    jit.move(subjectLength, A2);
    jit.loadPtr(Address(regExp, RegExp::offsetOfOvector() + FixedVector<int>::offsetOfStorage()), A3);
    jit.addPtr(TrustedImm32(FixedVector<int>::Storage::offsetOfData()), A3);
