    jit.move(sp, A4);
    jit.call(scratch, Yarr8BitPtrTag);
    jit.move(GPRInfo::returnValueGPR, scratch);
    jit.loadPtr(Address(sp, offsetOfSavedArguments), regExpObject);
    jit.loadPtr(Address(sp, offsetOfSavedArguments + sizeof(void*)), string);
