static void generateRegExpExecWithFastPath(CCallHelpers& jit) { generateRegExpMatchWithFastPath(jit, Entry::operationAOTTypedRegExpExec, Entry::operationAOTTypedRegExpExecFound, JSValue::encode(jsNull())); }

static void generateStringMatchRegExpWithFastPath(CCallHelpers& jit)
{
    constexpr GPRReg string = A1;
    constexpr GPRReg regExpObject = A2;
    constexpr GPRReg scratch = T9;
    constexpr GPRReg globalObject = T11;
    static_assert(noOverlap(string, regExpObject, scratch, globalObject));
    static_assert(sizeof(InlineWatchpointSet) == sizeof(uintptr_t));
    InlineWatchpointSet unwatchedSet(IsWatched);
    uintptr_t watchedSetWord;
    memcpy(&watchedSetWord, &unwatchedSet, sizeof(watchedSetWord));
    CCallHelpers::JumpList slowCases;
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfGlobalObject()), globalObject);
    jit.load64(Address(globalObject, OBJECT_OFFSETOF(JSGlobalObject, m_regExpPrimordialPropertiesWatchpointSet)), scratch);
    slowCases.append(jit.branch64(CCallHelpers::NotEqual, scratch, CCallHelpers::TrustedImm64(watchedSetWord)));
    jit.load64(Address(globalObject, OBJECT_OFFSETOF(JSGlobalObject, m_stringSymbolMatchWatchpointSet)), scratch);
    slowCases.append(jit.branch64(CCallHelpers::NotEqual, scratch, CCallHelpers::TrustedImm64(watchedSetWord)));
    jit.load32(Address(regExpObject, JSCell::structureIDOffset()), scratch);
    slowCases.append(jit.branch32(CCallHelpers::NotEqual, scratch, Address(globalObject, OBJECT_OFFSETOF(JSGlobalObject, m_regExpStructure))));
    jit.load64(Address(regExpObject, RegExpObject::offsetOfRegExpAndFlags()), scratch);
    jit.and64(TrustedImm32(static_cast<int32_t>(RegExpObject::regExpMask)), scratch);
    slowCases.append(jit.branchTest16(CCallHelpers::NonZero, Address(scratch, RegExp::offsetOfFlags()), TrustedImm32(static_cast<int32_t>(Yarr::Flags::Global))));
    jit.swap(string, regExpObject);
    jit.jump().linkTo(stubLabels()[static_cast<unsigned>(Stub::RegExpExecWithFastPath)], &jit);

    slowCases.link(&jit);
    jit.move(TrustedImm32(offsetInTable(Entry::operationAOTTypedStringMatchRegExp)), T9);
    generateOperation(jit, Returns::Value, Supplies::Instance);
}

