static void generateLookupCopyKeyOrder(CCallHelpers& jit, bool isLeaf)
{
    constexpr GPRReg result = GPRInfo::returnValueGPR;
    constexpr GPRReg words = T9;
    constexpr GPRReg site = T11;
    constexpr GPRReg entry = T12;
    constexpr GPRReg scratch = T13;
    static_assert(noOverlap(result, words, site, entry, scratch));
    static_assert(sizeof(Instance::CopyKeyOrderEntry) == 32);
    static_assert(Typed::shapeWordOf(1) >> 24 == 0xff);
    CCallHelpers::JumpList notRecord;
    jit.urshift64(words, TrustedImm32(56), entry);
    notRecord.append(jit.branch32(CCallHelpers::NotEqual, entry, TrustedImm32(0xff)));
    notRecord.append(jit.branchTest32(CCallHelpers::NonZero, words, TrustedImm32(Typed::orderWordHasExtraProperties)));
    jit.urshift64(words, TrustedImm32(32), entry);
    jit.xor32(words, entry);
    jit.urshift64(site, TrustedImm32(Instance::copyKeyOrderSiteShift), scratch);
    jit.xor32(scratch, entry);
    jit.mul32(TrustedImm32(static_cast<int32_t>(Instance::spreadCopyHashMultiplier)), entry, entry);
    jit.urshift32(TrustedImm32(Instance::copyKeyOrderHashShift), entry);
    jit.lshift32(TrustedImm32(5), entry);
    jit.addPtr(Address(instanceGPR, Instance::offsetOfCopyKeyOrderCache()), entry);
    CCallHelpers::JumpList isNotKnown;
    isNotKnown.append(jit.branch64(CCallHelpers::NotEqual, words, Address(entry, OBJECT_OFFSETOF(Instance::CopyKeyOrderEntry, sourceHeaderWords))));
    isNotKnown.append(jit.branchPtr(CCallHelpers::NotEqual, site, Address(entry, OBJECT_OFFSETOF(Instance::CopyKeyOrderEntry, site))));
    jit.load32(Address(entry, OBJECT_OFFSETOF(Instance::CopyKeyOrderEntry, orderWordAndSource)), result);
    returnToTypedCaller(jit, isLeaf);
    isNotKnown.link(&jit);
    jit.move(TrustedImm32(0), result);
    returnToTypedCaller(jit, isLeaf);
    notRecord.link(&jit);
    jit.move(TrustedImm32(Instance::copyAlwaysFails), result);
    returnToTypedCaller(jit, isLeaf);
}
static void generateLookupCopyKeyOrder(CCallHelpers& jit) { generateLookupCopyKeyOrder(jit, false); }
