static Vector<std::pair<Jump, unsigned>>& jumpsFromStubsToCallValue();

static void callGetter(CCallHelpers& jit, CCallHelpers::JumpList& cannot)
{
    {
        jit.loadPtr(Address(T12, GetterSetter::offsetOfGetterShortcut()), T13);
        Jump hasNoCode = jit.branchTestPtr(CCallHelpers::Zero, T13, TrustedImm32(GetterSetter::getterShortcutIsCode));
        static_assert(calleeGPR == T10);
        jit.loadPtr(Address(T12, GetterSetter::offsetOfGetter()), calleeGPR);
        jit.load32(Address(calleeGPR, JSCell::structureIDOffset()), T11);
        structureWithID(jit, T11);
        Jump belongsToThisInstance = jit.branchPtr(CCallHelpers::Equal, Address(T11, Structure::offsetOfAOTInstance()), instanceGPR);
        Jump belongsToAnotherInstance = jit.branchTestPtr(CCallHelpers::NonZero, Address(T11, Structure::offsetOfAOTInstance()));
        jit.loadPtr(Address(T11, Structure::realmOffset()), T11);
        Jump belongsToAnotherRealm = jit.branchPtr(CCallHelpers::NotEqual, Address(instanceGPR, Instance::offsetOfGlobalObject()), T11);
        belongsToThisInstance.link(&jit);
        checkStackBeforeCallingAccessor(jit);
        jit.move(R0, thisGPR);
        jit.subPtr(TrustedImm32(GetterSetter::getterShortcutIsCode), T13);
        jit.farJump(T13, JSEntryPtrTag);

        hasNoCode.link(&jit);
        Jump hasNoShortcut = jit.branchTestPtr(CCallHelpers::Zero, T13);
        CCallHelpers::JumpList useGetter;
        constexpr uint32_t shiftsByType = [] {
            uint32_t shifts = 0;
            for (unsigned i = 0; i < NumberOfTypedArrayTypesExcludingDataView; ++i)
                shifts |= logElementSize(static_cast<JSType>(FirstTypedArrayType + i)) << (2 * i);
            return shifts;
        }();
        static_assert(NumberOfTypedArrayTypesExcludingDataView <= 16);
        useGetter.append(jit.branchIfNotCell(R0));
        jit.load8(Address(R0, JSCell::typeInfoTypeOffset()), T11);
        jit.sub32(TrustedImm32(FirstTypedArrayType), T11);
        useGetter.append(jit.branch32(CCallHelpers::AboveOrEqual, T11, TrustedImm32(NumberOfTypedArrayTypesExcludingDataView)));
        useGetter.append(jit.branchTest8(CCallHelpers::NonZero, Address(R0, JSArrayBufferView::offsetOfMode()), TrustedImm32(resizabilityAndAutoLengthMask)));
        Jump returnsByteOffset = jit.branch64(CCallHelpers::Equal, T13, TrustedImm32(GetterSetter::getterReturnsTypedArrayByteOffset));
        jit.load64(Address(R0, JSArrayBufferView::offsetOfLength()), T13);
        useGetter.append(jit.branch64(CCallHelpers::Above, T13, TrustedImm32(std::numeric_limits<int32_t>::max() >> 3)));
        jit.lshift32(TrustedImm32(1), T11);
        jit.move(TrustedImm32(static_cast<int32_t>(shiftsByType)), T12);
        jit.urshift32(T11, T12);
        jit.and32(TrustedImm32(3), T12);
        jit.lshift64(T12, T13);
        jit.add64(numberTag, T13, R0);
        jit.ret();

        returnsByteOffset.link(&jit);
        jit.load64(Address(R0, JSArrayBufferView::offsetOfByteOffset()), T13);
        useGetter.append(jit.branch64(CCallHelpers::Above, T13, TrustedImm32(std::numeric_limits<int32_t>::max())));
        jit.add64(numberTag, T13, R0);
        jit.ret();

        useGetter.link(&jit);
        hasNoShortcut.link(&jit);
        belongsToAnotherInstance.link(&jit);
        belongsToAnotherRealm.link(&jit);
    }
    jit.loadPtr(Address(T12, GetterSetter::offsetOfGetter()), T12);
    {
        jit.loadPtr(Address(instanceGPR, Instance::offsetOfTypedArrayLengthGetter()), T13);
        Jump isDifferentGetter = jit.branchPtr(CCallHelpers::NotEqual, T12, T13);
        jit.load8(Address(R0, JSCell::typeInfoTypeOffset()), T13);
        jit.sub32(TrustedImm32(FirstTypedArrayType), T13);
        Jump isNotTypedArray = jit.branch32(CCallHelpers::AboveOrEqual, T13, TrustedImm32(NumberOfTypedArrayTypesExcludingDataView));
        jit.load8(Address(R0, JSArrayBufferView::offsetOfMode()), T13);
        Jump needsComputation = jit.branchTest32(CCallHelpers::NonZero, T13, TrustedImm32(resizabilityAndAutoLengthMask));
        jit.load64(Address(R0, JSArrayBufferView::offsetOfLength()), T13);
        Jump isTooLong = jit.branch64(CCallHelpers::Above, T13, CCallHelpers::TrustedImm64(std::numeric_limits<int32_t>::max()));
        jit.add64(numberTag, T13, R0);
        jit.ret();
        isDifferentGetter.link(&jit);
        isNotTypedArray.link(&jit);
        needsComputation.link(&jit);
        isTooLong.link(&jit);
    }
    {
        Jump isFunction = jit.branchTest8(CCallHelpers::NonZero, Address(T12, JSCell::typeInfoFlagsOffset()), TrustedImm32(TypeOfReturnsFunction));
        auto loadFunction = [&] {
            jit.load64(Address(R0, Typed::SlimClosure::offsetOfWord()), T12);
            jit.urshift64(TrustedImm32(ClosureWord::functionShift), T12);
            jit.and32(TrustedImm32(ClosureWord::functionMask), T12);
            jit.loadPtr(Address(instanceGPR, Instance::offsetOfTypedData()), T13);
        };
        auto markLazyPropertyRead = [&] {
            jit.load8(Address(R0, JSCell::typeInfoFlagsOffset()), T13);
            cannot.append(jit.branchTest32(CCallHelpers::NonZero, T13, TrustedImm32(TypeInfoPerCellBit)));
            jit.or32(TrustedImm32(TypeInfoPerCellBit), T13);
            jit.store8(T13, Address(R0, JSCell::typeInfoFlagsOffset()));
        };
        Jump isNotLength = jit.branchPtr(CCallHelpers::NotEqual, T12, Address(instanceGPR, Instance::offsetOfTypedSlimClosureLengthGetter()));
        markLazyPropertyRead();
        loadFunction();
        jit.load32(Address(T13, OBJECT_OFFSETOF(Typed::Data, functionLengthsOffset)), T11);
        jit.addPtr(T11, T13);
        if (s_functionLengthsAreBytes)
            jit.load8(CCallHelpers::BaseIndex(T13, T12, CCallHelpers::TimesOne), T13);
        else
            jit.load16(CCallHelpers::BaseIndex(T13, T12, CCallHelpers::TimesTwo), T13);
        jit.add64(numberTag, T13, R0);
        jit.ret();
        isNotLength.link(&jit);
        cannot.append(jit.branchPtr(CCallHelpers::NotEqual, T12, Address(instanceGPR, Instance::offsetOfTypedSlimClosureNameGetter())));
        markLazyPropertyRead();
        loadFunction();
        jit.load32(Address(T13, OBJECT_OFFSETOF(Typed::Data, functionsOffset)), T11);
        jit.addPtr(T11, T13);
        jit.load32(CCallHelpers::BaseIndex(T13, T12, CCallHelpers::TimesFour), lazyConstantKeyGPR);
        jit.add32(TrustedImm32(1), lazyConstantKeyGPR);
        s_callsBetweenStubs->append({ jit.nearTailCall(), Stub::TypedString });
        isFunction.link(&jit);
    }
    checkStackBeforeCallingAccessor(jit);
    jit.move(R0, thisGPR);
    jit.move(T12, calleeGPR);
    jumpsFromStubsToCallValue().append({ jit.jump(), 0u });
}

static void getFromMegamorphicCache(CCallHelpers& jit, GPRReg uid, CCallHelpers::JumpList& notFound, GPRReg untriedSlotData)
{
#if CPU(X86_64)
    constexpr GPRReg cache = T10;
    constexpr GPRReg result = T9;
#else
    constexpr GPRReg cache = GPRInfo::argumentGPR7;
    constexpr GPRReg result = GPRInfo::argumentGPR6;
#endif
    ASSERT(uid != cache && uid != result && uid != R0 && uid != A1);
    ASSERT(untriedSlotData == InvalidGPRReg || noOverlap(untriedSlotData, A1, cache, result, uid, T11, T12, T13));
    auto fillSlot = [&] {
        if (untriedSlotData == InvalidGPRReg)
            return;
        using Entry = MegamorphicCache::LoadEntry;
        Jump isNone = jit.branchTestPtr(CCallHelpers::Zero, untriedSlotData);
        CCallHelpers::JumpList operationSlowCases;
        {
            constexpr GPRReg location = T11;
            constexpr GPRReg pointer = T12;
            constexpr uint32_t firstInlineLocation = JSObject::offsetOfInlineStorage() / sizeof(EncodedJSValue);
            operationSlowCases.append(jit.branchTest32(CCallHelpers::NonZero, Address(A1, OBJECT_OFFSETOF(Slot, offset)), TrustedImm32(~Slot::attemptsMask)));
            jit.loadPtr(Address(T13, Entry::offsetOfHolder()), pointer);
            jit.load16(Address(T13, Entry::offsetOfOffset()), location);
            jit.load16(Address(T13, Entry::offsetOfEpoch()), cache);
            CCallHelpers::JumpList isReady;
            Jump isPermanent = jit.branch32(CCallHelpers::Equal, cache, TrustedImm32(MegamorphicCache::permanentEpoch));
            operationSlowCases.append(jit.branch64(CCallHelpers::NotEqual, pointer, TrustedImm32(static_cast<int32_t>(std::bit_cast<uintptr_t>(JSCell::seenMultipleCalleeObjects())))));
            Jump isOwnOutOfLine = jit.branch32(CCallHelpers::AboveOrEqual, location, TrustedImm32(firstOutOfLineOffset));
            jit.add32(TrustedImm32(firstInlineLocation), location);
            jit.move(uid, pointer);
            isReady.append(jit.jump());
            isOwnOutOfLine.link(&jit);
            jit.neg32(location);
            jit.add32(TrustedImm32(firstOutOfLineOffset - 2), location);
            jit.and32(TrustedImm32(Slot::offsetMask), location);
            jit.or32(TrustedImm32(Slot::isIndirect), location);
            jit.move(CCallHelpers::TrustedImmPtr(nullptr), pointer);
            isReady.append(jit.jump());
            isPermanent.link(&jit);
            Jump isPresent = jit.branchTestPtr(CCallHelpers::NonZero, pointer);
            loadInstance(jit, pointer);
            jit.loadPtr(Address(pointer, Instance::offsetOfRuntimeTable()), pointer);
            jit.loadPtr(Address(pointer, offsetInTable(AOT::Entry::UndefinedHolder)), pointer);
            jit.move(TrustedImm32(firstInlineLocation | Slot::isIndirect | Slot::pointerIsNotCell), location);
            isReady.append(jit.jump());

            isPresent.link(&jit);
            Jump isOutOfLine = jit.branch32(CCallHelpers::AboveOrEqual, location, TrustedImm32(firstOutOfLineOffset));
            jit.add32(TrustedImm32(firstInlineLocation), location);
            Jump isInLine = jit.jump();
            isOutOfLine.link(&jit);
            jit.neg32(location);
            jit.add32(TrustedImm32(firstOutOfLineOffset - 2), location);
            jit.and32(TrustedImm32(Slot::offsetMask), location);
            isInLine.link(&jit);
            jit.or32(TrustedImm32(Slot::isIndirect | Slot::pointerIsCell), location);

            isReady.link(&jit);
            Jump collectorNotNotified = jit.branchTest8(CCallHelpers::Zero, Address(untriedSlotData, Data::offsetOfHasBeenFilledSinceLastCollection() - BiasedDataPointer::bias));
            jit.store32(location, Address(A1, OBJECT_OFFSETOF(Slot, offset)));
            jit.storePtr(pointer, Address(A1, OBJECT_OFFSETOF(Slot, pointer)));
            jit.storeFence();
            jit.load32(Address(R0, JSCell::structureIDOffset()), T11);
            jit.store32(T11, Address(A1, OBJECT_OFFSETOF(Slot, structureID)));
            jit.add64(TrustedImm32(1), Address(untriedSlotData, Data::offsetOfSlotEpoch() - BiasedDataPointer::bias));
            operationSlowCases.append(jit.jump());
            collectorNotNotified.link(&jit);
            jit.move(result, R0);
            jit.emitFunctionPrologue();
#if CPU(ARM64)
            jit.pushPair(R0, A1);
#else
            jit.push(R0);
            jit.push(A1);
#endif
            jit.addPtr(TrustedImm32(-BiasedDataPointer::bias), untriedSlotData, A0);
            jit.loadPtr(Address(instanceGPR, Instance::offsetOfRuntimeTable()), T11);
            jit.loadPtr(Address(T11, offsetInTable(AOT::Entry::operationAOTDidFillSlots)), T11);
            jit.call(T11, OperationPtrTag);
#if CPU(ARM64)
            jit.popPair(R0, A1);
#else
            jit.pop(A1);
            jit.pop(R0);
#endif
            jit.emitFunctionEpilogue();
            jit.ret();
            operationSlowCases.link(&jit);
        }
        isNone.link(&jit);
    };
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfRuntimeTable()), cache);
    jit.loadPtr(Address(cache, offsetInTable(Entry::MegamorphicCache)), cache);
    notFound.append(jit.branchTestPtr(CCallHelpers::Zero, cache));
    CCallHelpers::JumpList notValue = jit.loadMegamorphicProperty(CCallHelpers::MegamorphicCacheLocation(cache), R0, uid, nullptr, result, T11, T12, T13);
    fillSlot();
    jit.move(result, R0);
    jit.ret();
    notValue.link(&jit);
    notFound.append(jit.loadMegamorphicGetterSetter(CCallHelpers::MegamorphicCacheLocation(cache), R0, uid, nullptr, result, T11, T12, T13));
    jit.move(result, T12);
    callGetter(jit, notFound);
}

static void generateGetByIdWith(CCallHelpers&, Entry, bool isCalledByThunk = false);
static void callLookUp(CCallHelpers&, Entry, GPRReg base, GPRReg name = InvalidGPRReg);

static void callLookUpAtSite(CCallHelpers& jit, Entry operation, GPRReg base, GPRReg name, GPRReg third)
{
    ASSERT(noOverlap(name, third, R0, A1) && third != A0 && third != A2 && name != A0);
    jit.emitFunctionPrologue();
#if CPU(ARM64)
    jit.pushPair(R0, A1);
#else
    jit.push(R0);
    jit.push(A1);
#endif
    jit.move(name, A1);
    jit.move(third, A2);
    jit.move(R0, A0);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfRuntimeTable()), T11);
    jit.loadPtr(Address(T11, offsetInTable(operation)), T11);
    jit.call(T11, OperationPtrTag);
#if CPU(ARM64)
    jit.popPair(base, A1);
#else
    jit.pop(A1);
    jit.pop(base);
#endif
    jit.emitFunctionEpilogue();
}

static void readExport(CCallHelpers& jit, GPRReg nameSpace)
{
    checkStackBeforeCallingAccessor(jit);
    jit.zeroExtend32ToWord(R0, T13);
    jit.loadPtr(Address(nameSpace, Typed::ModuleNamespace::offsetOfRead()), calleeGPR);
    jit.add64(numberTag, T13, argumentGPR(0));
    jit.move(CCallHelpers::TrustedImm64(JSValue::ValueUndefined), thisGPR);
    jit.move(TrustedImm32(1), countGPR);
    jit.jump().linkTo(variadicCallCellLabel(), &jit);
}

static void lookUpInMegamorphicCache(CCallHelpers& jit, GPRReg uid, CCallHelpers::JumpList& hasPair, CCallHelpers::JumpList& hasNoPair)
{
#if CPU(X86_64)
    constexpr GPRReg cache = T10;
    constexpr GPRReg result = T9;
#else
    constexpr GPRReg cache = GPRInfo::argumentGPR7;
    constexpr GPRReg result = GPRInfo::argumentGPR6;
#endif
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfRuntimeTable()), cache);
    jit.loadPtr(Address(cache, offsetInTable(Entry::MegamorphicCache)), cache);
    hasNoPair.append(jit.branchTestPtr(CCallHelpers::Zero, cache));
    hasNoPair.append(jit.loadMegamorphicProperty(CCallHelpers::MegamorphicCacheLocation(cache), R0, uid, nullptr, result, T11, T12, T13));
    hasPair.append(jit.jump());
}
struct GetByIdContinuations {
    CCallHelpers::Label isIndirect;
    CCallHelpers::Label hasDifferentStructure;
    CCallHelpers::Label hasDifferentStructureAndIsIndirect;
    CCallHelpers::Label isNotNamed;
    CCallHelpers::Label miss;
};
static GetByIdContinuations& getByIdContinuations(Entry operation)
{
    static NeverDestroyed<std::array<GetByIdContinuations, 2>> continuations;
    return continuations.get()[operation == Entry::operationAOTGetByIdWellKnown];
}

static void readByName(CCallHelpers& jit, GPRReg base, CCallHelpers::JumpList& isIndirect, CCallHelpers::JumpList& isNotNamed)
{
    ASSERT(base != T9 && base != T11 && base != T12 && base != T13 && base != T14);
    isIndirect.append(branchIfSlotHas<Slot::isIndirect>(jit, T11));
    jit.urshift64(T11, TrustedImm32(32 + Slot::nameIDShift), T13);
#if CPU(X86_64)
    isNotNamed.append(Jump(jit.m_assembler.jCC(X86Assembler::ConditionE)));
#else
    isNotNamed.append(jit.branchTest64(CCallHelpers::Zero, T13));
#endif
    loadDirectLocation(jit, A1, T11, T14);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfFieldIDAtDirectLocationBase()), T9);
    jit.add64(T12, T9);
    jit.load16(CCallHelpers::BaseIndex(T9, T14, CCallHelpers::TimesTwo), T9);
    isNotNamed.append(jit.branch32(CCallHelpers::NotEqual, T9, T13));
    jit.load64(CCallHelpers::BaseIndex(base, T14, CCallHelpers::TimesEight), R0);
    jit.ret();
}

static void findOffsetByNameAndStructure(CCallHelpers& jit, GPRReg name, GPRReg row, GPRReg displacement, GPRReg place, CCallHelpers::JumpList& hasNoDescriptor, CCallHelpers::JumpList& nameIsMissing)
{
    ASSERT(noOverlap(R0, name, row, displacement, place));
    jit.load32(Address(R0, JSCell::structureIDOffset()), row);
    structureWithID(jit, row);
    jit.load16(Address(row, Structure::offsetOfStructureDescriptorPlusOne()), row);
    hasNoDescriptor.append(jit.branchTest32(CCallHelpers::Zero, row));
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfNameDisplacements()), place);
    jit.load32(CCallHelpers::BaseIndex(place, name, CCallHelpers::TimesFour), displacement);
    Jump isLiteral = jit.branch32(CCallHelpers::Below, row, Address(instanceGPR, Instance::offsetOfFirstThisStructureDescriptorPlusOne()));
    jit.or32(TrustedImm32(Typed::Data::nameIsOnObjectPrototype), displacement);
    isLiteral.link(&jit);
    jit.and32(TrustedImm32(~Typed::Data::nameIsOnObjectPrototype), displacement, place);
    jit.add32(row, place);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfOffsetsByNameAndStructure()), row);
    jit.load32(CCallHelpers::BaseIndex(row, place, CCallHelpers::TimesFour), place);
    jit.urshift32(place, TrustedImm32(8), row);
    nameIsMissing.append(jit.branch32(CCallHelpers::NotEqual, row, name));
    jit.and32(TrustedImm32(0xff), place);
}

static void readByNameAndStructure(CCallHelpers& jit, GPRReg name, GPRReg row, GPRReg displacement, GPRReg place, CCallHelpers::JumpList& hasNoDescriptor)
{
    CCallHelpers::JumpList nameIsMissing;
    findOffsetByNameAndStructure(jit, name, row, displacement, place, hasNoDescriptor, nameIsMissing);
    jit.load64(CCallHelpers::BaseIndex(R0, place, CCallHelpers::TimesEight, JSObject::offsetOfInlineStorage()), place);
    hasNoDescriptor.append(jit.branchTest64(CCallHelpers::Zero, place));
    jit.move(place, R0);
    jit.ret();
    nameIsMissing.link(&jit);
    hasNoDescriptor.append(jit.branchTest32(CCallHelpers::NonZero, displacement, TrustedImm32(Typed::Data::nameIsOnObjectPrototype)));
    jit.move(CCallHelpers::TrustedImm64(JSValue::ValueUndefined), R0);
    jit.ret();
}

static void generateTryGetByNameAndStructure(CCallHelpers& jit)
{
    CCallHelpers::JumpList cannot;
    cannot.append(jit.branchIfNotCell(R0));
    cannot.append(jit.branchIfNotObject(R0));
    readByNameAndStructure(jit, A1, T11, T13, T10, cannot);
    cannot.link(&jit);
    jit.move(TrustedImm32(0), R0);
    jit.ret();
}

static void generateGetByNameUncached(CCallHelpers& jit)
{
    constexpr GPRReg string = A1;
    constexpr GPRReg name = T12;
    static_assert(noOverlap(R0, string, name, T10, T11, T13));
    CCallHelpers::JumpList cannot;
    cannot.append(jit.branchIfNotCell(R0));
    cannot.append(jit.branchIfNotObject(R0));
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfTypedData()), T11);
    jit.load32(Address(T11, OBJECT_OFFSETOF(Typed::Data, stringFactsOffset)), T10);
    jit.addPtr(T11, T10);
    jit.load32(CCallHelpers::BaseIndex(T10, string, CCallHelpers::TimesFour), name);
    jit.and32(TrustedImm32(Typed::Data::stringHashMask), name);
    readByNameAndStructure(jit, name, T11, T13, T10, cannot);
    cannot.link(&jit);
    jit.move(string, A2);
    jit.move(R0, A1);
    jit.move(instanceGPR, A0);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfRuntimeTable()), T11);
    jit.loadPtr(Address(T11, offsetInTable(Entry::operationAOTTypedGetByName)), T11);
    callAndCheckException(jit, T11, Returns::Value);
}

static CCallHelpers::Label returnAfterStoring(CCallHelpers&, GPRReg value);

static void generateTryPutByNameAndStructure(CCallHelpers& jit)
{
    CCallHelpers::JumpList cannot;
    cannot.append(jit.branchIfNotCell(R0));
    cannot.append(jit.branchIfNotObject(R0));
    findOffsetByNameAndStructure(jit, A2, T11, T13, T10, cannot, cannot);
    jit.store64(A1, CCallHelpers::BaseIndex(R0, T10, CCallHelpers::TimesEight, JSObject::offsetOfInlineStorage()));
    returnAfterStoring(jit, A1);
    cannot.link(&jit);
    jit.move(TrustedImm32(0), R0);
    jit.ret();
}

static void generatePutByNameUncached(CCallHelpers& jit, Entry operation)
{
    constexpr GPRReg string = A2;
    constexpr GPRReg name = T12;
    static_assert(noOverlap(R0, A1, string, name, T10, T11, T13));
    CCallHelpers::JumpList cannot;
    cannot.append(jit.branchIfNotCell(R0));
    cannot.append(jit.branchIfNotObject(R0));
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfTypedData()), T11);
    jit.load32(Address(T11, OBJECT_OFFSETOF(Typed::Data, stringFactsOffset)), T10);
    jit.addPtr(T11, T10);
    jit.load32(CCallHelpers::BaseIndex(T10, string, CCallHelpers::TimesFour), name);
    jit.and32(TrustedImm32(Typed::Data::stringHashMask), name);
    findOffsetByNameAndStructure(jit, name, T11, T13, T10, cannot, cannot);
    jit.store64(A1, CCallHelpers::BaseIndex(R0, T10, CCallHelpers::TimesEight, JSObject::offsetOfInlineStorage()));
    returnAfterStoring(jit, A1);
    cannot.link(&jit);
    jit.move(A1, A3);
    jit.move(R0, A1);
    jit.move(instanceGPR, A0);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfRuntimeTable()), T11);
    jit.loadPtr(Address(T11, offsetInTable(operation)), T11);
    callAndCheckException(jit, T11, Returns::Void);
}
static void generatePutByNameUncached(CCallHelpers& jit) { generatePutByNameUncached(jit, Entry::operationAOTTypedSetByName); }
static void generatePutByNameUncachedSloppy(CCallHelpers& jit) { generatePutByNameUncached(jit, Entry::operationAOTTypedSetByNameSloppy); }

static void generateGetById(CCallHelpers& jit) { generateGetByIdWith(jit, Entry::operationAOTGetById); }

static void findNamedField(CCallHelpers& jit, ptrdiff_t offsetOfTable, GPRReg access, CCallHelpers::JumpList& isMissing, bool isKnownToBeObjectType = false)
{
    ASSERT(access == T12 || access == T13);
    if (!isKnownToBeObjectType)
        isMissing.append(jit.branch8(CCallHelpers::NotEqual, Address(R0, JSCell::typeInfoTypeOffset()), TrustedImm32(ObjectType)));
    jit.load32(Address(R0, Typed::offsetOfShapeWord), T11);
    jit.lshift32(T11, TrustedImm32(Instance::namedFieldShapeShift), T13);
    jit.add32(T12, T13);
    jit.and32(TrustedImm32(Instance::numberOfNamedFields - 1), T13);
    jit.lshiftPtr(TrustedImm32(4), T13);
    jit.loadPtr(Address(instanceGPR, offsetOfTable), T10);
    jit.addPtr(T10, T13);
    jit.lshift64(T12, TrustedImm32(32), T10);
    jit.or64(T10, T11);
    isMissing.append(jit.branch64(CCallHelpers::NotEqual, Address(T13, OBJECT_OFFSETOF(Instance::NamedField, shapeWordAndName)), T11));
    jit.load64(Address(T13, OBJECT_OFFSETOF(Instance::NamedField, access)), access);
}

static CCallHelpers::JumpList* s_readsAwaitingTypedEnd;

static void returnFromRead(CCallHelpers& jit)
{
    if (s_readsAwaitingTypedEnd)
        s_readsAwaitingTypedEnd->append(jit.jump());
    else
        jit.ret();
}

static void readCompiledField(CCallHelpers& jit, CCallHelpers::JumpList& rare, CCallHelpers::JumpList* isNotField = nullptr, bool absentFieldIsRare = false)
{
    using FieldRead = Slot::FieldRead;
    constexpr GPRReg address = T11;
    constexpr GPRReg value = T13;
    auto hasBit = [&](unsigned bit) {
#if CPU(X86_64)
        return jit.branchTestBit64(CCallHelpers::NonZero, T12, TrustedImm32(Slot::fieldReadShift + bit));
#else
        return jit.branchTest64(CCallHelpers::NonZero, T12, CCallHelpers::TrustedImm64(1ll << (Slot::fieldReadShift + bit)));
#endif
    };
    auto returnValue = [&] {
        jit.move(value, R0);
        returnFromRead(jit);
    };
    auto returnInt32 = [&] {
#if CPU(ARM64)
        jit.addZeroExtend64(numberTag, value, R0);
#else
        jit.zeroExtend32ToWord(value, R0);
        jit.add64(numberTag, R0);
#endif
        returnFromRead(jit);
    };
    auto returnDoubleBits = [&] {
#if CPU(ARM64)
        jit.sub64(value, numberTag, R0);
        returnFromRead(jit);
#else
        jit.sub64(numberTag, value);
        returnValue();
#endif
    };
    CCallHelpers::JumpList isAbsent;
    CCallHelpers::JumpList isUndefined;
    CCallHelpers::JumpList isNull;
    static_assert(Slot::fieldIsInExtension == 1ull << (Slot::fieldReadShift + 4));
    Jump isInExtension = hasBit(4);
#if CPU(ARM64)
    jit.addZeroExtend64(R0, T12, address);
#else
    jit.zeroExtend32ToWord(T12, address);
    jit.addPtr(R0, address);
#endif
    CCallHelpers::Label hasAddress = jit.label();
    Jump isInUpperFour = hasBit(2);
    {
        Jump isInUpperTwo = hasBit(1);
        Jump isCell32 = hasBit(0);
        static_assert(!static_cast<unsigned>(FieldRead::Boxed));
        jit.load64(Address(address), value);
        isAbsent.append(jit.branchTest64(CCallHelpers::Zero, value));
        returnValue();

        static_assert(static_cast<unsigned>(FieldRead::Cell32) == 1);
        isCell32.link(&jit);
        jit.load32(Address(address), value);
        Jump notCell = jit.branch32(CCallHelpers::Below, value, TrustedImm32(Typed::minCell32));
#if CPU(ARM64)
        decodeCell32(jit, value, R0);
        returnFromRead(jit);
#else
        decodeCell32(jit, value, value);
        returnValue();
#endif
        notCell.link(&jit);
        Jump isLiteralString = jit.branch32(CCallHelpers::Above, value, TrustedImm32(Typed::undefinedCell32));
        static_assert(!Typed::absentCell32);
        isAbsent.append(jit.branchTest32(CCallHelpers::Zero, value));
        Jump isUnmaterializedClosure = jit.branch32(CCallHelpers::Equal, value, TrustedImm32(Typed::unmaterializedClosureCell32));
        returnValue();

        isUnmaterializedClosure.link(&jit);
        auto loadClosureHeader = [&](GPRReg header) {
            jit.urshift64(T12, TrustedImm32(Slot::fieldClosureKindShift), header);
            jit.and32(TrustedImm32(1), header);
            jit.load64(CCallHelpers::BaseIndex(instanceGPR, header, CCallHelpers::TimesEight, Instance::offsetOfTypedSlimClosureHeader(0)), header);
        };
        rare.append(jit.branchTest64(CCallHelpers::Zero, T12, CCallHelpers::TrustedImm64(static_cast<int64_t>(Slot::fieldHoldsLazyClosure))));
        jit.load8(Address(R0, JSCell::cellStateOffset()), value);
        rare.append(jit.branch32(CCallHelpers::BelowOrEqual, value, Address(instanceGPR, Instance::offsetOfBarrierThreshold())));
        loadClosureHeader(value);
        rare.append(jit.branchTest64(CCallHelpers::Zero, value));
        static_assert(Slot::fieldClosureCapturesHolder == 1ull << 63);
        Jump capturesHolder = jit.branchTest64(CCallHelpers::Signed, T12, T12);
        for (unsigned numberOfCaptures = 0; numberOfCaptures < 2; ++numberOfCaptures) {
            if (numberOfCaptures)
                capturesHolder.link(&jit);
            jit.loadPtr(Address(instanceGPR, Instance::offsetOfTypedSlimClosureAllocator(numberOfCaptures)), address);
            rare.append(jit.branchTestPtr(CCallHelpers::Zero, address));
            CCallHelpers::JumpList cannotAllocate;
#if CPU(X86_64)
            jit.push(T12);
#else
            jit.pushToSave(T12);
#endif
            jit.emitAllocateWithNonNullAllocator(value, JITAllocator::variable(), address, T12, cannotAllocate, CCallHelpers::SlowAllocationResult::UndefinedBehavior);
#if CPU(X86_64)
            jit.pop(T12);
#else
            jit.popToRestore(T12);
#endif
            loadClosureHeader(address);
            jit.store64(address, Address(value, 0));
            if (numberOfCaptures)
                jit.store64(R0, Address(value, Typed::SlimClosure::offsetOfCaptures()));
            jit.zeroExtend32ToWord(T12, address);
            jit.addPtr(address, R0);
            jit.urshift64(TrustedImm32(Slot::fieldClosureShift), T12);
            jit.and32(TrustedImm32(ClosureWord::functionMask), T12);
            jit.loadPtr(Address(instanceGPR, Instance::offsetOfTypedFunctions()), address);
            jit.load64(CCallHelpers::BaseIndex(address, T12, CCallHelpers::TimesEight), address);
            jit.store64(address, Address(value, Typed::SlimClosure::offsetOfWord()));
            fenceAfterAllocation(jit, address);
            encodeCell32(jit, value, address);
            jit.store32(address, Address(R0));
            returnValue();
            cannotAllocate.link(&jit);
#if CPU(X86_64)
            jit.pop(T12);
#else
            jit.popToRestore(T12);
#endif
            rare.append(jit.jump());
        }
        isLiteralString.link(&jit);
        static_assert(2 << Typed::literalStringShift == sizeof(JSCell*));
        jit.loadPtr(Address(instanceGPR, Instance::offsetOfTypedLiteralStrings()), address);
        jit.load64(CCallHelpers::BaseIndex(address, value, CCallHelpers::TimesTwo, -2 * static_cast<int32_t>(Typed::emptyLiteralStringWord)), value);
        rare.append(jit.branchTest64(CCallHelpers::Zero, value));
        returnValue();

        isInUpperTwo.link(&jit);
        jit.load32(Address(address), value);
        Jump isInt32 = hasBit(0);
        static_assert(static_cast<unsigned>(FieldRead::Int32OrNumberBox) == 2 && static_cast<unsigned>(FieldRead::Int32) == 3);
#if CPU(ARM64)
        static_assert(Typed::minInlineInt32 == -(1 << 30));
        jit.m_assembler.bic<32, ARM64Assembler::S>(ARM64Registers::zr, value, value, ARM64Assembler::LSL, 1);
        Jump notInlineNumber = jit.branchOnFlags(CCallHelpers::LessThan);
#else
        Jump notInlineNumber = jit.branch32(CCallHelpers::LessThan, value, TrustedImm32(Typed::minInlineInt32));
#endif
        isInt32.link(&jit);
        returnInt32();
        notInlineNumber.link(&jit);
        isAbsent.append(jit.branch32(CCallHelpers::Equal, value, TrustedImm32(Typed::absentInt32)));
        isUndefined.append(jit.branch32(CCallHelpers::Equal, value, TrustedImm32(Typed::undefinedInt32)));
        isNull.append(jit.branch32(CCallHelpers::Equal, value, TrustedImm32(Typed::nullInt32)));
        jit.and32(TrustedImm32(INT32_MAX), value);
        jit.lshift64(TrustedImm32(Typed::numberBoxShift), value);
        jit.add64(Address(instanceGPR, Instance::offsetOfNumberBoxBase()), value);
        jit.loadDouble(Address(value), FPRInfo::fpRegT0);
        rare.append(jit.branchIfNaN(FPRInfo::fpRegT0));
        CCallHelpers::JumpList notInt32;
        branchIfNotExactInt32(jit, FPRInfo::fpRegT0, value, notInt32, FPRInfo::fpRegT1);
        returnInt32();
        notInt32.link(&jit);
        jit.moveDoubleTo64(FPRInfo::fpRegT0, value);
        returnDoubleBits();
    }
    isInUpperFour.link(&jit);
    Jump isInLastTwo = hasBit(1);
    {
        Jump isBoolean = hasBit(0);
        static_assert(static_cast<unsigned>(FieldRead::Double) == 4);
        jit.loadDouble(Address(address), FPRInfo::fpRegT0);
        Jump isNaN = jit.branchIfNaN(FPRInfo::fpRegT0);
        CCallHelpers::JumpList notInt32;
        branchIfNotExactInt32(jit, FPRInfo::fpRegT0, value, notInt32, FPRInfo::fpRegT1);
        returnInt32();
        notInt32.link(&jit);
        jit.moveDoubleTo64(FPRInfo::fpRegT0, value);
        returnDoubleBits();
        isNaN.link(&jit);
        jit.moveDoubleTo64(FPRInfo::fpRegT0, value);
        isAbsent.append(jit.branch64(CCallHelpers::Equal, value, CCallHelpers::TrustedImm64(static_cast<int64_t>(Typed::absentDouble))));
        isUndefined.append(jit.branch64(CCallHelpers::Equal, value, CCallHelpers::TrustedImm64(static_cast<int64_t>(Typed::undefinedDouble))));
        isNull.append(jit.branch64(CCallHelpers::Equal, value, CCallHelpers::TrustedImm64(static_cast<int64_t>(Typed::nullDouble))));
        rare.append(jit.jump());

        static_assert(static_cast<unsigned>(FieldRead::Boolean) == 5);
        isBoolean.link(&jit);
        jit.load8(Address(address), value);
#if CPU(ARM64)
        jit.or32(TrustedImm32(JSValue::ValueFalse), value, R0);
        returnFromRead(jit);
#else
        jit.or32(TrustedImm32(JSValue::ValueFalse), value);
        returnValue();
#endif
    }
    isInLastTwo.link(&jit);
    Jump isInt64 = hasBit(0);
    static_assert(static_cast<unsigned>(FieldRead::OptionalBoolean) == 6);
    jit.load8(Address(address), value);
    isAbsent.append(jit.branchTest32(CCallHelpers::Zero, value));
    returnValue();

    static_assert(static_cast<unsigned>(FieldRead::Int64) == 7);
    isInt64.link(&jit);
    jit.load64(Address(address), value);
    jit.signExtend32ToPtr(value, address);
    Jump exceedsInt32 = jit.branch64(CCallHelpers::NotEqual, value, address);
    returnInt32();
    exceedsInt32.link(&jit);
    isAbsent.append(jit.branch64(CCallHelpers::Equal, value, CCallHelpers::TrustedImm64(Typed::absentInteger)));
    isUndefined.append(jit.branch64(CCallHelpers::Equal, value, CCallHelpers::TrustedImm64(Typed::undefinedInteger)));
    isNull.append(jit.branch64(CCallHelpers::Equal, value, CCallHelpers::TrustedImm64(Typed::nullInteger)));
    rare.append(jit.jump());

    isInExtension.link(&jit);
    static_assert(static_cast<unsigned>(FieldRead::Uint8) == 0x30 && static_cast<unsigned>(FieldRead::Uint32) == 0x34);
    Jump isNarrow = hasBit(5);
    jit.load32(Address(R0, Typed::offsetOfExtension), address);
    isAbsent.append(jit.branchTest32(CCallHelpers::Zero, address));
    decodeCell32(jit, address, address);
    jit.load32(Address(address, Typed::offsetOfExtensionSize), value);
    isAbsent.append(jit.branch32(CCallHelpers::BelowOrEqual, value, T12));
    jit.zeroExtend32ToWord(T12, value);
    jit.addPtr(value, address);
    jit.jump().linkTo(hasAddress, &jit);

    isAbsent.link(&jit);
    if (absentFieldIsRare)
        rare.append(jit.jump());
    else
        rare.append(jit.branchTest64(CCallHelpers::Zero, T12, CCallHelpers::TrustedImm64(static_cast<int64_t>(Slot::absentFieldIsUndefined))));
    isUndefined.link(&jit);
    jit.move(CCallHelpers::TrustedImm64(JSValue::ValueUndefined), R0);
    returnFromRead(jit);
    isNull.link(&jit);
    jit.move(CCallHelpers::TrustedImm64(JSValue::ValueNull), R0);
    returnFromRead(jit);

    isNarrow.link(&jit);
    Jump isUint32 = hasBit(2);
    jit.zeroExtend32ToWord(T12, address);
    jit.addPtr(R0, address);
    Jump hasTwoBytes = hasBit(1);
    Jump isInt8 = hasBit(0);
    jit.load8(Address(address), value);
    returnInt32();
    isInt8.link(&jit);
    jit.load8SignedExtendTo32(Address(address), value);
    returnInt32();
    hasTwoBytes.link(&jit);
    Jump isInt16 = hasBit(0);
    jit.load16(Address(address), value);
    returnInt32();
    isInt16.link(&jit);
    jit.load16SignedExtendTo32(Address(address), value);
    returnInt32();
    isUint32.link(&jit);
    static_assert(static_cast<unsigned>(FieldRead::NoField) == 0x37);
    (isNotField ? *isNotField : rare).append(hasBit(1));
    jit.zeroExtend32ToWord(T12, address);
    jit.addPtr(R0, address);
    jit.load32(Address(address), value);
    Jump notInt32 = jit.branch32(CCallHelpers::LessThan, value, TrustedImm32(0));
    returnInt32();
    notInt32.link(&jit);
    jit.convertInt64ToDouble(value, FPRInfo::fpRegT0);
    jit.moveDoubleTo64(FPRInfo::fpRegT0, value);
    returnDoubleBits();
}

static void loadExtraPropertiesHandleAt(CCallHelpers& jit, GPRReg numberAndScratch, GPRReg result)
{
    using Handles = Typed::ExtraPropertiesHandleTable;
    static_assert(sizeof(Typed::ExtraPropertiesHandle) == 3 * sizeof(void*));
    RELEASE_ASSERT(numberAndScratch != result);
    jit.urshift32(numberAndScratch, TrustedImm32(Handles::segmentIndexBits), result);
    jit.lshift64(TrustedImm32(3), result);
    jit.addPtr(Address(instanceGPR, Instance::offsetOfTypedExtraPropertiesHandleSegments()), result);
    jit.loadPtr(Address(result), result);
    jit.and32(TrustedImm32(Handles::handlesPerSegment - 1), numberAndScratch);
    jit.getEffectiveAddress(CCallHelpers::BaseIndex(numberAndScratch, numberAndScratch, CCallHelpers::TimesTwo), numberAndScratch);
    jit.getEffectiveAddress(CCallHelpers::BaseIndex(result, numberAndScratch, CCallHelpers::TimesEight), result);
}

static void loadExtraPropertiesViaHandle(CCallHelpers& jit, GPRReg object, GPRReg result, GPRReg scratch, CCallHelpers::JumpList& hasNoNumber)
{
    jit.load32(Address(object, Typed::offsetOfOrderWord), scratch);
    jit.and32(TrustedImm32(Typed::orderAndCountMask), scratch);
    loadExtraPropertiesHandleAt(jit, scratch, result);
    jit.loadPtr(Address(result, OBJECT_OFFSETOF(Typed::ExtraPropertiesHandle, extraProperties)), result);
    hasNoNumber.append(jit.branchTestPtr(CCallHelpers::Zero, result));
}

static void loadExtraPropertiesOf(CCallHelpers& jit, GPRReg object, GPRReg result, GPRReg scratch, CCallHelpers::JumpList& hasNone)
{
    jit.load32(Address(object, JSCell::structureIDOffset()), result);
    structureWithID(jit, result);
    hasNone.append(jit.branchTest8(CCallHelpers::Zero, Address(result, JSCell::indexingTypeAndMiscOffset()), TrustedImm32(Structure::isStructureWithExtraProperties)));
    jit.load16(Address(result, Structure::offsetOfExtraPropertiesOffset()), result);
    Jump extraPropertiesViaHandle = jit.branchTest32(CCallHelpers::Zero, result);
    jit.load32(CCallHelpers::BaseIndex(object, result, CCallHelpers::TimesOne), result);
    decodeCell32(jit, result, result);
    Jump areLoaded = jit.jump();
    extraPropertiesViaHandle.link(&jit);
    loadExtraPropertiesViaHandle(jit, object, result, scratch, hasNone);
    areLoaded.link(&jit);
}

static void readExtraProperty(CCallHelpers& jit, CCallHelpers::JumpList& isNotKnown)
{
    constexpr GPRReg offsetAndKind = T13;
    constexpr GPRReg extraProperties = T11;
    static_assert(noOverlap(offsetAndKind, extraProperties, T12, R0, A1, instanceGPR));
    static_assert(static_cast<unsigned>(Slot::FieldRead::NoField) == (static_cast<unsigned>(Slot::FieldRead::KnownCustomGetter) | 1));
#if CPU(X86_64)
    Jump kindDiffers = jit.branchTestBit64(CCallHelpers::Zero, T12, TrustedImm32(Slot::fieldReadShift));
#else
    Jump kindDiffers = jit.branchTest64(CCallHelpers::Zero, T12, CCallHelpers::TrustedImm64(1ll << Slot::fieldReadShift));
#endif
    jit.urshift64(T12, TrustedImm32(Slot::extraPropertyShift), offsetAndKind);
    isNotKnown.append(jit.branchTestPtr(CCallHelpers::Zero, offsetAndKind));
    loadExtraPropertiesOf(jit, R0, extraProperties, offsetAndKind, isNotKnown);
    jit.urshift64(T12, TrustedImm32(Slot::extraPropertyShift), offsetAndKind);
    isNotKnown.append(jit.branch32(CCallHelpers::NotEqual, Address(extraProperties, JSCell::structureIDOffset()), T12));
    Jump notInlineAccessor = jit.branchTest32(CCallHelpers::NonZero, offsetAndKind, TrustedImm32(static_cast<int32_t>(~Slot::extraPropertyOffsetMask)));
    jit.loadPtr(CCallHelpers::BaseIndex(extraProperties, offsetAndKind, CCallHelpers::TimesOne), T12);
    callGetter(jit, isNotKnown);

    notInlineAccessor.link(&jit);
    Jump isAbsent = jit.branchTest32(CCallHelpers::NonZero, offsetAndKind, TrustedImm32(static_cast<int32_t>(Slot::extraPropertyIsAbsent)));
    jit.and32(TrustedImm32(static_cast<int32_t>(Slot::extraPropertyOffsetMask)), offsetAndKind, T12);
    Jump isInLine = jit.branchTest32(CCallHelpers::Zero, offsetAndKind, TrustedImm32(static_cast<int32_t>(Slot::extraPropertyIsOutOfLine)));
    jit.loadPtr(Address(extraProperties, JSObject::butterflyOffset()), extraProperties);
    jit.neg64(T12);
    isInLine.link(&jit);
    jit.loadPtr(CCallHelpers::BaseIndex(extraProperties, T12, CCallHelpers::TimesOne), T12);
    Jump isValue = jit.branchTest32(CCallHelpers::NonZero, offsetAndKind, TrustedImm32(static_cast<int32_t>(Slot::extraPropertyIsValue)));
    callGetter(jit, isNotKnown);
    isValue.link(&jit);
    jit.move(T12, R0);
    jit.ret();
    isAbsent.link(&jit);
    jit.move(CCallHelpers::TrustedImm64(JSValue::ValueUndefined), R0);
    jit.ret();
    kindDiffers.link(&jit);
}

enum class ChecksEpoch : bool { No, Yes };
static void callKnownCustomGetter(CCallHelpers& jit, CCallHelpers::JumpList& isNotKnown, bool callerIsThunk, ChecksEpoch checksEpoch = ChecksEpoch::Yes)
{
    using Known = Instance::CustomGetter;
    constexpr GPRReg known = T13;
    static_assert(noOverlap(known, T11, R0, A1, A2) && noOverlap(known, T11, A0, A1, A2));
    static_assert(static_cast<unsigned>(Slot::FieldRead::NoField) == (static_cast<unsigned>(Slot::FieldRead::KnownCustomGetter) | 1));
#if CPU(X86_64)
    isNotKnown.append(jit.branchTestBit64(CCallHelpers::NonZero, T12, TrustedImm32(Slot::fieldReadShift)));
#else
    isNotKnown.append(jit.branchTest64(CCallHelpers::NonZero, T12, CCallHelpers::TrustedImm64(1ll << Slot::fieldReadShift)));
#endif
    jit.urshift64(T12, TrustedImm32(Slot::customGetterIndexShift), known);
    jit.addPtr(Address(instanceGPR, Instance::offsetOfCustomGetters()), known);
    isNotKnown.append(jit.branch32(CCallHelpers::NotEqual, Address(known, OBJECT_OFFSETOF(Known, serial)), T12));
    if (checksEpoch == ChecksEpoch::Yes) {
        jit.load32(Address(instanceGPR, Instance::offsetOfMegamorphicCacheEpoch()), T11);
        jit.load16(Address(known, OBJECT_OFFSETOF(Known, epoch)), T12);
        isNotKnown.append(jit.branch32(CCallHelpers::NotEqual, T11, T12));
    }

    if (callerIsThunk) {
#if CPU(ARM64)
        jit.pushToSave(CCallHelpers::linkRegister);
#else
        jit.subPtr(TrustedImm32(sizeof(CPURegister)), CCallHelpers::stackPointerRegister);
#endif
    } else
        jit.emitFunctionPrologue();
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfVM()), T11);
    jit.storePtr(GPRInfo::callFrameRegister, Address(T11, VM::offsetOfTopCallFrame()));
    jit.loadPtr(Address(known, OBJECT_OFFSETOF(Known, passedForReceiver)), A1);
    jit.moveConditionallyTest64(CCallHelpers::Zero, A1, A1, R0, A1);
    jit.loadPtr(Address(known, OBJECT_OFFSETOF(Known, uid)), A2);
    jit.loadPtr(Address(known, OBJECT_OFFSETOF(Known, getter)), T11);
    jit.loadPtr(Address(known, OBJECT_OFFSETOF(Known, globalObject)), A0);
    jit.call(T11, CustomAccessorPtrTag);
    if (callerIsThunk) {
#if CPU(ARM64)
        jit.popToRestore(CCallHelpers::linkRegister);
#else
        jit.addPtr(TrustedImm32(sizeof(CPURegister)), CCallHelpers::stackPointerRegister);
#endif
    } else
        jit.emitFunctionEpilogue();
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfVM()), T11);
    Jump exception = jit.branchTestPtr(CCallHelpers::NonZero, Address(T11, VM::exceptionOffset()));
    jit.move(GPRInfo::returnValueGPR, R0);
    jit.ret();
    exception.link(&jit);
    if (callerIsThunk)
        jit.emitFunctionEpilogue();
    loadInstance(jit, T9);
    jumpToEntry(jit, T9, Entry::HandleException);
}

static void callProxyGetTrap(CCallHelpers&, GPRReg name, CCallHelpers::JumpList& slowCases, bool isWithinFrame, GPRReg alsoPreserved);

static void generateGetByIdWith(CCallHelpers& jit, Entry operation, bool isCalledByThunk)
{
    CCallHelpers::JumpList miss;
    CCallHelpers::JumpList isNotField;
    miss.append(jit.branchIfNotCell(R0));
    jit.load64(slotWord(A1, 0), T11);
    Jump hasDifferentStructure = branchIfStructureDiffers(jit, R0, T11);
    Jump isIndirect = branchIfSlotHas<Slot::isIndirect>(jit, T11);
    loadDirectLocation(jit, A1, T11, T11);
    jit.load64(CCallHelpers::BaseIndex(R0, T11, CCallHelpers::TimesEight), R0);
    jit.ret();

    isIndirect.link(&jit);
    if (!isCalledByThunk)
        getByIdContinuations(operation).isIndirect = jit.label();
    jit.loadPtr(slotWord(A1, 1), T12);
    Jump isGetter = branchIfSlotHas<Slot::isGetter>(jit, T11);
    jit.moveConditionallyTest64(CCallHelpers::NonZero, T12, T12, T12, R0, T12);
    locateCachedProperty(jit, T12, T11, T13);
    jit.load64(CCallHelpers::BaseIndex(T13, T11, CCallHelpers::TimesEight), R0);
    jit.ret();

    isGetter.link(&jit);
    {
        Jump isField = branchIfSlotHas<Slot::pointerIsNotCell>(jit, T11);
        jit.moveConditionallyTest64(CCallHelpers::NonZero, T12, T12, T12, R0, T12);
        locateCachedProperty(jit, T12, T11, T13);
        jit.load64(CCallHelpers::BaseIndex(T13, T11, CCallHelpers::TimesEight), T12);
        if (isCalledByThunk)
            stubLabels()[static_cast<unsigned>(Stub::CallMethodReadThroughGetter)] = jit.label();
        callGetter(jit, miss);
        isField.link(&jit);
        readCompiledField(jit, miss, &isNotField);
    }

    hasDifferentStructure.link(&jit);
    if (!isCalledByThunk)
        getByIdContinuations(operation).hasDifferentStructure = jit.label();
#if CPU(X86_64)
    jit.load32(Address(R0, JSCell::structureIDOffset()), T12);
#endif
    CCallHelpers::JumpList missAndUpdateCache;
    if (operation == Entry::operationAOTGetById) {
        constexpr GPRReg several = T13;
#if CPU(X86_64)
        constexpr GPRReg entry = A2;
        constexpr GPRReg table = T10;
        constexpr GPRReg nameID = T9;
        constexpr GPRReg nameIDThere = T12;
#else
        constexpr GPRReg entry = T14;
        constexpr GPRReg table = GPRInfo::argumentGPR6;
        constexpr GPRReg nameID = A5;
        constexpr GPRReg nameIDThere = A4;
#endif
        {
            CCallHelpers::JumpList isAlsoIndirect;
            CCallHelpers::JumpList isNotNamed;
            readByName(jit, R0, isAlsoIndirect, isNotNamed);
            isNotNamed.link(&jit);
            if (!isCalledByThunk)
                getByIdContinuations(operation).isNotNamed = jit.label();
            miss.append(jit.branchTest64(CCallHelpers::Zero, T11, CCallHelpers::TrustedImm64(static_cast<int64_t>(~(static_cast<uint64_t>(Slot::attemptsMask) << 32)))));
            miss.append(jit.branchTest32(CCallHelpers::NonZero, T11));
            missAndUpdateCache.append(jit.jump());
            isAlsoIndirect.link(&jit);
            if (!isCalledByThunk)
                getByIdContinuations(operation).hasDifferentStructureAndIsIndirect = jit.label();
        }
        miss.append(jit.branchTest32(CCallHelpers::NonZero, T11));
        static_assert(Slot::polymorphicFlags == (Slot::isIndirect | Slot::pointerIsNotCell));
        miss.append(branchUnlessSlotHas<Slot::pointerIsNotCell>(jit, T11));
        jit.loadPtr(slotWord(A1, 1), several);
        static_assert(!OBJECT_OFFSETOF(Slot, structureID));

        static_assert(sizeof(Slot) == 16 && PolymorphicSlots::structureShift == 4);
        CCallHelpers::JumpList entryMatch;
        jit.and32(TrustedImm32((PolymorphicSlots::numberOfSlots - 1) << PolymorphicSlots::structureShift), T12, A3);
        for (unsigned place = 0; place < 2; ++place) {
            if (place)
                jit.xor32(TrustedImm32(sizeof(Slot)), A3);
#if CPU(X86_64)
            jit.x86Lea64(CCallHelpers::BaseIndex(several, A3, CCallHelpers::TimesOne, PolymorphicSlots::offsetOfSlots()), entry);
#else
            jit.addPtr(several, A3, entry);
            jit.addPtr(TrustedImm32(PolymorphicSlots::offsetOfSlots()), entry);
#endif
            jit.load64(slotWord(entry, 0), T11);
            entryMatch.append(jit.branch32(CCallHelpers::Equal, T11, T12));
        }
        if (isCalledByThunk)
            stubLabels()[static_cast<unsigned>(Stub::CallMethodReadPastEntries)] = jit.label();

        constexpr GPRReg byName = T11;
        constexpr GPRReg inlineSlot = A2;
        static_assert(!(PolymorphicSlots::inlineNameSlotsShift % 8));
        auto loadInlineNameSlot = [&](unsigned i, GPRReg result) {
#if CPU(X86_64)
            jit.load8(Address(several, PolymorphicSlots::offsetOfByName() + PolymorphicSlots::inlineNameSlotsShift / 8 + i), result);
#else
            extractBits(jit, byName, PolymorphicSlots::inlineNameSlotsShift + i * 8, 8, result);
#endif
        };
        jit.load64(Address(several, PolymorphicSlots::offsetOfByName()), byName);
        jit.zeroExtend16To32(byName, nameID);
        Jump hasNoInlineNameSlots = jit.branch32(CCallHelpers::Equal, nameID, TrustedImm32(Structure::firstReservedPropertyNameID));
        jit.zeroExtend32ToWord(T12, table);
        structureWithID(jit, table);
#if CPU(X86_64)
        const int32_t offsetInTable = Structure::offsetOfFieldIDInSlot();
#else
        const int32_t offsetInTable = 0;
        jit.addPtr(TrustedImm32(Structure::offsetOfFieldIDInSlot()), table);
#endif
        loadInlineNameSlot(0, inlineSlot);
        jit.load16(CCallHelpers::BaseIndex(table, inlineSlot, CCallHelpers::TimesTwo, offsetInTable), nameIDThere);
        Jump isInFirstInlineNameSlot = jit.branch32(CCallHelpers::Equal, nameIDThere, nameID);
        for (unsigned i = 1; i < PolymorphicSlots::numberOfInlineSlotsByName; ++i) {
            loadInlineNameSlot(i, A3);
            jit.load16(CCallHelpers::BaseIndex(table, A3, CCallHelpers::TimesTwo, offsetInTable), nameIDThere);
            jit.moveConditionally32(CCallHelpers::Equal, nameIDThere, nameID, A3, inlineSlot, inlineSlot);
        }
        jit.load16(CCallHelpers::BaseIndex(table, inlineSlot, CCallHelpers::TimesTwo, offsetInTable), nameIDThere);
        Jump isNotInInlineNameSlots = jit.branch32(CCallHelpers::NotEqual, nameIDThere, nameID);
        isInFirstInlineNameSlot.link(&jit);
        jit.load64(CCallHelpers::BaseIndex(R0, inlineSlot, CCallHelpers::TimesEight, JSObject::offsetOfInlineStorage()), R0);
        jit.ret();
        isNotInInlineNameSlots.link(&jit);
        jit.urshift64(byName, TrustedImm32(PolymorphicSlots::nameTableFillValueShift), nameID);
        for (unsigned i = 0; i < PolymorphicSlots::numberOfInlineSlotsByName; ++i) {
            loadInlineNameSlot(i, A3);
            jit.load16(CCallHelpers::BaseIndex(table, A3, CCallHelpers::TimesTwo, offsetInTable), nameIDThere);
            missAndUpdateCache.append(jit.branch32(CCallHelpers::Equal, nameIDThere, nameID));
        }
        hasNoInlineNameSlots.link(&jit);
        Jump isRefill = jit.branchAdd32(CCallHelpers::Zero, TrustedImm32(-1), Address(several, PolymorphicSlots::offsetOfMissesUntilRefill()));
        CCallHelpers::Label skipsRefill = jit.label();
        static_assert(FinalObjectType > ObjectType);
        jit.load8(Address(R0, JSCell::typeInfoTypeOffset()), T11);
        Jump isObjectTypeOrLower = jit.branch32(CCallHelpers::BelowOrEqual, T11, TrustedImm32(ObjectType));
        {
            CCallHelpers::JumpList hasNoDescriptor;
            jit.load32(Address(several, PolymorphicSlots::offsetOfIdentifierIndex()), T12);
            jit.and32(TrustedImm32((1u << Site::identifierBits) - 1), T12);
            readByNameAndStructure(jit, T12, T11, A3, A2, hasNoDescriptor);
            hasNoDescriptor.link(&jit);
        }
        CCallHelpers::Label probeMegamorphicCache = jit.label();
        jit.loadPtr(Address(several, PolymorphicSlots::offsetOfName()), A2);
        CCallHelpers::JumpList isInNoCache;
        getFromMegamorphicCache(jit, A2, isInNoCache);

        isRefill.link(&jit);
        Jump isEarlyRefill = jit.branchTest32(CCallHelpers::NonZero, Address(several, PolymorphicSlots::offsetOfRemainingBulkFillAttempts()));
        jit.store32(TrustedImm32(PolymorphicSlots::missesPerRefill), Address(several, PolymorphicSlots::offsetOfMissesUntilRefill()));
        missAndUpdateCache.append(jit.jump());
        isEarlyRefill.link(&jit);
        jit.store32(TrustedImm32(PolymorphicSlots::missesPerEarlyRefill), Address(several, PolymorphicSlots::offsetOfMissesUntilRefill()));
        missAndUpdateCache.append(jit.branchTest8(CCallHelpers::Zero, Address(several, PolymorphicSlots::offsetOfRefillsAreThrottled())));
        jit.load32(Address(R0, JSCell::structureIDOffset()), T11);
        jit.and32(TrustedImm32((PolymorphicSlots::numberOfSlots - 1) << PolymorphicSlots::structureShift), T11);
        Jump entryIsFree = jit.branchTest32(CCallHelpers::Zero, CCallHelpers::BaseIndex(several, T11, CCallHelpers::TimesOne, PolymorphicSlots::offsetOfSlots()));
        jit.xor32(TrustedImm32(sizeof(Slot)), T11);
        jit.branchTest32(CCallHelpers::NonZero, CCallHelpers::BaseIndex(several, T11, CCallHelpers::TimesOne, PolymorphicSlots::offsetOfSlots())).linkTo(skipsRefill, &jit);
        entryIsFree.link(&jit);
        jit.loadPtr(Address(several, PolymorphicSlots::offsetOfName()), A2);
        lookUpInMegamorphicCache(jit, A2, missAndUpdateCache, isInNoCache);

        isInNoCache.link(&jit);
        jit.loadPtr(slotWord(A1, 1), several);
        missAndUpdateCache.append(jit.branchTest8(CCallHelpers::Zero, Address(several, PolymorphicSlots::offsetOfRefillsAreThrottled())));
        jit.load8(Address(R0, JSCell::typeInfoTypeOffset()), T11);
        {
            Jump isFinal = jit.branch32(CCallHelpers::Equal, T11, TrustedImm32(FinalObjectType));
            Jump isArray = jit.branch32(CCallHelpers::Equal, T11, TrustedImm32(ArrayType));
            Jump isFunction = jit.branch32(CCallHelpers::Equal, T11, TrustedImm32(JSFunctionType));
            missAndUpdateCache.append(jit.branch32(CCallHelpers::NotEqual, T11, TrustedImm32(ObjectType)));
            jit.loadPtr(Address(instanceGPR, Instance::offsetOfTyped()), T11);
            missAndUpdateCache.append(jit.branchTestPtr(CCallHelpers::Zero, T11));
            jit.loadPtr(Address(T11, Typed::State::offsetOfModuleNamespaceStructure()), T11);
            missAndUpdateCache.append(jit.branchTestPtr(CCallHelpers::Zero, T11));
            jit.loadPtr(Address(T11, Structure::classInfoOffset()), T11);
            jit.load32(Address(R0, JSCell::structureIDOffset()), T12);
            structureWithID(jit, T12);
            missAndUpdateCache.append(jit.branchPtr(CCallHelpers::NotEqual, Address(T12, Structure::classInfoOffset()), T11));
            jit.loadPtr(Address(several, PolymorphicSlots::offsetOfName()), A2);
            callLookUpAtSite(jit, Entry::operationAOTGetGenericAtSite, T12, A2, several);
            Jump notExport = jit.branchTest64(CCallHelpers::Zero, R0);
            readExport(jit, T12);
            notExport.link(&jit);
            jit.move(T12, R0);
            missAndUpdateCache.append(jit.jump());
            isFinal.link(&jit);
            isArray.link(&jit);
            isFunction.link(&jit);
        }
        jit.loadPtr(Address(several, PolymorphicSlots::offsetOfName()), A2);
        callLookUpAtSite(jit, Entry::operationAOTGetGenericAtSite, T12, A2, several);
        Jump cannotLookUpAtSite = jit.branchTest64(CCallHelpers::Zero, R0);
        jit.ret();
        cannotLookUpAtSite.link(&jit);
        jit.move(T12, R0);
        missAndUpdateCache.append(jit.jump());

        isObjectTypeOrLower.link(&jit);
        missAndUpdateCache.append(jit.branch32(CCallHelpers::NotEqual, T11, TrustedImm32(ObjectType)));
        CCallHelpers::JumpList notKnownField;
        jit.load32(Address(several, PolymorphicSlots::offsetOfIdentifierIndex()), T12);
        jit.branchTest32(CCallHelpers::NonZero, T12, TrustedImm32(PolymorphicSlots::hasNotReadCompiledField)).linkTo(probeMegamorphicCache, &jit);
        findNamedField(jit, Instance::offsetOfNamedFieldReads(), T12, notKnownField, true);
        Jump isKnownField = jit.jump();
        notKnownField.link(&jit);
        jit.loadPtr(slotWord(A1, 1), several);
        jit.jump().linkTo(probeMegamorphicCache, &jit);

        entryMatch.link(&jit);
        Jump isIndirectLocation = branchIfSlotHas<Slot::isIndirect>(jit, T11);
        loadDirectLocation(jit, entry, T11, T11);
        jit.load64(CCallHelpers::BaseIndex(R0, T11, CCallHelpers::TimesEight), R0);
        jit.ret();
        isIndirectLocation.link(&jit);
        jit.loadPtr(slotWord(entry, 1), T12);
        jit.moveConditionallyTest64(CCallHelpers::NonZero, T12, T12, T12, R0, T12);
        Jump isGetterThere = branchIfSlotHas<Slot::isGetter>(jit, T11);
        locateCachedProperty(jit, T12, T11, T13);
        jit.load64(CCallHelpers::BaseIndex(T13, T11, CCallHelpers::TimesEight), R0);
        jit.ret();
        isGetterThere.link(&jit);
        CCallHelpers::JumpList cannotCallGetter;
        Jump isFieldThere = branchIfSlotHas<Slot::pointerIsNotCell>(jit, T11);
        locateCachedProperty(jit, T12, T11, T13);
        jit.load64(CCallHelpers::BaseIndex(T13, T11, CCallHelpers::TimesEight), T12);
        callGetter(jit, cannotCallGetter);
        isFieldThere.link(&jit);
        isKnownField.link(&jit);
        CCallHelpers::JumpList fieldNotPresent;
        readCompiledField(jit, cannotCallGetter, &fieldNotPresent);
        fieldNotPresent.link(&jit);
        static_assert(static_cast<unsigned>(Slot::FieldRead::NoField) == (static_cast<unsigned>(Slot::FieldRead::KnownCustomGetter) | 1));
#if CPU(X86_64)
        isNotField.append(jit.branchTestBit64(CCallHelpers::Zero, T12, TrustedImm32(Slot::fieldReadShift)));
#else
        isNotField.append(jit.branchTest64(CCallHelpers::Zero, T12, CCallHelpers::TrustedImm64(1ll << Slot::fieldReadShift)));
#endif
        static_assert(Slot::isAbsentWhileCountUnchanged == ((Slot::knownCustomGetter & ~1ull) | 4) && Slot::isLookedUp == ((Slot::knownCustomGetter & ~1ull) | 2));
        jit.urshift64(T12, TrustedImm32(Slot::extraPropertyShift), T13);
        isNotField.append(jit.branchTestPtr(CCallHelpers::NonZero, T13));
        Jump isAbsentWhileCountUnchanged = jit.branchTest32(CCallHelpers::NonZero, T12, TrustedImm32(4));
        cannotCallGetter.append(jit.branchTest32(CCallHelpers::Zero, T12, TrustedImm32(2)));
        jit.loadPtr(slotWord(A1, 1), several);
        jit.loadPtr(Address(several, PolymorphicSlots::offsetOfName()), A2);
        callLookUp(jit, Entry::operationAOTGetGeneric, T12, A2);
        Jump cannotLookUp = jit.branchTest64(CCallHelpers::Zero, R0);
        jit.ret();
        cannotLookUp.link(&jit);
        jit.move(T12, R0);
        cannotCallGetter.append(jit.jump());
        isAbsentWhileCountUnchanged.link(&jit);
        jit.load32(Address(R0, JSCell::structureIDOffset()), T11);
        structureWithID(jit, T11);
        jit.loadPtr(Address(T11, Structure::propertyTableUnsafeOffset()), T11);
        cannotCallGetter.append(jit.branchTestPtr(CCallHelpers::Zero, T11));
        jit.load32(Address(T11, PropertyTable::offsetOfKeyCount()), T11);
        jit.urshift32(TrustedImm32(Slot::countShift), T12);
        cannotCallGetter.append(jit.branch32(CCallHelpers::NotEqual, T11, T12));
        jit.move(CCallHelpers::TrustedImm64(JSValue::ValueUndefined), R0);
        jit.ret();
        cannotCallGetter.link(&jit);
        missAndUpdateCache.append(jit.jump());
    }

    miss.link(&jit);
    if (!isCalledByThunk)
        getByIdContinuations(operation).miss = jit.label();
    CCallHelpers::JumpList notFound;
    constexpr bool preservesCallerIndex = T15 != T9;
    if (operation == Entry::operationAOTGetById) {
        loadCallerIndex(jit, 0, isCalledByThunk, false);
        loadDataForSlot(jit, A1, T10);
        countSlotMiss(jit, T10);

        notFound.append(jit.branchIfNotCell(R0));
        notFound.append(jit.branchIfNotObject(R0));
        jit.load32(Address(A1, OBJECT_OFFSETOF(Slot, offset)), T11);
        jit.and32(TrustedImm32(Slot::attemptsMask), T11);
        constexpr GPRReg untriedSlotData = T14;
        jit.move(CCallHelpers::TrustedImmPtr(nullptr), untriedSlotData);
        Jump hasGivenUp = jit.branch32(CCallHelpers::Equal, T11, TrustedImm32(Slot::attemptsMask));
        Jump isTaken = jit.branchTest32(CCallHelpers::NonZero, Address(A1, OBJECT_OFFSETOF(Slot, structureID)));
        jit.loadPtr(Address(instanceGPR, Instance::offsetOfSharedData()), T12);
        Jump isUnowned = jit.branchPtr(CCallHelpers::Equal, T10, T12);
        notFound.append(jit.branch32(CCallHelpers::AboveOrEqual, T11, TrustedImm32(Slot::missesBeforeCaching << Slot::attemptsShift)));
        jit.add32(TrustedImm32(1u << Slot::attemptsShift), Address(A1, OBJECT_OFFSETOF(Slot, offset)));
        jit.move(T10, untriedSlotData);
        Jump isUntried = jit.jump();
        isTaken.link(&jit);
        notFound.append(jit.branch32(CCallHelpers::AboveOrEqual, T11, TrustedImm32(Slot::missesBeforePolymorphic << Slot::attemptsShift)));
        jit.add32(TrustedImm32(1u << Slot::attemptsShift), Address(A1, OBJECT_OFFSETOF(Slot, offset)));
        hasGivenUp.link(&jit);
        isUnowned.link(&jit);
        isUntried.link(&jit);
        CCallHelpers::BaseIndex slotSite = slotSiteIn(jit, T10, A1, T11, T13);
        loadInfo(jit, T10);
        loadSites(jit, T10, T11);
        jit.load32(slotSite, T12);
        jit.and32(TrustedImm32((1u << Site::identifierBits) - 1), T12);
        {
            CCallHelpers::JumpList notKnownField;
            findNamedField(jit, Instance::offsetOfNamedFieldReads(), T12, notKnownField);
            readCompiledField(jit, notFound);
            notKnownField.link(&jit);
        }
        {
            CCallHelpers::JumpList hasNoDescriptor;
            readByNameAndStructure(jit, T12, T11, T13, T10, hasNoDescriptor);
            hasNoDescriptor.link(&jit);
        }
        jit.move(T12, T10);
        jit.loadPtr(Address(instanceGPR, Instance::offsetOfProgramIdentifierPositions()), T11);
        jit.load16(CCallHelpers::BaseIndex(T11, T12, CCallHelpers::TimesTwo), T12);
        jit.loadPtr(Address(instanceGPR, Instance::offsetOfProgramIdentifiers()), T11);
        jit.loadPtr(CCallHelpers::BaseIndex(T11, T12, CCallHelpers::TimesEight), A2);
        notFound.append(jit.branchTestPtr(CCallHelpers::Zero, A2));
        {
            static_assert(sizeof(Structure::SeenProperties) == sizeof(uint64_t));
            CCallHelpers::JumpList mayBeThere;
            mayBeThere.append(jit.branch8(CCallHelpers::NotEqual, Address(R0, JSCell::typeInfoTypeOffset()), TrustedImm32(FinalObjectType)));
            mayBeThere.append(jit.branchTest8(CCallHelpers::NonZero, Address(R0, JSCell::indexingTypeAndMiscOffset()), TrustedImm32(IndexingShapeMask)));
            jit.load32(Address(R0, JSCell::structureIDOffset()), T11);
            structureWithID(jit, T11);
            jit.load64(Address(T11, Structure::seenPropertiesOffset()), T13);
            jit.and64(A2, T13);
            mayBeThere.append(jit.branch64(CCallHelpers::Equal, T13, A2));
            jit.load64(Address(T11, Structure::prototypeOffset()), T13);
            mayBeThere.append(jit.branch64(CCallHelpers::NotEqual, T13, Address(instanceGPR, Instance::offsetOfRealmObjectPrototype())));
            jit.loadPtr(Address(instanceGPR, Instance::offsetOfNameDisplacements()), T13);
            jit.load32(CCallHelpers::BaseIndex(T13, T10, CCallHelpers::TimesFour), T13);
            mayBeThere.append(jit.branchTest32(CCallHelpers::NonZero, T13, TrustedImm32(Typed::Data::nameIsOnObjectPrototype)));
            jit.move(CCallHelpers::TrustedImm64(JSValue::ValueUndefined), R0);
            jit.ret();
            mayBeThere.link(&jit);
        }
        CCallHelpers::JumpList isInNoCache;
        getFromMegamorphicCache(jit, A2, isInNoCache, untriedSlotData);
        isInNoCache.link(&jit);
        jit.load8(Address(R0, JSCell::typeInfoTypeOffset()), T11);
        {
            Jump isFinal = jit.branch32(CCallHelpers::Equal, T11, TrustedImm32(FinalObjectType));
            Jump isArray = jit.branch32(CCallHelpers::Equal, T11, TrustedImm32(ArrayType));
            Jump isFunction = jit.branch32(CCallHelpers::Equal, T11, TrustedImm32(JSFunctionType));
            notFound.append(jit.branch32(CCallHelpers::NotEqual, T11, TrustedImm32(ObjectType)));
            jit.loadPtr(Address(instanceGPR, Instance::offsetOfTyped()), T11);
            notFound.append(jit.branchTestPtr(CCallHelpers::Zero, T11));
            jit.loadPtr(Address(T11, Typed::State::offsetOfModuleNamespaceStructure()), T11);
            notFound.append(jit.branchTestPtr(CCallHelpers::Zero, T11));
            jit.loadPtr(Address(T11, Structure::classInfoOffset()), T11);
            jit.load32(Address(R0, JSCell::structureIDOffset()), T12);
            structureWithID(jit, T12);
            notFound.append(jit.branchPtr(CCallHelpers::NotEqual, Address(T12, Structure::classInfoOffset()), T11));
            callLookUpAtSite(jit, Entry::operationAOTGetGenericAndCache, T12, A2, instanceGPR);
            Jump notExport = jit.branchTest64(CCallHelpers::Zero, R0);
            readExport(jit, T12);
            notExport.link(&jit);
            jit.move(T12, R0);
            missAndUpdateCache.append(jit.jump());
            isFinal.link(&jit);
            isArray.link(&jit);
            isFunction.link(&jit);
        }
        callLookUpAtSite(jit, Entry::operationAOTGetGenericAndCache, T12, A2, instanceGPR);
        Jump cannotLookUp = jit.branchTest64(CCallHelpers::Zero, R0);
        jit.ret();
        cannotLookUp.link(&jit);
        jit.move(T12, R0);
        missAndUpdateCache.append(jit.jump());
        if (!preservesCallerIndex)
            notFound.link(&jit);
    }
    if (operation != Entry::operationAOTGetById)
        isNotField.link(&jit);
    missAndUpdateCache.link(&jit);
    CCallHelpers::Label callOperationLabel = jit.label();
    prepareMissAtSite(jit, operation == Entry::operationAOTGetById ? Entry::RawGetById : operation, 1, 0, preservesCallerIndex ? &notFound : nullptr, isCalledByThunk);
    if (operation == Entry::operationAOTGetById) {
        CCallHelpers::JumpList notProxy;
        CCallHelpers::JumpList declined;
        notProxy.append(jit.branchIfNotCell(A1));
        notProxy.append(jit.branch8(CCallHelpers::NotEqual, Address(A1, JSCell::typeInfoTypeOffset()), TrustedImm32(ProxyObjectType)));
        jit.move(A1, R0);
        jit.or32(TrustedImm32(static_cast<int32_t>(Instance::nameIsIdentifierIndex)), A2, T9);
        callProxyGetTrap(jit, T9, declined, isCalledByThunk, A3);
        declined.link(&jit);
        jit.and32(TrustedImm32(static_cast<int32_t>(~Instance::nameIsIdentifierIndex)), T9, A2);
        jit.move(R0, A1);
        jit.move(instanceGPR, A0);
        jit.loadPtr(Address(instanceGPR, Instance::offsetOfRuntimeTable()), T9);
        jit.loadPtr(Address(T9, offsetInTable(Entry::RawGetById)), T9);
        notProxy.link(&jit);
    }
    callAndCheckException(jit, T9, Returns::Value, GPRInfo::returnValueGPR, isCalledByThunk);
    if (operation == Entry::operationAOTGetById) {
        CCallHelpers::JumpList isNotKnown;
        isNotField.link(&jit);
        readExtraProperty(jit, isNotKnown);
        callKnownCustomGetter(jit, isNotKnown, isCalledByThunk);
        isNotKnown.linkTo(callOperationLabel, &jit);
    }
}

static void loadSlotFromPayload(CCallHelpers& jit, GPRReg payload, PropertyLookupTable::Access access, GPRReg slot, GPRReg scratch)
{
    ASSERT(scratch != payload);
    static_assert(sizeof(Slot) == 2 * 8);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfLookupTableSlots()), scratch);
    jit.getEffectiveAddress(CCallHelpers::BaseIndex(scratch, payload, CCallHelpers::TimesEight, PropertyLookupTable::offsetOfSlotFromScaledPayload(access)), slot);
}

enum class Preserves : uint8_t { Nothing, TwoIntegers, NothingWithinFrame };
#if CPU(X86_64)
constexpr GPRReg preservedIntegerGPRs[] = { X86Registers::ecx, X86Registers::edx };
#else
constexpr GPRReg preservedIntegerGPRs[] = { ARM64Registers::x1, ARM64Registers::x2 };
#endif

template<typename Functor>
static void callStubPreservingRegisters(CCallHelpers& jit, Stub stub, Preserves preserves, const Functor& setUpOperands)
{
    if (preserves == Preserves::NothingWithinFrame) {
        setUpOperands();
        s_callsBetweenStubs->append({ jit.nearTailCall(), stub });
        return;
    }
    jit.emitFunctionPrologue();
    if (preserves == Preserves::TwoIntegers) {
#if CPU(X86_64)
        jit.push(preservedIntegerGPRs[0]);
        jit.push(preservedIntegerGPRs[1]);
#else
        jit.pushPair(preservedIntegerGPRs[0], preservedIntegerGPRs[1]);
#endif
    }
    setUpOperands();
    callStubFromStub(jit, stub);
    if (preserves == Preserves::TwoIntegers) {
#if CPU(X86_64)
        jit.pop(preservedIntegerGPRs[1]);
        jit.pop(preservedIntegerGPRs[0]);
#else
        jit.popPair(preservedIntegerGPRs[0], preservedIntegerGPRs[1]);
#endif
    }
    jit.emitFunctionEpilogue();
    jit.ret();
}

static void setLabelOf(CCallHelpers& jit, Stub stub)
{
    stubLabels()[static_cast<unsigned>(stub)] = jit.label();
}

#if CPU(ARM64)
constexpr GPRReg nameCellGPR = T12;
constexpr GPRReg nameDifferenceGPR = T14;
constexpr unsigned codeInCellShift = 8 * PropertyLookupTable::offsetOfCodeInEntry;
constexpr unsigned kindInCellShift = 8 * PropertyLookupTable::offsetOfKindInEntry;
constexpr unsigned nameInCellShift = 8 * PropertyLookupTable::offsetOfNameInEntry;

static Jump branchIfCellNameDiffers(CCallHelpers& jit, GPRReg name)
{
    jit.m_assembler.sub<64>(nameDifferenceGPR, name, nameCellGPR, ARM64Assembler::LSR, nameInCellShift);
    return jit.branchTest64(CCallHelpers::NonZero, nameDifferenceGPR);
}

static Jump branchIfCellHasNoEntry(CCallHelpers& jit)
{
    static_assert(!(PropertyLookupTable::hasKindAndCode & 0xfff));
    jit.m_assembler.add<64>(nameDifferenceGPR, nameDifferenceGPR, UInt12(PropertyLookupTable::hasKindAndCode >> 12), 12);
    return jit.branchTest64(CCallHelpers::NonZero, nameDifferenceGPR);
}

static void readInlineByCell(CCallHelpers& jit)
{
    static_assert(!PropertyLookupTable::offsetOfReadOffsetInEntry);
    jit.m_assembler.ldr<64>(R0, R0, nameCellGPR, ARM64Assembler::UXTW, 3);
    jit.ret();
}
#endif

#if CPU(ARM64)
static void readMethodByCell(CCallHelpers& jit, GPRReg method, GPRReg row, CCallHelpers::JumpList& otherwise)
{
    const GPRReg scratch = row;
    static_assert(noOverlap(thisGPR, calleeGPR, nameCellGPR, nameDifferenceGPR));
    for (unsigned i = 0; i < numberOfArgumentGPRs; ++i)
        RELEASE_ASSERT(noOverlap(argumentGPR(i), nameCellGPR, nameDifferenceGPR, method, scratch));
    auto hasFlag = [&](uint8_t flag) { return CCallHelpers::TrustedImm64(static_cast<int64_t>(flag) << kindInCellShift); };
    CCallHelpers::JumpList isRead;
    Jump hasNoKindEntry = branchIfCellNameDiffers(jit, calleeGPR);
    Jump isOwn = jit.branchTest64(CCallHelpers::Zero, nameCellGPR, hasFlag(PropertyLookupTable::holderIsInPayload));
    jit.m_assembler.add<64>(scratch, cellCageBaseGPR, nameCellGPR, ARM64Assembler::UXTW, Typed::cell32Shift);
    Jump holderHasInline = jit.branchTest64(CCallHelpers::Zero, nameCellGPR, hasFlag(PropertyLookupTable::valueIsInStorage));
    jit.loadPtr(Address(scratch, JSObject::butterflyOffset()), scratch);
    holderHasInline.link(&jit);
    jit.extractSignedBitfield64(nameCellGPR, TrustedImm32(codeInCellShift), TrustedImm32(8), method);
    jit.load64(CCallHelpers::BaseIndex(scratch, method, CCallHelpers::TimesEight), method);
    isRead.append(jit.jump());

    isOwn.link(&jit);
    Jump isNotInOwnStorage = jit.branchTest64(CCallHelpers::Zero, nameCellGPR, hasFlag(PropertyLookupTable::valueIsInStorage));
    jit.loadPtr(Address(thisGPR, JSObject::butterflyOffset()), scratch);
    jit.m_assembler.ldr<64>(method, scratch, nameCellGPR, ARM64Assembler::SXTW, 0);
    isRead.append(jit.jump());

    isNotInOwnStorage.link(&jit);
    extractBits(jit, nameCellGPR, codeInCellShift, 16, method);
    otherwise.append(jit.branch32(CCallHelpers::NotEqual, method, TrustedImm32(PropertyLookupTable::farInheritedCodeAndKind)));
    extractBits(jit, nameCellGPR, nameInCellShift, WTF::fastLog2(PropertyLookupTable::numberOfColumns), method);
    jit.getEffectiveAddress(CCallHelpers::BaseIndex(row, method, CCallHelpers::TimesEight, PropertyLookupTable::offsetOfFirstColumn + PropertyLookupTable::offsetOfOverflow), method);
    jit.load32SignedExtendTo64(Address(method, PropertyLookupTable::offsetOfPayloads), method);
    jit.m_assembler.add<64>(scratch, cellCageBaseGPR, nameCellGPR, ARM64Assembler::UXTW, Typed::cell32Shift);
    jit.loadPtr(Address(scratch, JSObject::butterflyOffset()), scratch);
    jit.load64(CCallHelpers::BaseIndex(scratch, method, CCallHelpers::TimesOne), method);
    isRead.append(jit.jump());

    hasNoKindEntry.link(&jit);
    jit.m_assembler.sub<64>(nameDifferenceGPR, nameDifferenceGPR, UInt12(PropertyLookupTable::hasKindAndCode >> 12), 12);
    otherwise.append(jit.branchTest64(CCallHelpers::NonZero, nameDifferenceGPR));
    jit.m_assembler.ldr<64>(method, thisGPR, nameCellGPR, ARM64Assembler::UXTW, 3);
    isRead.link(&jit);
}
#endif

static void loadRowByName(CCallHelpers& jit, GPRReg cell, GPRReg row, GPRReg scratch)
{
    jit.load32(Address(cell, JSCell::structureIDOffset()), scratch);
#if CPU(ARM64)
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfLookupTableBaseForStructureIDZero()), row);
    jit.loadPtr(CCallHelpers::BaseIndex(row, scratch, CCallHelpers::TimesOne), row);
#else
    structureWithID(jit, scratch);
    jit.loadPtr(Address(scratch, Structure::offsetOfLookupTableRow()), row);
#endif
}

static void loadEntryName(CCallHelpers& jit, GPRReg entry, GPRReg name)
{
    jit.load16(Address(entry, PropertyLookupTable::offsetOfNameInEntry), name);
    jit.and32(TrustedImm32(PropertyLookupTable::maxName), name);
}

#if CPU(X86_64)
static void jumpToEntryHandler(CCallHelpers& jit, GPRReg entry, GPRReg scratch, ptrdiff_t offsetOfHandlers)
{
    jit.load8(Address(entry, PropertyLookupTable::offsetOfKindInEntry), scratch);
    jit.farJump(CCallHelpers::BaseIndex(instanceGPR, scratch, CCallHelpers::TimesEight, static_cast<int32_t>(offsetOfHandlers)), JITThunkPtrTag);
}
#endif

static void findEntryInOverflow(CCallHelpers& jit, GPRReg name, GPRReg row, GPRReg scratch, CCallHelpers::JumpList& hasNone)
{
    hasNone.append(jit.branchTest8(CCallHelpers::Zero, Address(row, PropertyLookupTable::offsetOfRowFlags), TrustedImm32(PropertyLookupTable::rowHasOverflowNames)));
    jit.getEffectiveAddress(CCallHelpers::BaseIndex(row, name, CCallHelpers::TimesEight, PropertyLookupTable::offsetOfFirstColumn + PropertyLookupTable::offsetOfOverflow), row);
    jit.load16(Address(row, PropertyLookupTable::offsetOfNameInEntry), scratch);
    jit.xor32(name, scratch);
    hasNone.append(jit.branch32(CCallHelpers::NotEqual, scratch, TrustedImm32(PropertyLookupTable::hasKindAndCode)));
}

static CCallHelpers::BaseIndex storageSlotFor(CCallHelpers& jit, GPRReg object, GPRReg entry, GPRReg code, GPRReg storage)
{
    static_assert(PropertyLookupTable::codeForOutOfLineIndex(0) == 0xfe);
#if CPU(ARM64)
    jit.m_assembler.ldrsb<64>(code, entry, PropertyLookupTable::offsetOfCodeInEntry);
    jit.loadPtr(Address(object, JSObject::butterflyOffset()), storage);
    return CCallHelpers::BaseIndex(storage, code, CCallHelpers::TimesEight);
#else
    jit.load8(Address(entry, PropertyLookupTable::offsetOfCodeInEntry), code);
    jit.loadPtr(Address(object, JSObject::butterflyOffset()), storage);
    return CCallHelpers::BaseIndex(storage, code, CCallHelpers::TimesEight, -256 * static_cast<int32_t>(sizeof(EncodedJSValue)));
#endif
}

static CCallHelpers::BaseIndex ownStorageSlot(CCallHelpers& jit, GPRReg object, Address word, GPRReg distance, GPRReg storage)
{
    jit.load32SignedExtendTo64(word, distance);
    jit.loadPtr(Address(object, JSObject::butterflyOffset()), storage);
    return CCallHelpers::BaseIndex(storage, distance, CCallHelpers::TimesOne);
}

static CCallHelpers::BaseIndex outOfLineSlot(CCallHelpers& jit, GPRReg object, GPRReg code, GPRReg storage, uint32_t firstCode)
{
    jit.loadPtr(Address(object, JSObject::butterflyOffset()), storage);
    jit.neg64(code);
    return CCallHelpers::BaseIndex(storage, code, CCallHelpers::TimesEight, (static_cast<int32_t>(firstCode) - 2) * static_cast<int32_t>(sizeof(EncodedJSValue)));
}

static CCallHelpers::Label& getThroughSlotByNameLabel()
{
    static NeverDestroyed<CCallHelpers::Label> label;
    return label.get();
}

static void callProxyGetTrap(CCallHelpers& jit, GPRReg name, CCallHelpers::JumpList& slowCases, bool isWithinFrame, GPRReg alsoPreserved)
{
    constexpr GPRReg sp = CCallHelpers::stackPointerRegister;
    constexpr int32_t proxy = 0;
    constexpr int32_t nameRead = 8;
    constexpr int32_t trap = 16;
    constexpr int32_t handler = 24;
    constexpr int32_t target = 32;
    constexpr int32_t key = 40;
    constexpr int32_t kept = 48;
    constexpr int32_t size = 64;
    static_assert(numberOfArgumentGPRs >= 3);
    auto enter = [&] {
        if (!isWithinFrame) {
            jit.emitFunctionPrologue();
            jit.subPtr(TrustedImm32(size), sp);
            return;
        }
#if CPU(ARM64)
        jit.pushToSave(CCallHelpers::linkRegister);
        jit.subPtr(TrustedImm32(size), sp);
#else
        jit.subPtr(TrustedImm32(size + sizeof(CPURegister)), sp);
#endif
    };
    auto leave = [&] {
        if (!isWithinFrame) {
            jit.addPtr(TrustedImm32(size), sp);
            jit.emitFunctionEpilogue();
            return;
        }
#if CPU(ARM64)
        jit.addPtr(TrustedImm32(size), sp);
        jit.popToRestore(CCallHelpers::linkRegister);
#else
        jit.addPtr(TrustedImm32(size + sizeof(CPURegister)), sp);
#endif
    };
    enter();
    jit.store64(R0, Address(sp, proxy));
    jit.store64(name, Address(sp, nameRead));
    if (alsoPreserved != InvalidGPRReg)
        jit.store64(alsoPreserved, Address(sp, kept));
    jit.move(name, A2);
    jit.move(R0, A1);
    jit.move(instanceGPR, A0);
    jit.addPtr(TrustedImm32(trap), sp, A3);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfRuntimeTable()), T11);
    jit.loadPtr(Address(T11, offsetInTable(Entry::operationAOTPrepareProxyGet)), T11);
    prepareCallOperation(jit, assertionScratchGPR);
    jit.call(T11, OperationPtrTag);
    Jump isNotPrepared = jit.branchTestPtr(CCallHelpers::Zero, GPRInfo::returnValueGPR);
    jit.load64(Address(sp, trap), calleeGPR);
    jit.load64(Address(sp, handler), thisGPR);
    jit.load64(Address(sp, target), argumentGPR(0));
    jit.load64(Address(sp, key), argumentGPR(1));
    jit.load64(Address(sp, proxy), argumentGPR(2));
    jit.move(TrustedImm32(3), countGPR);
    callStubFromStub(jit, Stub::Call);
    jit.load64(Address(sp, target), T11);
    jit.load32(Address(T11, JSCell::structureIDOffset()), T13);
    structureWithID(jit, T13);
    Jump isValidated = jit.branchTest32(CCallHelpers::NonZero, Address(T13, Structure::bitFieldOffset()), TrustedImm32(Structure::s_hasNonConfigurableReadOnlyOrGetterSetterPropertiesBits));
    leave();
    jit.ret();

    isValidated.link(&jit);
    jit.move(R0, A3);
    jit.load32(Address(sp, nameRead), A2);
    jit.move(T11, A1);
    jit.move(instanceGPR, A0);
    leave();
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfRuntimeTable()), T11);
    jit.loadPtr(Address(T11, offsetInTable(Entry::operationAOTValidateProxyGet)), T11);
    callAndCheckException(jit, T11, Returns::Value, GPRInfo::returnValueGPR, isWithinFrame);

    isNotPrepared.link(&jit);
    jit.load64(Address(sp, proxy), R0);
    jit.load64(Address(sp, nameRead), name);
    if (alsoPreserved != InvalidGPRReg)
        jit.load64(Address(sp, kept), alsoPreserved);
    leave();
    slowCases.append(jit.jump());
}

static void generateGetByNameGeneric(CCallHelpers& jit)
{
    constexpr bool callerIsThunk = true;
    CCallHelpers::JumpList miss;
    CCallHelpers::JumpList isNotField;
    constexpr GPRReg name = T9;
    jit.move(A1, name);
    miss.append(jit.branchIfNotCell(R0));
    miss.append(jit.branch8(CCallHelpers::NotEqual, Address(R0, JSCell::typeInfoTypeOffset()), TrustedImm32(ProxyObjectType)));
    callProxyGetTrap(jit, name, miss, true, InvalidGPRReg);

    getThroughSlotByNameLabel() = jit.label();
    miss.append(branchUnlessSlotHas<Slot::isGetter>(jit, T11));
    jit.loadPtr(slotWord(A1, 1), T12);
    Jump isField = branchIfSlotHas<Slot::pointerIsNotCell>(jit, T11);
    jit.moveConditionallyTest64(CCallHelpers::NonZero, T12, T12, T12, R0, T12);
    locateCachedProperty(jit, T12, T11, T13);
    jit.load64(CCallHelpers::BaseIndex(T13, T11, CCallHelpers::TimesEight), T12);
    callGetter(jit, miss);
    isField.link(&jit);
    readCompiledField(jit, miss, &isNotField);
    isNotField.link(&jit);
    readExtraProperty(jit, miss);
    callKnownCustomGetter(jit, miss, callerIsThunk);

    miss.link(&jit);
    {
        using Kind = PropertyLookupTable::Kind;
        constexpr GPRReg holder = T12;
        constexpr GPRReg entry = T13;
        constexpr GPRReg word = T11;
        static_assert(noOverlap(R0, name, holder, entry, word));
        CCallHelpers::JumpList slowCases;
        CCallHelpers::JumpList hasHolder;
        Jump notCell = jit.branchIfNotCell(R0);
        Jump notString = jit.branchIfNotString(R0);
        jit.loadPtr(Address(instanceGPR, Instance::offsetOfStringPrototype()), holder);
        hasHolder.append(jit.jump());
        notString.link(&jit);
        slowCases.append(jit.branchIfNotSymbol(R0));
        jit.loadPtr(Address(instanceGPR, Instance::offsetOfSymbolPrototype()), holder);
        hasHolder.append(jit.jump());
        notCell.link(&jit);
        Jump notNumber = jit.branchIfNotNumber(R0);
        jit.loadPtr(Address(instanceGPR, Instance::offsetOfNumberPrototype()), holder);
        hasHolder.append(jit.jump());
        notNumber.link(&jit);
        jit.move(R0, word);
        jit.and64(TrustedImm32(~1), word);
        slowCases.append(jit.branch64(CCallHelpers::NotEqual, word, TrustedImm32(JSValue::ValueFalse)));
        jit.loadPtr(Address(instanceGPR, Instance::offsetOfBooleanPrototype()), holder);
        hasHolder.link(&jit);
        slowCases.append(jit.branchTestPtr(CCallHelpers::Zero, holder));
        loadRowByName(jit, holder, entry, word);
        jit.and32(TrustedImm32(PropertyLookupTable::numberOfColumns - 1), name, word);
        jit.getEffectiveAddress(CCallHelpers::BaseIndex(entry, word, CCallHelpers::TimesEight, PropertyLookupTable::offsetOfFirstColumn), entry);
        jit.load16(Address(entry, PropertyLookupTable::offsetOfNameInEntry), word);
        jit.xor32(name, word);
        Jump hasKindAndCode = jit.branch32(CCallHelpers::Equal, word, TrustedImm32(PropertyLookupTable::hasKindAndCode));
        slowCases.append(jit.branchTest32(CCallHelpers::NonZero, word));
        jit.load32(Address(entry, PropertyLookupTable::offsetOfReadOffsetInEntry), word);
        jit.load64(CCallHelpers::BaseIndex(holder, word, CCallHelpers::TimesEight), R0);
        jit.ret();

        hasKindAndCode.link(&jit);
        jit.load8(Address(entry, PropertyLookupTable::offsetOfKindInEntry), word);
#if CPU(ARM64)
        jit.and32(TrustedImm32((1 << PropertyLookupTable::bitsOfKind) - 1), word);
#endif
        static_assert(static_cast<unsigned>(Kind::OutOfLine) + 1 == static_cast<unsigned>(Kind::OutOfLineAndWritten) && !static_cast<unsigned>(Kind::Absent));
        Jump isInheritedInline = jit.branch32(CCallHelpers::Equal, word, TrustedImm32(static_cast<int32_t>(Kind::InheritedInline)));
        Jump isInheritedOutOfLine = jit.branch32(CCallHelpers::Equal, word, TrustedImm32(static_cast<int32_t>(Kind::InheritedOutOfLine)));
        Jump isAbsent = jit.branch32(CCallHelpers::BelowOrEqual, word, TrustedImm32(static_cast<int32_t>(Kind::AbsentAndStoreAddsInNewStorage)));
        jit.sub32(TrustedImm32(static_cast<int32_t>(Kind::OutOfLine)), word);
        slowCases.append(jit.branch32(CCallHelpers::Above, word, TrustedImm32(1)));
        jit.load64(ownStorageSlot(jit, holder, Address(entry, PropertyLookupTable::offsetOfPayloads), word, holder), R0);
        jit.ret();

        isInheritedOutOfLine.link(&jit);
        jit.load32(Address(entry, PropertyLookupTable::offsetOfPayloads), holder);
        decodeCell32(jit, holder, holder);
        jit.load64(storageSlotFor(jit, holder, entry, word, holder), R0);
        jit.ret();

        isInheritedInline.link(&jit);
        jit.load8(Address(entry, PropertyLookupTable::offsetOfCodeInEntry), word);
        jit.load32(Address(entry, PropertyLookupTable::offsetOfPayloads), holder);
        decodeCell32(jit, holder, holder);
        jit.load64(CCallHelpers::BaseIndex(holder, word, CCallHelpers::TimesEight), R0);
        jit.ret();

        isAbsent.link(&jit);
        jit.move(CCallHelpers::TrustedImm64(JSValue::ValueUndefined), R0);
        jit.ret();

        slowCases.link(&jit);
    }
    jit.move(name, A2);
    jit.move(R0, A1);
    jit.move(instanceGPR, A0);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfRuntimeTable()), T11);
    jit.loadPtr(Address(T11, offsetInTable(Entry::operationAOTGetByNameAndCache)), T11);
    callAndCheckException(jit, T11, Returns::Value, GPRInfo::returnValueGPR, callerIsThunk);
}

