static void loadOwnAccessor(CCallHelpers& jit, GPRReg object, GPRReg word, GPRReg accessor)
{
    ASSERT(noOverlap(object, word, accessor));
    Jump isInlineEntry = jit.branchTest32(CCallHelpers::NonZero, word, TrustedImm32(PropertyLookupTable::ownAccessorIsInline));
    jit.loadPtr(Address(object, JSObject::butterflyOffset()), accessor);
    jit.neg64(word);
    jit.load64(CCallHelpers::BaseIndex(accessor, word, CCallHelpers::TimesOne), accessor);
    Jump isLoaded = jit.jump();
    isInlineEntry.link(&jit);
    jit.load64(CCallHelpers::BaseIndex(object, word, CCallHelpers::TimesOne, -static_cast<int32_t>(PropertyLookupTable::ownAccessorIsInline)), accessor);
    isLoaded.link(&jit);
}

static void getThroughAccessor(CCallHelpers& jit, CCallHelpers::JumpList& cannot)
{
    CCallHelpers::JumpList isLoaded;
    jit.load32(Address(readEntryGPR, PropertyLookupTable::offsetOfPayloads), T13);
    Jump isOwn = jit.branch32(CCallHelpers::Below, T13, TrustedImm32(PropertyLookupTable::minHolderWord));
    jit.load8(Address(readEntryGPR, PropertyLookupTable::offsetOfCodeInEntry), T11);
    decodeCell32(jit, T13, T13);
    Jump isOutOfLine = jit.branch32(CCallHelpers::AboveOrEqual, T11, TrustedImm32(PropertyLookupTable::firstCodeOutOfLine));
    jit.load64(CCallHelpers::BaseIndex(T13, T11, CCallHelpers::TimesEight), T12);
    isLoaded.append(jit.jump());
    isOutOfLine.link(&jit);
    jit.load64(outOfLineSlot(jit, T13, T11, T13, PropertyLookupTable::firstCodeOutOfLine), T12);
    isLoaded.append(jit.jump());
    isOwn.link(&jit);
    loadOwnAccessor(jit, R0, T13, T12);
    isLoaded.link(&jit);
    callGetter(jit, cannot);
}

static void loadExtraProperties(CCallHelpers& jit, GPRReg object, GPRReg payloadAndResult, GPRReg scratch, CCallHelpers::JumpList& hasNoNumber)
{
    jit.urshift32(TrustedImm32(PropertyLookupTable::extraPropertiesOffsetShift), payloadAndResult);
    Jump extraPropertiesViaHandle = jit.branchTest32(CCallHelpers::Zero, payloadAndResult);
    jit.load32(CCallHelpers::BaseIndex(object, payloadAndResult, CCallHelpers::TimesOne), payloadAndResult);
    decodeCell32(jit, payloadAndResult, payloadAndResult);
    Jump areLoaded = jit.jump();
    extraPropertiesViaHandle.link(&jit);
    loadExtraPropertiesViaHandle(jit, object, payloadAndResult, scratch, hasNoNumber);
    areLoaded.link(&jit);
}

static void getThroughExtraAccessor(CCallHelpers& jit, CCallHelpers::JumpList& cannot)
{
    jit.load8(Address(readEntryGPR, PropertyLookupTable::offsetOfCodeInEntry), T11);
    jit.load32(Address(readEntryGPR, PropertyLookupTable::offsetOfPayloads), T13);
    jit.and32(TrustedImm32(PropertyLookupTable::firstOutOfLineExtraPropertyCode - 1), T11);
    loadExtraProperties(jit, R0, T13, T12, cannot);
    jit.loadPtr(CCallHelpers::BaseIndex(T13, T11, CCallHelpers::TimesEight), T12);
    callGetter(jit, cannot);
}

static void getThroughKnownCustomGetter(CCallHelpers& jit, CCallHelpers::JumpList& cannot, bool callerIsThunk)
{
    constexpr GPRReg slot = T13;
    jit.load32(Address(readEntryGPR, PropertyLookupTable::offsetOfPayloads), T13);
    cannot.append(jit.branchTest32(CCallHelpers::Zero, T13, TrustedImm32(PropertyLookupTable::payloadIsSlots)));
    loadSlotFromPayload(jit, T13, PropertyLookupTable::Access::Read, slot, T11);
    jit.load64(slotWord(slot, 0), T11);
    cannot.append(branchIfStructureDiffers(jit, R0, T11));
    jit.loadPtr(slotWord(slot, 1), T12);
    callKnownCustomGetter(jit, cannot, callerIsThunk, ChecksEpoch::No);
}

static void makeLazyClosure(CCallHelpers& jit, CCallHelpers::JumpList& cannot)
{
    constexpr GPRReg entry = readEntryGPR;
    constexpr GPRReg scratch = T10;
    constexpr GPRReg place = T11;
    constexpr GPRReg request = T12;
    constexpr GPRReg closure = T13;
    static_assert(noOverlap(R0, entry, scratch, place, request, closure));
    auto loadRequest = [&] {
        jit.loadPtr(Address(place), request);
        jit.load32(Address(request, CustomGetterSetter::offsetOfLazyClosureRequest()), request);
    };
    jit.load8(Address(R0, JSCell::cellStateOffset()), scratch);
    cannot.append(jit.branch32(CCallHelpers::BelowOrEqual, scratch, Address(instanceGPR, Instance::offsetOfBarrierThreshold())));
    jit.load8(Address(entry, PropertyLookupTable::offsetOfCodeInEntry), place);
    Jump isOutOfLine = jit.branch32(CCallHelpers::AboveOrEqual, place, TrustedImm32(PropertyLookupTable::firstCodeOutOfLine));
    jit.getEffectiveAddress(CCallHelpers::BaseIndex(R0, place, CCallHelpers::TimesEight), place);
    Jump isLocated = jit.jump();
    isOutOfLine.link(&jit);
    jit.getEffectiveAddress(outOfLineSlot(jit, R0, place, scratch, PropertyLookupTable::firstCodeOutOfLine), place);
    isLocated.link(&jit);
    loadRequest();
    cannot.append(jit.branchTest32(CCallHelpers::Zero, request));
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfTypedSlimClosureAllocator(1)), request);
    cannot.append(jit.branchTestPtr(CCallHelpers::Zero, request));
    jit.emitAllocateWithNonNullAllocator(closure, JITAllocator::variable(), request, scratch, cannot, CCallHelpers::SlowAllocationResult::UndefinedBehavior);
    loadRequest();
    jit.urshift32(request, TrustedImm32(ClosureRequest::executableShift), scratch);
    jit.load64(CCallHelpers::BaseIndex(instanceGPR, scratch, CCallHelpers::TimesEight, Instance::offsetOfTypedSlimClosureHeader(0) - static_cast<ptrdiff_t>(sizeof(uint64_t) << (ClosureRequest::isSlimBit - ClosureRequest::executableShift))), scratch);
    jit.store64(scratch, Address(closure, 0));
    jit.store64(R0, Address(closure, Typed::SlimClosure::offsetOfCaptures()));
    jit.and32(TrustedImm32(ClosureWord::functionMask), request);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfTypedFunctions()), scratch);
    jit.load64(CCallHelpers::BaseIndex(scratch, request, CCallHelpers::TimesEight), scratch);
    jit.store64(scratch, Address(closure, Typed::SlimClosure::offsetOfWord()));
    fenceAfterAllocation(jit, scratch);
    jit.store64(closure, Address(place));
    jit.load32(Address(entry, PropertyLookupTable::offsetOfPayloads), scratch);
    jit.store32(scratch, Address(R0, JSCell::structureIDOffset()));
    jit.move(closure, R0);
    jit.ret();
}

static void getNamespaceExport(CCallHelpers& jit)
{
    jit.move(R0, T12);
    jit.load32(Address(readEntryGPR, PropertyLookupTable::offsetOfPayloads), R0);
    jit.urshift32(TrustedImm32(1), R0);
    readExport(jit, T12);
}
static void generateGetNamespaceExportByName(CCallHelpers& jit) { getNamespaceExport(jit); }

enum class AccessorIs : uint8_t { OwnInline, Anywhere, InExtraProperties, KnownCustomGetter };
static void generateGetThroughAccessorByNameWith(CCallHelpers& jit, AccessorIs where)
{
    CCallHelpers::JumpList cannot;
    if (where == AccessorIs::OwnInline)
        getThroughOwnAccessorInline(jit, cannot);
    else if (where == AccessorIs::Anywhere)
        getThroughAccessor(jit, cannot);
    else if (where == AccessorIs::KnownCustomGetter)
        getThroughKnownCustomGetter(jit, cannot, true);
    else
        getThroughExtraAccessor(jit, cannot);
    cannot.link(&jit);
    loadEntryName(jit, readEntryGPR, A1);
    jit.jump().linkTo(stubLabels()[static_cast<unsigned>(Stub::GetByNameGeneric)], &jit);
}
static void generateGetThroughAccessorByName(CCallHelpers& jit) { generateGetThroughAccessorByNameWith(jit, AccessorIs::Anywhere); }
static void generateGetThroughOwnAccessorByName(CCallHelpers& jit) { generateGetThroughAccessorByNameWith(jit, AccessorIs::OwnInline); }
static void generateGetThroughExtraAccessorByName(CCallHelpers& jit) { generateGetThroughAccessorByNameWith(jit, AccessorIs::InExtraProperties); }
static void generateGetThroughKnownCustomGetterByName(CCallHelpers& jit) { generateGetThroughAccessorByNameWith(jit, AccessorIs::KnownCustomGetter); }

struct GetByNameContinuations {
    CCallHelpers::Label notInlineEntry;
    CCallHelpers::Label genericPath;
};
static GetByNameContinuations& getByNameContinuations(Preserves preserves)
{
    static NeverDestroyed<std::array<GetByNameContinuations, 3>> continuations;
    return continuations.get()[static_cast<unsigned>(preserves)];
}

constexpr unsigned numberOfGetHandlersPerVariant = 13;
static_assert(static_cast<unsigned>(Stub::ReadFieldCell32ByName) + numberOfGetHandlersPerVariant == static_cast<unsigned>(Stub::ReadFieldCell32ByNamePreservingTwo) && static_cast<unsigned>(Stub::ReadThroughSlotsByName) + 2 * numberOfGetHandlersPerVariant == static_cast<unsigned>(Stub::ReadThroughSlotsByNameWithinFrame));

static void readFromPrototypeByName(CCallHelpers& jit, CCallHelpers::JumpList& genericPath)
{
    using Kind = PropertyLookupTable::Kind;
    constexpr GPRReg name = T9;
    constexpr GPRReg receiver = T10;
    constexpr GPRReg cell = T12;
    constexpr int32_t fromSignedCode = -256 * static_cast<int32_t>(sizeof(EncodedJSValue));
    static_assert(name == readEntryGPR && noOverlap(R0, name, receiver, T11, cell, T13, instanceGPR));
    static_assert(noOverlap(preservedIntegerGPRs[0], name, receiver, T11, cell, T13) && noOverlap(preservedIntegerGPRs[1], name, receiver, T11, cell, T13));
    CCallHelpers::JumpList isNotPlainData;
    auto isKind = [&](Kind kind) { return jit.branch32(CCallHelpers::Equal, T13, TrustedImm32(static_cast<int32_t>(kind))); };
    loadEntryName(jit, name, name);
    jit.move(R0, receiver);
    decodeCell32(jit, T13, T13);
    jit.move(T13, R0);
    loadRowByName(jit, R0, T13, T11);
    jit.getEffectiveAddress(CCallHelpers::BaseIndex(T13, name, CCallHelpers::TimesEight, PropertyLookupTable::offsetOfFirstColumn), cell);
    jit.load16(Address(cell, PropertyLookupTable::offsetOfNameInEntry), T11);
    jit.xor32(name, T11);
    isNotPlainData.append(jit.branch32(CCallHelpers::NotEqual, T11, TrustedImm32(PropertyLookupTable::hasKindAndCode)));
    jit.load8(Address(cell, PropertyLookupTable::offsetOfKindInEntry), T13);
    jit.and32(TrustedImm32((1 << PropertyLookupTable::bitsOfKind) - 1), T13);
    jit.load8(Address(cell, PropertyLookupTable::offsetOfCodeInEntry), T11);
    Jump isCell32 = isKind(Kind::FieldCell32);
    Jump isInt32 = isKind(Kind::FieldInt32);
    Jump isBoxed = isKind(Kind::FieldBoxed);
    Jump isDouble = isKind(Kind::FieldDouble);
    Jump isBoolean = isKind(Kind::FieldBoolean);
    Jump isOptionalBoolean = isKind(Kind::FieldOptionalBoolean);
    Jump isInheritedInline = isKind(Kind::InheritedInline);
    Jump isInheritedOutOfLine = isKind(Kind::InheritedOutOfLine);
    static_assert(!static_cast<unsigned>(Kind::Absent));
    isNotPlainData.append(jit.branch32(CCallHelpers::Above, T13, TrustedImm32(static_cast<int32_t>(Kind::AbsentAndStoreAddsInNewStorage))));
    jit.move(CCallHelpers::TrustedImm64(JSValue::ValueUndefined), R0);
    jit.ret();

    isCell32.link(&jit);
    jit.load32(CCallHelpers::BaseIndex(R0, T11, CCallHelpers::TimesFour), T13);
    Jump notCell = jit.branch32(CCallHelpers::Below, T13, TrustedImm32(Typed::minCell32));
    decodeCell32(jit, T13, T13);
    jit.move(T13, R0);
    jit.ret();
    notCell.link(&jit);
    Jump isLiteralString = jit.branch32(CCallHelpers::Above, T13, TrustedImm32(Typed::undefinedCell32));
    static_assert(!Typed::absentCell32 && Typed::nullCell32 == JSValue::ValueNull && Typed::undefinedCell32 == JSValue::ValueUndefined);
    isNotPlainData.append(jit.branch32(CCallHelpers::BelowOrEqual, T13, TrustedImm32(Typed::unmaterializedClosureCell32)));
    jit.move(T13, R0);
    jit.ret();
    isLiteralString.link(&jit);
    static_assert(2 << Typed::literalStringShift == sizeof(JSCell*));
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfTypedLiteralStrings()), T11);
    jit.load64(CCallHelpers::BaseIndex(T11, T13, CCallHelpers::TimesTwo, -2 * static_cast<int32_t>(Typed::emptyLiteralStringWord)), T13);
    isNotPlainData.append(jit.branchTest64(CCallHelpers::Zero, T13));
    jit.move(T13, R0);
    jit.ret();

    isInt32.link(&jit);
    jit.load32(CCallHelpers::BaseIndex(R0, T11, CCallHelpers::TimesFour), T13);
    isNotPlainData.append(jit.branch32(CCallHelpers::LessThan, T13, TrustedImm32(Typed::minInlineInt32)));
#if CPU(ARM64)
    jit.addZeroExtend64(numberTag, T13, R0);
#else
    jit.add64(numberTag, T13, R0);
#endif
    jit.ret();

    isBoxed.link(&jit);
    jit.load64(CCallHelpers::BaseIndex(R0, T11, CCallHelpers::TimesFour), T13);
    isNotPlainData.append(jit.branchTest64(CCallHelpers::Zero, T13));
    jit.move(T13, R0);
    jit.ret();

    isDouble.link(&jit);
    jit.loadDouble(CCallHelpers::BaseIndex(R0, T11, CCallHelpers::TimesFour), FPRInfo::fpRegT0);
    Jump isNaN = jit.branchIfNaN(FPRInfo::fpRegT0);
    CCallHelpers::JumpList notInt32;
    branchIfNotExactInt32(jit, FPRInfo::fpRegT0, T13, notInt32, FPRInfo::fpRegT1);
#if CPU(ARM64)
    jit.addZeroExtend64(numberTag, T13, R0);
#else
    jit.zeroExtend32ToWord(T13, R0);
    jit.add64(numberTag, R0);
#endif
    jit.ret();
    notInt32.link(&jit);
    jit.moveDoubleTo64(FPRInfo::fpRegT0, R0);
    jit.sub64(numberTag, R0);
    jit.ret();
    isNaN.link(&jit);
    jit.moveDoubleTo64(FPRInfo::fpRegT0, T13);
    Jump isUndefinedNumber = jit.branch64(CCallHelpers::Equal, T13, CCallHelpers::TrustedImm64(static_cast<int64_t>(Typed::undefinedDouble)));
    isNotPlainData.append(jit.branch64(CCallHelpers::NotEqual, T13, CCallHelpers::TrustedImm64(static_cast<int64_t>(Typed::nullDouble))));
    jit.move(CCallHelpers::TrustedImm64(JSValue::ValueNull), R0);
    jit.ret();
    isUndefinedNumber.link(&jit);
    jit.move(CCallHelpers::TrustedImm64(JSValue::ValueUndefined), R0);
    jit.ret();

    isBoolean.link(&jit);
    jit.load8(CCallHelpers::BaseIndex(R0, T11, CCallHelpers::TimesOne), T13);
    jit.or32(TrustedImm32(JSValue::ValueFalse), T13, R0);
    jit.ret();

    isOptionalBoolean.link(&jit);
    jit.load8(CCallHelpers::BaseIndex(R0, T11, CCallHelpers::TimesOne), T13);
    isNotPlainData.append(jit.branchTest32(CCallHelpers::Zero, T13));
    jit.move(T13, R0);
    jit.ret();

    isInheritedInline.link(&jit);
    jit.load32(Address(cell, PropertyLookupTable::offsetOfPayloads), T13);
    decodeCell32(jit, T13, T13);
    jit.load64(CCallHelpers::BaseIndex(T13, T11, CCallHelpers::TimesEight), R0);
    jit.ret();

    isInheritedOutOfLine.link(&jit);
    jit.load32(Address(cell, PropertyLookupTable::offsetOfPayloads), T13);
    decodeCell32(jit, T13, T13);
    jit.loadPtr(Address(T13, JSObject::butterflyOffset()), T13);
    jit.load64(CCallHelpers::BaseIndex(T13, T11, CCallHelpers::TimesEight, fromSignedCode), R0);
    jit.ret();

    isNotPlainData.link(&jit);
    jit.move(receiver, R0);
    genericPath.append(jit.jump());
}

static void generateGetByNameWith(CCallHelpers& jit, Preserves preserves)
{
    bool preservesNothing = preserves != Preserves::TwoIntegers;
    constexpr GPRReg name = T9;
    constexpr GPRReg entry = readEntryGPR;
    constexpr GPRReg slot = T13;
    ptrdiff_t handlers = Instance::offsetOfGetByNameHandlers(static_cast<unsigned>(preserves));
    auto setHandlerLabel = [&](Stub nonPreservingStub) {
        setLabelOf(jit, static_cast<Stub>(static_cast<unsigned>(nonPreservingStub) + numberOfGetHandlersPerVariant * static_cast<unsigned>(preserves)));
    };
    CCallHelpers::JumpList genericPath;
    CCallHelpers::JumpList genericWithEntry;
    CCallHelpers::JumpList throughSlots;
    genericPath.append(jit.branchIfNotCell(R0));
    loadRowByName(jit, R0, T13, T11);
    jit.and32(TrustedImm32(PropertyLookupTable::numberOfColumns - 1), name, T11);
#if CPU(X86_64)
    jit.m_assembler.cmpw_rm(name, PropertyLookupTable::offsetOfFirstColumn + PropertyLookupTable::offsetOfNameInEntry, T13, T11, CCallHelpers::TimesEight);
    Jump notInlineEntry = Jump(jit.m_assembler.jCC(X86Assembler::ConditionNE));
    jit.load32(CCallHelpers::BaseIndex(T13, T11, CCallHelpers::TimesEight, PropertyLookupTable::offsetOfFirstColumn + PropertyLookupTable::offsetOfReadOffsetInEntry), T11);
    jit.load64(CCallHelpers::BaseIndex(R0, T11, CCallHelpers::TimesEight), R0);
    jit.ret();

    notInlineEntry.link(&jit);
    jit.getEffectiveAddress(CCallHelpers::BaseIndex(T13, T11, CCallHelpers::TimesEight, PropertyLookupTable::offsetOfFirstColumn), T13);
    jit.load16(Address(T13, PropertyLookupTable::offsetOfNameInEntry), T11);
    jit.xor32(name, T11);
    Jump hasNoEntry = jit.branch32(CCallHelpers::NotEqual, T11, TrustedImm32(PropertyLookupTable::hasKindAndCode));
    jit.move(T13, entry);
    jumpToEntryHandler(jit, entry, T11, handlers);
#else
    jit.load64(CCallHelpers::BaseIndex(T13, T11, CCallHelpers::TimesEight, PropertyLookupTable::offsetOfFirstColumn), nameCellGPR);
    Jump notInlineEntry = branchIfCellNameDiffers(jit, name);
    readInlineByCell(jit);

    notInlineEntry.link(&jit);
    getByNameContinuations(preserves).notInlineEntry = jit.label();
    Jump hasNoEntry = branchIfCellHasNoEntry(jit);
    Jump holderIsInPayload = jit.branchTest64(CCallHelpers::NonZero, nameCellGPR, CCallHelpers::TrustedImm64(static_cast<int64_t>(PropertyLookupTable::holderIsInPayload) << kindInCellShift));
    Jump valueIsInOwnStorage = jit.branchTest64(CCallHelpers::NonZero, nameCellGPR, CCallHelpers::TrustedImm64(static_cast<int64_t>(PropertyLookupTable::valueIsInStorage) << kindInCellShift));
    extractBits(jit, nameCellGPR, nameInCellShift, WTF::fastLog2(PropertyLookupTable::numberOfColumns), T11);
    jit.getEffectiveAddress(CCallHelpers::BaseIndex(T13, T11, CCallHelpers::TimesEight, PropertyLookupTable::offsetOfFirstColumn), entry);
    extractBits(jit, nameCellGPR, kindInCellShift, PropertyLookupTable::bitsOfKind, T11);
    jit.farJump(CCallHelpers::BaseIndex(instanceGPR, T11, CCallHelpers::TimesEight, static_cast<int32_t>(handlers)), JITThunkPtrTag);

    holderIsInPayload.link(&jit);
    jit.m_assembler.add<64>(T13, cellCageBaseGPR, nameCellGPR, ARM64Assembler::UXTW, Typed::cell32Shift);
    Jump holderHasInline = jit.branchTest64(CCallHelpers::Zero, nameCellGPR, CCallHelpers::TrustedImm64(static_cast<int64_t>(PropertyLookupTable::valueIsInStorage) << kindInCellShift));
    jit.loadPtr(Address(T13, JSObject::butterflyOffset()), T13);
    holderHasInline.link(&jit);
    jit.extractSignedBitfield64(nameCellGPR, TrustedImm32(codeInCellShift), TrustedImm32(8), T11);
    jit.load64(CCallHelpers::BaseIndex(T13, T11, CCallHelpers::TimesEight), R0);
    jit.ret();

    valueIsInOwnStorage.link(&jit);
    jit.loadPtr(Address(R0, JSObject::butterflyOffset()), T13);
    jit.m_assembler.ldr<64>(R0, T13, nameCellGPR, ARM64Assembler::SXTW, 0);
    jit.ret();

#endif

    setHandlerLabel(Stub::ReadFieldCell32ByName);
    jit.load8(Address(entry, PropertyLookupTable::offsetOfCodeInEntry), T11);
    jit.load32(CCallHelpers::BaseIndex(R0, T11, CCallHelpers::TimesFour), T13);
    Jump notCell = jit.branch32(CCallHelpers::Below, T13, TrustedImm32(Typed::minCell32));
#if CPU(ARM64)
    decodeCell32(jit, T13, R0);
#else
    decodeCell32(jit, T13, T13);
    jit.move(T13, R0);
#endif
    jit.ret();

    notCell.link(&jit);
    Jump isLiteralString = jit.branch32(CCallHelpers::Above, T13, TrustedImm32(Typed::undefinedCell32));
    static_assert(!Typed::absentCell32 && Typed::nullCell32 == JSValue::ValueNull && Typed::undefinedCell32 == JSValue::ValueUndefined);
    throughSlots.append(jit.branch32(CCallHelpers::BelowOrEqual, T13, TrustedImm32(Typed::unmaterializedClosureCell32)));
    jit.move(T13, R0);
    jit.ret();

    isLiteralString.link(&jit);
    static_assert(2 << Typed::literalStringShift == sizeof(JSCell*));
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfTypedLiteralStrings()), T11);
    jit.load64(CCallHelpers::BaseIndex(T11, T13, CCallHelpers::TimesTwo, -2 * static_cast<int32_t>(Typed::emptyLiteralStringWord)), T13);
    throughSlots.append(jit.branchTest64(CCallHelpers::Zero, T13));
    jit.move(T13, R0);
    jit.ret();

    setHandlerLabel(Stub::ReadFieldInt32ByName);
    jit.load8(Address(entry, PropertyLookupTable::offsetOfCodeInEntry), T11);
    jit.load32(CCallHelpers::BaseIndex(R0, T11, CCallHelpers::TimesFour), T13);
    throughSlots.append(jit.branch32(CCallHelpers::LessThan, T13, TrustedImm32(Typed::minInlineInt32)));
#if CPU(ARM64)
    jit.addZeroExtend64(numberTag, T13, R0);
#else
    jit.add64(numberTag, T13, R0);
#endif
    jit.ret();

    setHandlerLabel(Stub::ReadFieldBoxedByName);
    jit.load8(Address(entry, PropertyLookupTable::offsetOfCodeInEntry), T11);
    jit.load64(CCallHelpers::BaseIndex(R0, T11, CCallHelpers::TimesFour), T13);
    throughSlots.append(jit.branchTest64(CCallHelpers::Zero, T13));
    jit.move(T13, R0);
    jit.ret();

    setHandlerLabel(Stub::ReadFieldDoubleByName);
    jit.load8(Address(entry, PropertyLookupTable::offsetOfCodeInEntry), T11);
    jit.loadDouble(CCallHelpers::BaseIndex(R0, T11, CCallHelpers::TimesFour), FPRInfo::fpRegT0);
    Jump isNaN = jit.branchIfNaN(FPRInfo::fpRegT0);
    CCallHelpers::JumpList notInt32;
    branchIfNotExactInt32(jit, FPRInfo::fpRegT0, T13, notInt32, FPRInfo::fpRegT1);
#if CPU(ARM64)
    jit.addZeroExtend64(numberTag, T13, R0);
#else
    jit.zeroExtend32ToWord(T13, R0);
    jit.add64(numberTag, R0);
#endif
    jit.ret();
    notInt32.link(&jit);
    jit.moveDoubleTo64(FPRInfo::fpRegT0, R0);
    jit.sub64(numberTag, R0);
    jit.ret();
    isNaN.link(&jit);
    jit.moveDoubleTo64(FPRInfo::fpRegT0, T13);
    Jump isUndefinedNumber = jit.branch64(CCallHelpers::Equal, T13, CCallHelpers::TrustedImm64(static_cast<int64_t>(Typed::undefinedDouble)));
    throughSlots.append(jit.branch64(CCallHelpers::NotEqual, T13, CCallHelpers::TrustedImm64(static_cast<int64_t>(Typed::nullDouble))));
    jit.move(CCallHelpers::TrustedImm64(JSValue::ValueNull), R0);
    jit.ret();
    isUndefinedNumber.link(&jit);
    jit.move(CCallHelpers::TrustedImm64(JSValue::ValueUndefined), R0);
    jit.ret();

    setHandlerLabel(Stub::ReadFieldBooleanByName);
    jit.load8(Address(entry, PropertyLookupTable::offsetOfCodeInEntry), T11);
    jit.load8(CCallHelpers::BaseIndex(R0, T11, CCallHelpers::TimesOne), T13);
    jit.or32(TrustedImm32(JSValue::ValueFalse), T13, R0);
    jit.ret();

    setHandlerLabel(Stub::ReadFieldOptionalBooleanByName);
    jit.load8(Address(entry, PropertyLookupTable::offsetOfCodeInEntry), T11);
    jit.load8(CCallHelpers::BaseIndex(R0, T11, CCallHelpers::TimesOne), T13);
    throughSlots.append(jit.branchTest32(CCallHelpers::Zero, T13));
    jit.move(T13, R0);
    jit.ret();

    setHandlerLabel(Stub::ReadOwnAccessorByName);
    if (preservesNothing)
        getThroughOwnAccessorInline(jit, genericWithEntry);
    else
        callStubPreservingRegisters(jit, Stub::GetThroughOwnAccessorByName, preserves, [] { });

    setHandlerLabel(Stub::ReadAccessorByName);
    if (preservesNothing)
        getThroughAccessor(jit, genericWithEntry);
    else
        callStubPreservingRegisters(jit, Stub::GetThroughAccessorByName, preserves, [] { });

    setHandlerLabel(Stub::ReadExtraPropertyByName);
    jit.load8(Address(entry, PropertyLookupTable::offsetOfCodeInEntry), T11);
    jit.load32(Address(entry, PropertyLookupTable::offsetOfPayloads), T13);
    CCallHelpers::JumpList isExtraAccessor;
    Jump notInlineAfterReference = jit.branch32(CCallHelpers::AboveOrEqual, T11, TrustedImm32(PropertyLookupTable::firstOutOfLineExtraPropertyCode));
    isExtraAccessor.append(jit.branchTest32(CCallHelpers::NonZero, T13, TrustedImm32(PropertyLookupTable::extraPropertyIsAccessor)));
    jit.urshift32(TrustedImm32(PropertyLookupTable::extraPropertiesOffsetShift), T13);
    jit.load32(CCallHelpers::BaseIndex(R0, T13, CCallHelpers::TimesOne), T13);
    decodeCell32(jit, T13, T13);
    jit.load64(CCallHelpers::BaseIndex(T13, T11, CCallHelpers::TimesEight), R0);
    jit.ret();

    notInlineAfterReference.link(&jit);
    Jump notExtraProperty = jit.branchTest32(CCallHelpers::NonZero, T11, TrustedImm32(PropertyLookupTable::storeAddsExtraProperty));
    isExtraAccessor.append(jit.branchTest32(CCallHelpers::NonZero, T13, TrustedImm32(PropertyLookupTable::extraPropertyIsAccessor)));
    loadExtraProperties(jit, R0, T13, T12, genericWithEntry);
    jit.and32(TrustedImm32(PropertyLookupTable::extraPropertyUsesHandle - 1), T11);
    Jump isExtraPropertyOutOfLine = jit.branch32(CCallHelpers::AboveOrEqual, T11, TrustedImm32(PropertyLookupTable::firstOutOfLineExtraPropertyCode));
    jit.load64(CCallHelpers::BaseIndex(T13, T11, CCallHelpers::TimesEight), R0);
    jit.ret();

    isExtraPropertyOutOfLine.link(&jit);
    jit.load64(outOfLineSlot(jit, T13, T11, T13, PropertyLookupTable::firstOutOfLineExtraPropertyCode), R0);
    jit.ret();

    notExtraProperty.link(&jit);
    genericWithEntry.append(jit.branchTest32(CCallHelpers::Zero, T13, TrustedImm32(PropertyLookupTable::extraPropertyIsKnownToBeAbsent)));
    jit.move(CCallHelpers::TrustedImm64(JSValue::ValueUndefined), R0);
    jit.ret();

    isExtraAccessor.link(&jit);
    if (preservesNothing)
        getThroughExtraAccessor(jit, genericWithEntry);
    else
        callStubPreservingRegisters(jit, Stub::GetThroughExtraAccessorByName, preserves, [] { });

    setHandlerLabel(Stub::ReadKnownCustomGetterByName);
    jit.load8(Address(entry, PropertyLookupTable::offsetOfCodeInEntry), T11);
    Jump cachesNoValue = jit.branchTest32(CCallHelpers::Zero, T11);
    jit.load64(CCallHelpers::BaseIndex(R0, T11, CCallHelpers::TimesFour), T13);
    Jump cacheIsEmpty = jit.branchTest64(CCallHelpers::Zero, T13);
    jit.move(T13, R0);
    jit.ret();
    cachesNoValue.link(&jit);
    cacheIsEmpty.link(&jit);
    if (preservesNothing)
        getThroughKnownCustomGetter(jit, genericWithEntry, preserves == Preserves::NothingWithinFrame);
    else
        callStubPreservingRegisters(jit, Stub::GetThroughKnownCustomGetterByName, preserves, [] { });

    setHandlerLabel(Stub::ReadLazyClosureByName);
    makeLazyClosure(jit, genericWithEntry);

    setHandlerLabel(Stub::ReadNamespaceExportByName);
    if (preservesNothing)
        getNamespaceExport(jit);
    else
        callStubPreservingRegisters(jit, Stub::GetNamespaceExportByName, preserves, [] { });

    throughSlots.link(&jit);
    setHandlerLabel(Stub::ReadThroughSlotsByName);
    jit.load32(Address(entry, PropertyLookupTable::offsetOfPayloads), T13);
    Jump hasNoSlots = jit.branchTest32(CCallHelpers::Zero, T13, TrustedImm32(PropertyLookupTable::payloadIsSlots));
    loadSlotFromPayload(jit, T13, PropertyLookupTable::Access::Read, slot, T11);
    jit.load64(slotWord(slot, 0), T11);
    genericWithEntry.append(branchIfStructureDiffers(jit, R0, T11));
    Jump isIndirect = branchIfSlotHas<Slot::isIndirect>(jit, T11);
    loadDirectLocation(jit, slot, T11, T11);
    jit.load64(CCallHelpers::BaseIndex(R0, T11, CCallHelpers::TimesEight), R0);
    jit.ret();

    isIndirect.link(&jit);
    Jump isGetterOrField = branchIfSlotHas<Slot::isGetter>(jit, T11);
    jit.loadPtr(slotWord(slot, 1), T13);
    jit.moveConditionallyTest64(CCallHelpers::NonZero, T13, T13, T13, R0, T13);
    locateCachedProperty(jit, T13, T11, T10);
    jit.load64(CCallHelpers::BaseIndex(T10, T11, CCallHelpers::TimesEight), R0);
    jit.ret();

    isGetterOrField.link(&jit);
    if (preservesNothing) {
        CCallHelpers::JumpList isNotField;
        Jump isGetter = branchUnlessSlotHas<Slot::pointerIsNotCell>(jit, T11);
        jit.loadPtr(slotWord(slot, 1), T12);
        readCompiledField(jit, genericWithEntry, &isNotField);
        isNotField.link(&jit);
        readExtraProperty(jit, genericWithEntry);
        jit.load32(Address(entry, PropertyLookupTable::offsetOfPayloads), T13);
        loadSlotFromPayload(jit, T13, PropertyLookupTable::Access::Read, slot, T11);
        isGetter.link(&jit);
    }
    loadEntryName(jit, entry, name);
    callStubPreservingRegisters(jit, Stub::GetThroughSlotByName, preserves, [&] {
        jit.move(slot, A1);
    });

    hasNoSlots.link(&jit);
    jit.load16(Address(entry, PropertyLookupTable::offsetOfCodeInEntry), T11);
    Jump isNotFarInherited = jit.branch32(CCallHelpers::NotEqual, T11, TrustedImm32(PropertyLookupTable::farInheritedCodeAndKind));
    decodeCell32(jit, T13, T13);
    jit.load32SignedExtendTo64(Address(entry, PropertyLookupTable::offsetOfOverflow + PropertyLookupTable::offsetOfPayloads), T11);
    jit.loadPtr(Address(T13, JSObject::butterflyOffset()), T13);
    jit.load64(CCallHelpers::BaseIndex(T13, T11, CCallHelpers::TimesOne), R0);
    jit.ret();

    isNotFarInherited.link(&jit);
    genericWithEntry.append(jit.branch32(CCallHelpers::NotEqual, T11, TrustedImm32(PropertyLookupTable::delegatesToPrototypeCodeAndKind)));
    readFromPrototypeByName(jit, genericPath);

    genericWithEntry.link(&jit);
    loadEntryName(jit, entry, name);
    genericPath.link(&jit);
    hasNoEntry.link(&jit);
    getByNameContinuations(preserves).genericPath = jit.label();
    if (preserves == Preserves::NothingWithinFrame)
        setLabelOf(jit, Stub::GetByNameWithinFrameAfterFirstProbe);
    callStubPreservingRegisters(jit, Stub::GetByNameGeneric, preserves, [&] {
        jit.move(name, A1);
    });
}
