#undef AOT_GENERATE_READ_WITH_RECEIVER_IN

static void generateGetByNameOf(CCallHelpers& jit, uint32_t number, Preserves preserves)
{
    constexpr GPRReg row = T13;
    int32_t offset = PropertyLookupTable::offsetOfFirstColumn + static_cast<int32_t>(number * sizeof(PropertyLookupTable::Cell));
#if CPU(X86_64)
    constexpr GPRReg entry = readEntryGPR;
    Jump notCell = jit.branchIfNotCell(R0);
    loadRowByName(jit, R0, row, T11);
    Jump notInlineEntry = jit.branch16(CCallHelpers::NotEqual, Address(row, offset + PropertyLookupTable::offsetOfNameInEntry), TrustedImm32(number));
    jit.load32(Address(row, offset + PropertyLookupTable::offsetOfReadOffsetInEntry), row);
    jit.load64(CCallHelpers::BaseIndex(R0, row, CCallHelpers::TimesEight), R0);
    jit.ret();
    notInlineEntry.link(&jit);
    jit.addPtr(TrustedImm32(offset), row, entry);
    Jump hasNoEntry = jit.branch16(CCallHelpers::NotEqual, Address(entry, PropertyLookupTable::offsetOfNameInEntry), TrustedImm32(number | PropertyLookupTable::hasKindAndCode));
    jumpToEntryHandler(jit, entry, T11, Instance::offsetOfGetByNameHandlers(static_cast<unsigned>(preserves)));
    hasNoEntry.link(&jit);
    notCell.link(&jit);
    jit.move(TrustedImm32(number), T9);
    jit.jump().linkTo(getByNameContinuations(preserves).genericPath, &jit);
#else
    jit.move(TrustedImm32(number), T9);
    jit.branchIfNotCell(R0).linkTo(getByNameContinuations(preserves).genericPath, &jit);
    loadRowByName(jit, R0, row, T11);
    jit.load64(Address(row, offset), nameCellGPR);
    branchIfCellNameDiffers(jit, T9).linkTo(getByNameContinuations(preserves).notInlineEntry, &jit);
    readInlineByCell(jit);
#endif
}

static void storeCompiledField(CCallHelpers& jit, CCallHelpers::JumpList& miss, CCallHelpers::JumpList* created = nullptr, CCallHelpers::Label* hasAddress = nullptr, std::optional<PropertyLookupTable::Kind> onlyKind = std::nullopt)
{
    using FieldWrite = Slot::FieldWrite;
    using Kind = PropertyLookupTable::Kind;
    const GPRReg pointer = onlyKind ? T9 : T13;
    const GPRReg description = onlyKind ? T10 : T14;
    auto stores = [&](Kind kind) {
        return !onlyKind || *onlyKind == kind;
    };
    auto linkIfSet = [&](Jump jump) {
        if (jump.isSet())
            jump.link(&jit);
    };
    constexpr GPRReg address = T12;
    constexpr GPRReg scratch = T11;
    auto unlessAccepts = [&](uint32_t kind) {
        miss.append(jit.branchTest32(CCallHelpers::Zero, description, TrustedImm32(kind)));
    };
    auto isValue = [&](int64_t encoded) {
        return jit.branch64(CCallHelpers::Equal, A1, CCallHelpers::TrustedImm64(encoded));
    };
    auto unlessTypeAcceptsObject = [&] {
        using Typed::RuntimeShapeTest;
        using Typed::RuntimeType;
        const GPRReg type = pointer;
        const GPRReg other = description;
        constexpr unsigned maxSupertypes = 3;
        constexpr unsigned maxJSTypes = 2;
        CCallHelpers::JumpList isAccepted;
        CCallHelpers::JumpList hasNoMoreSupertypes;
        CCallHelpers::JumpList hasNoMoreJSTypes;
        jit.urshift32(TrustedImm32(FieldWrite::offsetBits), type);
        jit.urshift32(TrustedImm32(FieldWrite::typeShift), other);
        jit.and32(TrustedImm32((1 << FieldWrite::typeBitsInUpperHalf) - 1), other);
        jit.lshift32(TrustedImm32(32 - FieldWrite::offsetBits), other);
        jit.or32(other, type);
        miss.append(jit.branchTest32(CCallHelpers::Zero, type));
        jit.lshift64(TrustedImm32(2), type);
        jit.addPtr(Address(instanceGPR, Instance::offsetOfTypedData()), type);
        for (unsigned i = 0; i < maxSupertypes; ++i) {
            jit.load16(Address(type, OBJECT_OFFSETOF(RuntimeType, supertypesCount)), other);
            hasNoMoreSupertypes.append(jit.branch32(CCallHelpers::BelowOrEqual, other, TrustedImm32(i)));
            jit.load32(Address(type, sizeof(RuntimeType) + i * sizeof(int32_t)), scratch);
            jit.signExtend32ToPtr(scratch, scratch);
            jit.addPtr(type, scratch);
            miss.append(jit.branch32(CCallHelpers::NotEqual, Address(scratch, OBJECT_OFFSETOF(RuntimeShapeTest, set)), TrustedImm32(-1)));
            jit.load32(Address(scratch, OBJECT_OFFSETOF(RuntimeShapeTest, first)), other);
            jit.add32(Address(scratch, OBJECT_OFFSETOF(RuntimeShapeTest, count)), other);
            jit.sub32(TrustedImm32(1), other);
            jit.add32(Address(A1, Typed::offsetOfShapeWord), other);
            isAccepted.append(jit.branch32(CCallHelpers::Below, other, Address(scratch, OBJECT_OFFSETOF(RuntimeShapeTest, count))));
        }
        jit.load16(Address(type, OBJECT_OFFSETOF(RuntimeType, supertypesCount)), other);
        miss.append(jit.branch32(CCallHelpers::Above, other, TrustedImm32(maxSupertypes)));
        hasNoMoreSupertypes.link(&jit);
        jit.lshift32(TrustedImm32(2), other);
        jit.addPtr(type, other);
        jit.load8(Address(A1, JSCell::typeInfoTypeOffset()), scratch);
        miss.append(jit.branch32(CCallHelpers::Equal, scratch, TrustedImm32(ObjectType)));
        for (unsigned i = 0; i < maxJSTypes; ++i) {
            hasNoMoreJSTypes.append(jit.branch8(CCallHelpers::BelowOrEqual, Address(type, OBJECT_OFFSETOF(RuntimeType, jsTypesCount)), TrustedImm32(i)));
            isAccepted.append(jit.branch32(CCallHelpers::Equal, scratch, Address(other, sizeof(RuntimeType) + i * sizeof(uint32_t))));
        }
        miss.append(jit.branch8(CCallHelpers::Above, Address(type, OBJECT_OFFSETOF(RuntimeType, jsTypesCount)), TrustedImm32(maxJSTypes)));
        hasNoMoreJSTypes.link(&jit);
        miss.append(jit.branchTest8(CCallHelpers::Zero, Address(type, OBJECT_OFFSETOF(RuntimeType, bits)), TrustedImm32(RuntimeType::allowsAnyFunctionBit)));
        isAccepted.append(jit.branch32(CCallHelpers::Equal, scratch, TrustedImm32(JSFunctionType)));
        jit.sub32(TrustedImm32(SlimClosureType), scratch);
        miss.append(jit.branch32(CCallHelpers::Above, scratch, TrustedImm32(SlimClosureWithPropertiesType - SlimClosureType)));
        isAccepted.link(&jit);
    };
    auto didStore = [&](bool mayBeCell) {
        if (created)
            created->append(jit.jump());
        else if (mayBeCell && onlyKind) {
            jit.branchIfCell(A1).linkTo(stubLabels()[static_cast<unsigned>(Stub::WriteBarrier)], &jit);
            jit.ret();
        } else if (mayBeCell)
            returnAfterStoring(jit, A1);
        else
            jit.ret();
    };
    if (!created) {
        jit.load32(Address(R0, Typed::offsetOfOrderWord), scratch);
        miss.append(jit.branchTest32(CCallHelpers::NonZero, scratch, TrustedImm32(Typed::orderWordIsFrozen)));
    }
    static_assert(!((((1u << FieldWrite::typeBitsInUpperHalf) - 1) << FieldWrite::typeShift) & (FieldWrite::isFieldWrite | FieldWrite::isInGlobalProxyTarget | Slot::isStoreTransition >> 32)));
    static_assert(FieldWrite::offsetBits == 16);
    jit.zeroExtend16To32(pointer, address);
    jit.addPtr(R0, address);
    if (hasAddress)
        *hasAddress = jit.label();
    static_assert(!FieldWrite::Boxed);
    Jump isNotBoxed;
    if (!onlyKind)
        isNotBoxed = jit.branchTest32(CCallHelpers::NonZero, description, TrustedImm32(FieldWrite::representationMask));
    if (stores(Kind::FieldBoxed)) {
        if (!created)
            miss.append(jit.branchTest64(CCallHelpers::Zero, Address(address)));
        CCallHelpers::JumpList isAccepted;
        Jump notInt32 = jit.branchIfNotInt32(A1);
        unlessAccepts(FieldWrite::acceptsInt32);
        isAccepted.append(jit.jump());
        notInt32.link(&jit);
        Jump notNumber = jit.branchIfNotNumber(A1);
        unlessAccepts(FieldWrite::acceptsNumber);
        isAccepted.append(jit.jump());
        notNumber.link(&jit);
        Jump isCell = jit.branchIfCell(A1);
        Jump isUndefined = isValue(JSValue::ValueUndefined);
        Jump isNull = isValue(JSValue::ValueNull);
        unlessAccepts(FieldWrite::acceptsBoolean);
        isAccepted.append(isValue(JSValue::ValueTrue));
        isAccepted.append(isValue(JSValue::ValueFalse));
        miss.append(jit.jump());
        isUndefined.link(&jit);
        unlessAccepts(FieldWrite::acceptsUndefined);
        isAccepted.append(jit.jump());
        isNull.link(&jit);
        unlessAccepts(FieldWrite::acceptsNull);
        isAccepted.append(jit.jump());
        isCell.link(&jit);
        jit.load8(Address(A1, JSCell::typeInfoTypeOffset()), scratch);
        Jump isObject = jit.branch32(CCallHelpers::AboveOrEqual, scratch, TrustedImm32(ObjectType));
        Jump isString = jit.branch32(CCallHelpers::Equal, scratch, TrustedImm32(StringType));
        Jump isSymbol = jit.branch32(CCallHelpers::Equal, scratch, TrustedImm32(SymbolType));
        miss.append(jit.branch32(CCallHelpers::NotEqual, scratch, TrustedImm32(HeapBigIntType)));
        unlessAccepts(FieldWrite::acceptsBigInt);
        isAccepted.append(jit.jump());
        isObject.link(&jit);
        isAccepted.append(jit.branchTest32(CCallHelpers::NonZero, description, TrustedImm32(FieldWrite::acceptsObject)));
        unlessTypeAcceptsObject();
        isAccepted.append(jit.jump());
        isString.link(&jit);
        unlessAccepts(FieldWrite::acceptsString);
        isAccepted.append(jit.jump());
        isSymbol.link(&jit);
        unlessAccepts(FieldWrite::acceptsSymbol);
        isAccepted.link(&jit);
        jit.store64(A1, Address(address));
        didStore(true);
    }

    linkIfSet(isNotBoxed);
    Jump isInt32OrNumberBox;
    Jump isCell32;
    Jump isDouble;
    Jump isBoolean;
    Jump isInt64;
    Jump isInt32;
    static_assert(FieldWrite::Int32 + 1 == FieldWrite::representationMask);
    if (!onlyKind || *onlyKind == Kind::FieldInt32) {
        jit.and32(TrustedImm32(FieldWrite::representationMask), description, scratch);
        isInt32OrNumberBox = jit.branch32(CCallHelpers::Equal, scratch, TrustedImm32(FieldWrite::Int32OrNumberBox));
    }
    if (!onlyKind) {
        isCell32 = jit.branch32(CCallHelpers::Equal, scratch, TrustedImm32(FieldWrite::Cell32));
        isDouble = jit.branch32(CCallHelpers::Equal, scratch, TrustedImm32(FieldWrite::Double));
        isBoolean = jit.branch32(CCallHelpers::Equal, scratch, TrustedImm32(FieldWrite::Boolean));
        isInt64 = jit.branch32(CCallHelpers::Equal, scratch, TrustedImm32(FieldWrite::Int64));
    }
    if (!onlyKind || *onlyKind == Kind::FieldInt32)
        isInt32 = jit.jump();
    Jump isInBox;

    linkIfSet(isInt32OrNumberBox);
    if (stores(Kind::FieldInt32)) {
        static_assert(Typed::absentInt32 < Typed::undefinedInt32 && Typed::undefinedInt32 < Typed::nullInt32);
        Jump hasBox;
        if (!created) {
            jit.load32(Address(address), scratch);
            Jump isInlineNumber = jit.branch32(CCallHelpers::GreaterThanOrEqual, scratch, TrustedImm32(Typed::minInlineInt32));
            miss.append(jit.branch32(CCallHelpers::LessThanOrEqual, scratch, TrustedImm32(Typed::absentInt32)));
            hasBox = jit.branch32(CCallHelpers::GreaterThan, scratch, TrustedImm32(Typed::nullInt32));
            isInlineNumber.link(&jit);
        }
        miss.append(jit.branchIfNotInt32(A1));
        unlessAccepts(FieldWrite::acceptsInt32);
        miss.append(jit.branch32(CCallHelpers::LessThan, A1, TrustedImm32(Typed::minInlineInt32)));
        jit.store32(A1, Address(address));
        didStore(false);
        if (!created) {
            hasBox.link(&jit);
            jit.and32(TrustedImm32(INT32_MAX), scratch, address);
            jit.lshift64(TrustedImm32(Typed::numberBoxShift), address);
            jit.add64(Address(instanceGPR, Instance::offsetOfNumberBoxBase()), address);
            isInBox = jit.jump();
        }
    }

    linkIfSet(isCell32);
    if (stores(Kind::FieldCell32)) {
        static_assert(!Typed::absentCell32 && Typed::nullCell32 == JSValue::ValueNull && Typed::undefinedCell32 == JSValue::ValueUndefined);
        if (!created)
            miss.append(jit.branchTest32(CCallHelpers::Zero, Address(address)));
        Jump notCell = jit.branchIfNotCell(A1);
        jit.load8(Address(A1, JSCell::typeInfoTypeOffset()), scratch);
        Jump isString = jit.branch32(CCallHelpers::Equal, scratch, TrustedImm32(StringType));
        Jump isObject = jit.branch32(CCallHelpers::AboveOrEqual, scratch, TrustedImm32(ObjectType));
        miss.append(jit.branch32(CCallHelpers::NotEqual, scratch, TrustedImm32(SymbolType)));
        unlessAccepts(FieldWrite::acceptsSymbol);
        Jump isAcceptedSymbol = jit.jump();
        isObject.link(&jit);
        miss.append(jit.branchTestPtr(CCallHelpers::NonZero, A1, TrustedImm32(PreciseAllocation::halfAlignment)));
        unlessTypeAcceptsObject();
        Jump isAcceptedObject = jit.jump();
        isString.link(&jit);
        unlessAccepts(FieldWrite::acceptsString);
        Jump storesLiteralStringWord = jit.branchTest32(CCallHelpers::NonZero, description, TrustedImm32(FieldWrite::storesLiteralStringWords));
        isAcceptedSymbol.link(&jit);
        isAcceptedObject.link(&jit);
        CCallHelpers::Label isStoredAsCell = jit.label();
        encodeCell32(jit, A1, scratch);
        jit.store32(scratch, Address(address));
        didStore(true);

        storesLiteralStringWord.link(&jit);
        jit.loadPtr(Address(A1, JSString::offsetOfValue()), scratch);
        jit.loadPtr(Address(instanceGPR, Instance::offsetOfTypedData()), description);
        Jump isRope = jit.branchTestPtr(CCallHelpers::NonZero, scratch, TrustedImm32(JSString::isRopeInPointer));
        jit.load32(Address(scratch, StringImpl::lengthMemoryOffset()), pointer);
        jit.branch32(CCallHelpers::Below, Address(description, OBJECT_OFFSETOF(Typed::Data, maxLiteralStringLength)), pointer).linkTo(isStoredAsCell, &jit);
        jit.urshift64(scratch, TrustedImm32(Typed::literalStringCacheIndexShift), pointer);
        jit.and32(TrustedImm32((1 << Typed::literalStringCacheIndexBits) - 1), pointer);
        jit.loadPtr(Address(instanceGPR, Instance::offsetOfTypedLiteralStringCache()), description);
        jit.load64(CCallHelpers::BaseIndex(description, pointer, CCallHelpers::TimesEight), pointer);
        jit.urshift64(TrustedImm32(3), scratch);
        jit.urshift64(pointer, TrustedImm32(Typed::literalStringCacheWordBits), description);
        miss.append(jit.branch64(CCallHelpers::NotEqual, description, scratch));
        jit.and32(TrustedImm32((1 << Typed::literalStringCacheWordBits) - 1), pointer);
        jit.branchTest32(CCallHelpers::Zero, pointer).linkTo(isStoredAsCell, &jit);
        jit.lshift32(TrustedImm32(1), pointer);
        jit.store32(pointer, Address(address));
        didStore(false);
        isRope.link(&jit);
        jit.load32(Address(A1, JSRopeString::offsetOfLength()), pointer);
        jit.branch32(CCallHelpers::Below, Address(description, OBJECT_OFFSETOF(Typed::Data, maxLiteralStringLength)), pointer).linkTo(isStoredAsCell, &jit);
        miss.append(jit.jump());

        notCell.link(&jit);
        Jump isUndefined = isValue(JSValue::ValueUndefined);
        miss.append(jit.branch64(CCallHelpers::NotEqual, A1, CCallHelpers::TrustedImm64(JSValue::ValueNull)));
        unlessAccepts(FieldWrite::acceptsNull);
        Jump isAcceptedNull = jit.jump();
        isUndefined.link(&jit);
        unlessAccepts(FieldWrite::acceptsUndefined);
        isAcceptedNull.link(&jit);
        jit.store32(A1, Address(address));
        didStore(false);
    }

    linkIfSet(isDouble);
    if (stores(Kind::FieldDouble) || stores(Kind::FieldInt32)) {
        if (!created) {
            Jump hasNoMarkers = jit.branchTest32(CCallHelpers::Zero, description, TrustedImm32(FieldWrite::isOptional));
            jit.load64(Address(address), scratch);
            miss.append(jit.branch64(CCallHelpers::Equal, scratch, CCallHelpers::TrustedImm64(static_cast<int64_t>(Typed::absentDouble))));
            hasNoMarkers.link(&jit);
            linkIfSet(isInBox);
        }
        Jump notInt32 = jit.branchIfNotInt32(A1);
        unlessAccepts(FieldWrite::acceptsInt32);
        jit.convertInt32ToDouble(A1, FPRInfo::fpRegT0);
        jit.storeDouble(FPRInfo::fpRegT0, Address(address));
        didStore(false);
        notInt32.link(&jit);
        miss.append(jit.branchIfNotNumber(A1));
        unlessAccepts(FieldWrite::acceptsNumber);
        jit.add64(numberTag, A1, scratch);
        jit.store64(scratch, Address(address));
        didStore(false);
    }

    linkIfSet(isBoolean);
    if (stores(Kind::FieldBoolean)) {
        Jump hasNoMarkers = jit.branchTest32(CCallHelpers::Zero, description, TrustedImm32(FieldWrite::isOptional));
        if (!created)
            miss.append(jit.branchTest8(CCallHelpers::Zero, Address(address)));
        Jump isUndefined = isValue(JSValue::ValueUndefined);
        Jump isNull = isValue(JSValue::ValueNull);
        jit.and64(TrustedImm32(~1), A1, scratch);
        miss.append(jit.branch64(CCallHelpers::NotEqual, scratch, CCallHelpers::TrustedImm64(JSValue::ValueFalse)));
        unlessAccepts(FieldWrite::acceptsBoolean);
        Jump isAcceptedBoolean = jit.jump();
        isUndefined.link(&jit);
        unlessAccepts(FieldWrite::acceptsUndefined);
        Jump isAcceptedUndefined = jit.jump();
        isNull.link(&jit);
        unlessAccepts(FieldWrite::acceptsNull);
        isAcceptedBoolean.link(&jit);
        isAcceptedUndefined.link(&jit);
        jit.store8(A1, Address(address));
        didStore(false);

        hasNoMarkers.link(&jit);
        jit.and64(TrustedImm32(~1), A1, scratch);
        miss.append(jit.branch64(CCallHelpers::NotEqual, scratch, CCallHelpers::TrustedImm64(JSValue::ValueFalse)));
        unlessAccepts(FieldWrite::acceptsBoolean);
        jit.and32(TrustedImm32(1), A1, scratch);
        jit.store8(scratch, Address(address));
        didStore(false);
    }

    linkIfSet(isInt64);
    if (!onlyKind) {
        if (!created) {
            Jump hasNoMarkers = jit.branchTest32(CCallHelpers::Zero, description, TrustedImm32(FieldWrite::isOptional));
            jit.load64(Address(address), scratch);
            miss.append(jit.branch64(CCallHelpers::Equal, scratch, CCallHelpers::TrustedImm64(Typed::absentInteger)));
            hasNoMarkers.link(&jit);
        }
        Jump notInt32 = jit.branchIfNotInt32(A1);
        unlessAccepts(FieldWrite::acceptsInt32);
        jit.signExtend32ToPtr(A1, scratch);
        jit.store64(scratch, Address(address));
        didStore(false);
        notInt32.link(&jit);
        Jump isUndefined = isValue(JSValue::ValueUndefined);
        miss.append(jit.branch64(CCallHelpers::NotEqual, A1, CCallHelpers::TrustedImm64(JSValue::ValueNull)));
        unlessAccepts(FieldWrite::acceptsNull);
        jit.move(CCallHelpers::TrustedImm64(Typed::nullInteger), scratch);
        Jump isAcceptedNull = jit.jump();
        isUndefined.link(&jit);
        unlessAccepts(FieldWrite::acceptsUndefined);
        jit.move(CCallHelpers::TrustedImm64(Typed::undefinedInteger), scratch);
        isAcceptedNull.link(&jit);
        jit.store64(scratch, Address(address));
        didStore(false);
    }

    linkIfSet(isInt32);
    if (stores(Kind::FieldInt32)) {
        miss.append(jit.branchIfNotInt32(A1));
        unlessAccepts(FieldWrite::acceptsInt32);
        jit.store32(A1, Address(address));
        didStore(false);
    }
}

static void storeByTransition(CCallHelpers& jit, CCallHelpers::JumpList& miss, bool returns = true, CCallHelpers::JumpList* hasOtherKeys = nullptr, bool mayCreateStorage = false)
{
    using Transition = Typed::StoreTransition;
    constexpr GPRReg transition = T10;
    auto in = [&](ptrdiff_t offset) {
        return Address(transition, offset);
    };
    static_assert(Slot::isStoreTransition == 1ull << 62);
    jit.move(T13, transition);
    jit.lshift64(TrustedImm32(2), transition);
    jit.urshift64(TrustedImm32(2), transition);
    jit.load64(Address(R0, Typed::offsetOfOrderWord), T11);
    (hasOtherKeys ? *hasOtherKeys : miss).append(jit.branch64(CCallHelpers::NotEqual, T11, in(OBJECT_OFFSETOF(Transition, wordsBefore))));
    miss.append(jit.branchTestPtr(CCallHelpers::NonZero, R0, TrustedImm32(PreciseAllocation::halfAlignment)));
    jit.move(R0, T11);
    jit.andPtr(CCallHelpers::TrustedImmPtr(MarkedBlock::blockMask), T11);
    jit.loadPtr(Address(T11, MarkedBlock::offsetOfHeader + MarkedBlock::Header::offsetOfHandle()), T11);
    jit.load32(Address(T11, MarkedBlock::Handle::offsetOfAtomsPerCell()), T11);
    static_assert(MarkedBlock::atomSize == 16 && !MarkedBlock::Header::offsetOfHandle() && !MarkedBlock::Handle::offsetOfAtomsPerCell());
    jit.lshift32(TrustedImm32(4), T11);
    Jump mayNeedStorage;
    if (mayCreateStorage)
        mayNeedStorage = jit.branch32(CCallHelpers::Below, T11, in(OBJECT_OFFSETOF(Transition, sizeIfStorageExists)));
    else
        miss.append(jit.branch32(CCallHelpers::Below, T11, in(OBJECT_OFFSETOF(Transition, size))));
    CCallHelpers::JumpList chainEnds;
    for (unsigned i = 0; i < Transition::maxHolders; ++i) {
        jit.loadPtr(in(OBJECT_OFFSETOF(Transition, holders) + i * sizeof(JSCell*)), T11);
        chainEnds.append(jit.branchTestPtr(CCallHelpers::Zero, T11));
        jit.load32(Address(T11, JSCell::structureIDOffset()), T11);
        miss.append(jit.branch32(CCallHelpers::NotEqual, T11, in(OBJECT_OFFSETOF(Transition, holderStructureIDs) + i * sizeof(uint32_t))));
    }
    chainEnds.link(&jit);
    {
        using Cleared = Transition::Cleared;
        constexpr GPRReg remaining = T11;
        constexpr GPRReg cleared = T12;
        constexpr GPRReg address = T13;
        constexpr GPRReg word = T14;
        jit.load32(in(OBJECT_OFFSETOF(Transition, clearedSlotCount)), remaining);
        jit.loadPtr(in(OBJECT_OFFSETOF(Transition, cleared)), cleared);
        auto next = jit.label();
        Jump areCleared = jit.branchTest32(CCallHelpers::Zero, remaining);
        jit.load32(Address(cleared, OBJECT_OFFSETOF(Cleared, offset)), address);
        jit.addPtr(R0, address);
        jit.load32(Address(cleared, OBJECT_OFFSETOF(Cleared, width)), word);
        Jump isEightBytes = jit.branch32(CCallHelpers::Equal, word, TrustedImm32(8));
        Jump isFourBytes = jit.branch32(CCallHelpers::Equal, word, TrustedImm32(4));
        jit.load64(Address(cleared, OBJECT_OFFSETOF(Cleared, absent)), word);
        jit.store8(word, Address(address));
        Jump didClearByte = jit.jump();
        isFourBytes.link(&jit);
        jit.load64(Address(cleared, OBJECT_OFFSETOF(Cleared, absent)), word);
        jit.store32(word, Address(address));
        Jump didClearFourBytes = jit.jump();
        isEightBytes.link(&jit);
        jit.load64(Address(cleared, OBJECT_OFFSETOF(Cleared, absent)), word);
        jit.store64(word, Address(address));
        didClearByte.link(&jit);
        didClearFourBytes.link(&jit);
        jit.addPtr(TrustedImm32(sizeof(Cleared)), cleared);
        jit.sub32(TrustedImm32(1), remaining);
        jit.jump().linkTo(next, &jit);
        areCleared.link(&jit);
    }
    CCallHelpers::Label hasFieldAddress;
    auto makeStorage = [&] {
        constexpr GPRReg storage = T12;
        constexpr GPRReg allocator = A2;
        constexpr GPRReg size = T13;
        constexpr GPRReg zero = T14;
        static_assert(noOverlap(storage, allocator, size, zero, T11, transition, R0, A1, T9));
        jit.load32(in(OBJECT_OFFSETOF(Transition, extensionSize)), size);
        miss.append(jit.branchTest32(CCallHelpers::Zero, size));
        jit.load32(Address(R0, Typed::offsetOfExtension), storage);
        Jump hasNoExtension = jit.branchTest32(CCallHelpers::Zero, storage);
        decodeCell32(jit, storage, storage);
        Jump hasExtension = jit.branch32(CCallHelpers::BelowOrEqual, size, Address(storage, Typed::offsetOfExtensionSize));

        hasNoExtension.link(&jit);
        jit.load8(Address(R0, JSCell::cellStateOffset()), T11);
        miss.append(jit.branch32(CCallHelpers::BelowOrEqual, T11, Address(instanceGPR, Instance::offsetOfBarrierThreshold())));
        static_assert(MarkedSpace::sizeStep == 2 * sizeof(Allocator) && !(Typed::minExtensionSize % MarkedSpace::sizeStep));
        jit.loadPtr(Address(instanceGPR, Instance::offsetOfAuxiliarySpace()), allocator);
        jit.urshift32(size, TrustedImm32(1), T11);
        jit.addPtr(T11, allocator);
        jit.loadPtr(Address(allocator, CompleteSubspace::offsetOfAllocatorForSizeStep()), allocator);
        miss.append(jit.branchTestPtr(CCallHelpers::Zero, allocator));
        if (Options::forceGCSlowPaths())
            miss.append(jit.jump());
        jit.emitAllocateWithNonNullAllocator(storage, JITAllocator::variable(), allocator, T11, miss, CCallHelpers::SlowAllocationResult::UndefinedBehavior);
        static_assert(!Typed::offsetOfExtensionSize);
        jit.store64(size, Address(storage));
        jit.move(TrustedImm32(0), zero);
        jit.move(TrustedImm32(sizeof(uint64_t)), T11);
        CCallHelpers::Label clearNext = jit.label();
        jit.store64(zero, CCallHelpers::BaseIndex(storage, T11, CCallHelpers::TimesOne));
        jit.add32(TrustedImm32(sizeof(uint64_t)), T11);
        jit.branch32(CCallHelpers::Below, T11, size).linkTo(clearNext, &jit);
        constexpr GPRReg previous = A2;
        jit.load32(Address(R0, Typed::offsetOfExtension), previous);
        Jump hasNothingToCopy = jit.branchTest32(CCallHelpers::Zero, previous);
        decodeCell32(jit, previous, previous);
        static_assert(Typed::offsetOfFirstExtensionSlot == sizeof(uint32_t) && !Typed::offsetOfExtensionSize);
        jit.load32(Address(previous, Typed::offsetOfFirstExtensionSlot), zero);
        jit.store32(zero, Address(storage, Typed::offsetOfFirstExtensionSlot));
        jit.load32(Address(previous, Typed::offsetOfExtensionSize), size);
        jit.move(TrustedImm32(sizeof(uint64_t)), T11);
        CCallHelpers::Label copyNext = jit.label();
        jit.load64(CCallHelpers::BaseIndex(previous, T11, CCallHelpers::TimesOne), zero);
        jit.store64(zero, CCallHelpers::BaseIndex(storage, T11, CCallHelpers::TimesOne));
        jit.add32(TrustedImm32(sizeof(uint64_t)), T11);
        jit.branch32(CCallHelpers::Below, T11, size).linkTo(copyNext, &jit);
        hasNothingToCopy.link(&jit);
#if CPU(ARM64)
        Jump isNotFenced = jit.branchTest8(CCallHelpers::Zero, Address(instanceGPR, Instance::offsetOfMutatorShouldBeFenced()));
        jit.storeFence();
        isNotFenced.link(&jit);
#endif
        encodeCell32(jit, storage, T11);
        jit.store32(T11, Address(R0, Typed::offsetOfExtension));

        hasExtension.link(&jit);
        jit.load64(in(OBJECT_OFFSETOF(Transition, fieldWrite)), T13);
        jit.load32(in(OBJECT_OFFSETOF(Transition, fieldWrite) + sizeof(uint32_t)), T14);
        jit.zeroExtend16To32(T13, T11);
        jit.addPtr(T11, storage);
        jit.jump().linkTo(hasFieldAddress, &jit);
    };
    jit.load64(in(OBJECT_OFFSETOF(Transition, fieldWrite)), T13);
    jit.load32(in(OBJECT_OFFSETOF(Transition, fieldWrite) + sizeof(uint32_t)), T14);
    CCallHelpers::JumpList created;
    storeCompiledField(jit, miss, &created, &hasFieldAddress);
    created.link(&jit);
    jit.storeFence();
    jit.load32(in(OBJECT_OFFSETOF(Transition, structureID)), T11);
    jit.store32(T11, Address(R0, JSCell::structureIDOffset()));
    jit.load64(in(OBJECT_OFFSETOF(Transition, wordsAfter)), T11);
    jit.store64(T11, Address(R0, Typed::offsetOfOrderWord));
    if (returns)
        returnAfterStoring(jit, A1);
    if (mayCreateStorage) {
        RELEASE_ASSERT(returns);
        mayNeedStorage.link(&jit);
        miss.append(jit.branch32(CCallHelpers::Below, T11, in(OBJECT_OFFSETOF(Transition, size))));
        makeStorage();
    }
}

static void generateFrontEndTypedPutExtra(CCallHelpers& jit)
{
    using Known = Typed::KnownStoreTransition;
    constexpr GPRReg cell = A1;
    constexpr GPRReg name = A2;
    constexpr GPRReg value = A3;
    static_assert(noOverlap(cell, name, value, T9, T10, T11, instanceGPR));
    static_assert(sizeof(Known) == 16);
    auto callOperation = [&] {
        jit.loadPtr(Address(instanceGPR, Instance::offsetOfRuntimeTable()), T9);
        jit.loadPtr(Address(T9, offsetInTable(Entry::RawTypedPutExtra)), T9);
        jit.farJump(T9, OperationPtrTag);
    };
    auto leave = [&] {
#if CPU(ARM64)
        jit.popToRestore(CCallHelpers::linkRegister);
#else
        jit.pop(T13);
#endif
    };
    CCallHelpers::JumpList isNotKnown;
    CCallHelpers::JumpList miss;
    jit.load32(Address(cell, JSCell::structureIDOffset()), T11);
    jit.load32(Address(cell, Typed::offsetOfOrderWord), T10);
    jit.xor32(name, T11, T9);
    jit.xor32(T10, T9);
    jit.mul32(TrustedImm32(static_cast<int32_t>(Known::multiplier)), T9, T9);
    jit.urshift32(TrustedImm32(32 - Known::indexBits), T9);
    jit.lshift32(TrustedImm32(4), T9);
    jit.addPtr(Address(instanceGPR, Instance::offsetOfTypedKnownStoreTransitions()), T9);
    isNotKnown.append(jit.branch32(CCallHelpers::NotEqual, T11, Address(T9, OBJECT_OFFSETOF(Known, structureID))));
    isNotKnown.append(jit.branch32(CCallHelpers::NotEqual, name, Address(T9, OBJECT_OFFSETOF(Known, name))));
#if CPU(ARM64)
    jit.pushToSave(CCallHelpers::linkRegister);
#else
    jit.push(T13);
#endif
    jit.loadPtr(Address(T9, OBJECT_OFFSETOF(Known, transition)), T13);
    jit.move(cell, R0);
    jit.move(value, A1);
    storeByTransition(jit, miss, false);
    Jump notCell = jit.branchIfNotCell(A1);
    callStubFromStub(jit, Stub::WriteBarrier);
    notCell.link(&jit);
    leave();
    jit.move(TrustedImm32(0), GPRInfo::returnValueGPR);
    jit.ret();

    miss.link(&jit);
    leave();
    jit.move(A1, value);
    jit.move(R0, cell);
    jit.move(instanceGPR, A0);
    isNotKnown.link(&jit);
    callOperation();
}

static void generateFrontEndTypedConstruct(CCallHelpers& jit)
{
    constexpr GPRReg sp = CCallHelpers::stackPointerRegister;
    constexpr GPRReg callee = A1;
    constexpr GPRReg count = A2;
    constexpr GPRReg values = A3;
    constexpr GPRReg function = T9;
    constexpr GPRReg globalObject = T10;
    constexpr GPRReg scratch = T11;
    constexpr GPRReg copied = A0;
    static_assert(noOverlap(callee, count, values, function, globalObject, scratch, copied, instanceGPR));
    auto inHostFrame = [](CallFrameSlot slot, ptrdiff_t offset = 0) {
        return Address(sp, static_cast<int>(slot) * sizeof(Register) + offset);
    };
    CCallHelpers::JumpList genericPath;
    CCallHelpers::Label start = jit.label();
    genericPath.append(jit.branchIfNotCell(callee));
    jit.load8(Address(callee, JSCell::typeInfoTypeOffset()), scratch);
    Jump isInternalFunction = jit.branch32(CCallHelpers::Equal, scratch, TrustedImm32(InternalFunctionType));
    genericPath.append(jit.branch32(CCallHelpers::NotEqual, scratch, TrustedImm32(JSFunctionType)));
    jit.load32(Address(callee, JSCell::structureIDOffset()), scratch);
    structureWithID(jit, scratch);
    jit.loadPtr(Address(scratch, Structure::classInfoOffset()), scratch);
    genericPath.append(jit.branchPtr(CCallHelpers::Equal, scratch, Address(instanceGPR, Instance::offsetOfBoundFunctionClassInfo())));
    jit.loadPtr(Address(callee, JSFunction::offsetOfExecutableOrRareData()), function);
    Jump hasExecutable = jit.branchTestPtr(CCallHelpers::Zero, function, TrustedImm32(JSFunction::rareDataTag));
    jit.loadPtr(Address(function, FunctionRareData::offsetOfExecutable() - JSFunction::rareDataTag), function);
    hasExecutable.link(&jit);
    genericPath.append(jit.branchIfNotType(function, NativeExecutableType));
    jit.loadPtr(Address(function, NativeExecutable::offsetOfNativeFunctionFor(CodeSpecializationKind::CodeForConstruct)), function);
    jit.loadPtr(Address(callee, JSCallee::offsetOfScopeChain()), globalObject);
    Jump hasFunction = jit.jump();
    isInternalFunction.link(&jit);
    jit.loadPtr(Address(callee, InternalFunction::offsetOfNativeFunctionFor(CodeSpecializationKind::CodeForConstruct)), function);
    jit.loadPtr(Address(callee, InternalFunction::offsetOfGlobalObject()), globalObject);
    hasFunction.link(&jit);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfRuntimeTable()), scratch);
    genericPath.append(jit.branchPtr(CCallHelpers::Equal, function, Address(scratch, offsetInTable(Entry::NonConstructorHostFunction))));

    jit.emitFunctionPrologue();
    static_assert(stackAlignmentRegisters() == 2);
    jit.add32(TrustedImm32(CallFrame::headerSizeInRegisters + 1 + 1), count, scratch);
    jit.and32(TrustedImm32(~1), scratch);
    jit.lshiftPtr(TrustedImm32(3), scratch);
    jit.subPtr(sp, scratch, scratch);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfVM()), copied);
    Jump overflow = jit.branchPtr(CCallHelpers::Above, Address(copied, VM::offsetOfSoftStackLimit()), scratch);
    Jump wrapped = jit.branchPtr(CCallHelpers::Above, scratch, GPRInfo::callFrameRegister);
    jit.move(scratch, sp);
    jit.storePtr(scratch, Address(copied, VM::offsetOfTopCallFrame()));
    jit.storePtr(GPRInfo::callFrameRegister, Address(sp, CallFrame::callerFrameOffset()));
    loadLabelAddress(jit, start, scratch);
    jit.storePtr(scratch, Address(sp, CallFrame::returnPCOffset()));
    jit.store64(TrustedImm32(0), inHostFrame(CallFrameSlot::codeBlock));
    jit.store64(callee, inHostFrame(CallFrameSlot::callee));
    jit.add32(TrustedImm32(1), count, scratch);
    jit.store64(scratch, inHostFrame(CallFrameSlot::argumentCountIncludingThis));
    jit.store64(callee, inHostFrame(CallFrameSlot::thisArgument));
    Jump none = jit.branchTest32(CCallHelpers::Zero, count);
    jit.zeroExtend32ToWord(count, count);
    jit.addPtr(TrustedImm32(inHostFrame(CallFrameSlot::thisArgument, sizeof(Register)).offset), sp, scratch);
    CCallHelpers::Label next = jit.label();
    jit.sub32(TrustedImm32(1), count);
    jit.load64(CCallHelpers::BaseIndex(values, count, CCallHelpers::TimesEight), copied);
    jit.store64(copied, CCallHelpers::BaseIndex(scratch, count, CCallHelpers::TimesEight));
    jit.branchTest32(CCallHelpers::NonZero, count).linkTo(next, &jit);
    none.link(&jit);
    jit.move(globalObject, A0);
    jit.move(sp, A1);
    jit.call(function, HostFunctionPtrTag);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfVM()), scratch);
    jit.loadPtr(Address(scratch, VM::exceptionOffset()), GPRInfo::returnValueGPR2);
    jit.emitFunctionEpilogue();
    jit.ret();

    overflow.link(&jit);
    wrapped.link(&jit);
    jit.emitFunctionEpilogue();
    genericPath.link(&jit);
    jit.move(instanceGPR, A0);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfRuntimeTable()), T9);
    jit.loadPtr(Address(T9, offsetInTable(Entry::RawTypedConstruct)), T9);
    jit.farJump(T9, OperationPtrTag);
}

static void generateFrontEndTypedConstructSuper(CCallHelpers& jit)
{
    constexpr GPRReg sp = CCallHelpers::stackPointerRegister;
    constexpr GPRReg fp = GPRInfo::callFrameRegister;
    constexpr GPRReg classObject = A1;
    constexpr GPRReg newTarget = A2;
    constexpr GPRReg list = A3;
    constexpr GPRReg callee = A4;
    constexpr GPRReg function = T9;
    constexpr GPRReg scratch = T11;
    constexpr GPRReg copied = A0;
    constexpr GPRReg globalObject = classObject;
    constexpr GPRReg count = newTarget;
    constexpr GPRReg values = list;
    static_assert(noOverlap(classObject, newTarget, list, callee, function, scratch, copied, instanceGPR));
    auto inHostFrame = [](CallFrameSlot slot, ptrdiff_t offset = 0) {
        return Address(sp, static_cast<int>(slot) * sizeof(Register) + offset);
    };
    auto given = [](unsigned index) {
        return Address(fp, -static_cast<int>((index + 1) * sizeof(Register)));
    };
    CCallHelpers::JumpList genericPath;
    CCallHelpers::Label start = jit.label();
    jit.emitFunctionPrologue();
    static_assert(stackAlignmentRegisters() == 2);
    jit.subPtr(TrustedImm32(4 * sizeof(Register)), sp);
    jit.store64(classObject, given(0));
    jit.store64(newTarget, given(1));
    jit.store64(list, given(2));
    jit.store64(callee, given(3));
    genericPath.append(jit.branchIfNotCell(classObject));
    genericPath.append(jit.branchIfNotCell(newTarget));
    Jump isProvided = jit.branchTest64(CCallHelpers::NonZero, callee);
    jit.load32(Address(classObject, JSCell::structureIDOffset()), scratch);
    structureWithID(jit, scratch);
    jit.load64(Address(scratch, Structure::prototypeOffset()), callee);
    genericPath.append(jit.branchTest64(CCallHelpers::Zero, callee));
    isProvided.link(&jit);
    genericPath.append(jit.branchIfNotCell(callee));
    jit.load32(Address(callee, JSCell::structureIDOffset()), function);
    structureWithID(jit, function);
    jit.loadPtr(Address(function, Structure::classInfoOffset()), function);
    jit.load8(Address(callee, JSCell::typeInfoTypeOffset()), scratch);
    Jump isInternalFunction = jit.branch32(CCallHelpers::Equal, scratch, TrustedImm32(InternalFunctionType));
    genericPath.append(jit.branch32(CCallHelpers::NotEqual, scratch, TrustedImm32(JSFunctionType)));
    genericPath.append(jit.branchPtr(CCallHelpers::Equal, function, Address(instanceGPR, Instance::offsetOfBoundFunctionClassInfo())));
    jit.load32(Address(instanceGPR, Instance::offsetOfTypedClosureStructureID(0)), scratch);
    structureWithID(jit, scratch);
    Jump isNotClosure = jit.branchPtr(CCallHelpers::NotEqual, function, Address(scratch, Structure::classInfoOffset()));
    jit.load32(Address(callee, JSCell::structureIDOffset()), scratch);
    structureWithID(jit, scratch);
    Jump isOfAnotherInstance = jit.branchPtr(CCallHelpers::NotEqual, Address(scratch, Structure::offsetOfAOTInstance()), instanceGPR);
    Jump isNotDerived = jit.branchTest8(CCallHelpers::Zero, Address(callee, Typed::Closure::offsetOfEntry() + ClosureWord::isDerivedConstructorBit / 8), TrustedImm32(1 << ClosureWord::isDerivedConstructorBit % 8));
    jit.move(TrustedImm32(0), function);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfRuntimeTable()), scratch);
    Jump isDerivedClosure = jit.jump();
    isNotClosure.link(&jit);
    isOfAnotherInstance.link(&jit);
    isNotDerived.link(&jit);
    jit.loadPtr(Address(callee, JSFunction::offsetOfExecutableOrRareData()), function);
    Jump hasExecutable = jit.branchTestPtr(CCallHelpers::Zero, function, TrustedImm32(JSFunction::rareDataTag));
    jit.loadPtr(Address(function, FunctionRareData::offsetOfExecutable() - JSFunction::rareDataTag), function);
    hasExecutable.link(&jit);
    genericPath.append(jit.branchIfNotType(function, NativeExecutableType));
    jit.loadPtr(Address(function, NativeExecutable::offsetOfNativeFunctionFor(CodeSpecializationKind::CodeForConstruct)), function);
    jit.loadPtr(Address(callee, JSCallee::offsetOfScopeChain()), globalObject);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfRuntimeTable()), scratch);
    Jump hasFunction = jit.jump();
    isInternalFunction.link(&jit);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfRuntimeTable()), scratch);
    genericPath.append(jit.branchPtr(CCallHelpers::Equal, function, Address(scratch, offsetInTable(Entry::ErrorConstructorClassInfo))));
    jit.loadPtr(Address(callee, InternalFunction::offsetOfNativeFunctionFor(CodeSpecializationKind::CodeForConstruct)), function);
    jit.loadPtr(Address(callee, InternalFunction::offsetOfGlobalObject()), globalObject);
    hasFunction.link(&jit);
    isDerivedClosure.link(&jit);
    genericPath.append(jit.branchPtr(CCallHelpers::Equal, function, Address(scratch, offsetInTable(Entry::NonConstructorHostFunction))));

    genericPath.append(jit.branchIfNotCell(list));
    genericPath.append(jit.branchIfNotType(list, ArrayType));
    jit.load8(Address(list, JSCell::indexingTypeAndMiscOffset()), scratch);
    jit.and32(TrustedImm32(IndexingShapeMask), scratch);
    jit.loadPtr(Address(list, JSObject::butterflyOffset()), values);
    jit.load32(Address(values, Butterfly::offsetOfPublicLength()), count);
    Jump hasContiguousShape = jit.branch32(CCallHelpers::Equal, scratch, TrustedImm32(ContiguousShape));
    Jump isInt32Shape = jit.branch32(CCallHelpers::Equal, scratch, TrustedImm32(Int32Shape));
    genericPath.append(jit.branch32(CCallHelpers::NotEqual, scratch, TrustedImm32(UndecidedShape)));
    genericPath.append(jit.branchTest32(CCallHelpers::NonZero, count));
    hasContiguousShape.link(&jit);
    isInt32Shape.link(&jit);

    jit.add32(TrustedImm32(CallFrame::headerSizeInRegisters + 1 + 1), count, scratch);
    jit.and32(TrustedImm32(~1), scratch);
    jit.lshiftPtr(TrustedImm32(3), scratch);
    jit.subPtr(sp, scratch, scratch);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfVM()), copied);
    genericPath.append(jit.branchPtr(CCallHelpers::Above, Address(copied, VM::offsetOfSoftStackLimit()), scratch));
    genericPath.append(jit.branchPtr(CCallHelpers::Above, scratch, fp));
    jit.move(scratch, sp);
    jit.storePtr(fp, Address(sp, CallFrame::callerFrameOffset()));
    loadLabelAddress(jit, start, scratch);
    jit.storePtr(scratch, Address(sp, CallFrame::returnPCOffset()));
    jit.store64(TrustedImm32(0), inHostFrame(CallFrameSlot::codeBlock));
    jit.store64(callee, inHostFrame(CallFrameSlot::callee));
    jit.add32(TrustedImm32(1), count, scratch);
    jit.store64(scratch, inHostFrame(CallFrameSlot::argumentCountIncludingThis));
    jit.load64(given(1), copied);
    jit.store64(copied, inHostFrame(CallFrameSlot::thisArgument));
    Jump none = jit.branchTest32(CCallHelpers::Zero, count);
    jit.addPtr(TrustedImm32(inHostFrame(CallFrameSlot::thisArgument, sizeof(Register)).offset), sp, scratch);
    CCallHelpers::Label next = jit.label();
    jit.sub32(TrustedImm32(1), count);
    jit.load64(CCallHelpers::BaseIndex(values, count, CCallHelpers::TimesEight), copied);
    genericPath.append(jit.branchTest64(CCallHelpers::Zero, copied));
    jit.store64(copied, CCallHelpers::BaseIndex(scratch, count, CCallHelpers::TimesEight));
    jit.branchTest32(CCallHelpers::NonZero, count).linkTo(next, &jit);
    none.link(&jit);
    Jump entersClosure = jit.branchTestPtr(CCallHelpers::Zero, function);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfVM()), scratch);
    jit.move(globalObject, A0);
    jit.move(sp, A1);
    jit.storePtr(A1, Address(scratch, VM::offsetOfTopCallFrame()));
    jit.call(function, HostFunctionPtrTag);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfVM()), scratch);
    jit.loadPtr(Address(scratch, VM::exceptionOffset()), GPRInfo::returnValueGPR2);
    jit.emitFunctionEpilogue();
    jit.ret();

    entersClosure.link(&jit);
    static_assert(noOverlap(calleeGPR, thisGPR, T11, argumentGPR(0), argumentGPR(1), instanceGPR));
    jit.load64(inHostFrame(CallFrameSlot::callee), calleeGPR);
    jit.loadPtr(Address(calleeGPR, Typed::Closure::offsetOfEntry()), T11);
    jit.load32(inHostFrame(CallFrameSlot::argumentCountIncludingThis), argumentGPR(0));
    jit.addPtr(TrustedImm32(inHostFrame(CallFrameSlot::thisArgument).offset), sp, argumentGPR(1));
    jit.move(CCallHelpers::TrustedImm64(JSValue::ValueUndefined), thisGPR);
#if CPU(X86_64)
    jit.storePtr(T13, given(0));
#endif
    callStubFromStub(jit, Stub::ConstructClosureList);
#if CPU(X86_64)
    jit.loadPtr(given(0), T13);
#endif
    jit.move(TrustedImm32(0), GPRInfo::returnValueGPR2);
    jit.emitFunctionEpilogue();
    jit.ret();

    genericPath.link(&jit);
    jit.load64(given(0), A1);
    jit.load64(given(1), A2);
    jit.load64(given(2), A3);
    jit.load64(given(3), A4);
    jit.emitFunctionEpilogue();
    jit.move(instanceGPR, A0);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfRuntimeTable()), T9);
    jit.loadPtr(Address(T9, offsetInTable(Entry::RawTypedConstructSuper)), T9);
    jit.farJump(T9, OperationPtrTag);
}

static void generateFrontEndTypedCloneObjectImpl(CCallHelpers& jit, bool extendsClone)
{
    using Copy = Instance::SpreadCopyCacheEntry;
    constexpr GPRReg source = A1;
    constexpr GPRReg first = A3;
    constexpr GPRReg second = A4;
    constexpr GPRReg entry = T11;
    constexpr GPRReg result = T9;
    constexpr GPRReg scratch = A0;
    const GPRReg more = extendsClone ? A2 : A3;
    const GPRReg counter = more;
    static_assert(noOverlap(A0, A1, A2, A3, A4, T9, T11, instanceGPR));
    constexpr int32_t storageLessOneWord = static_cast<int32_t>(JSObject::offsetOfInlineStorage() - sizeof(EncodedJSValue));
    auto inEntry = [&](ptrdiff_t offset) {
        return Address(entry, offset);
    };
    CCallHelpers::JumpList genericPath;
    CCallHelpers::JumpList cannotAllocate;
    genericPath.append(jit.branchIfNotCell(source));
    Jump isNotPlainObject = jit.branchIfNotType(source, FinalObjectType);
    if (extendsClone)
        genericPath.append(isNotPlainObject);
    genericPath.append(jit.branchTestPtr(CCallHelpers::NonZero, Address(source, JSObject::butterflyOffset())));
    if (!extendsClone)
        jit.move(TrustedImm32(0), more);
    jit.load32(Address(source, JSCell::structureIDOffset()), result);
    jit.move(more, scratch);
    jit.urshift64(TrustedImm32(Instance::secondAddedNameShift), scratch);
    jit.xor32(more, scratch);
    jit.mul32(TrustedImm32(static_cast<int32_t>(Instance::spreadCopyHashMultiplier)), scratch, scratch);
    jit.xor32(result, scratch);
    jit.mul32(TrustedImm32(static_cast<int32_t>(Instance::spreadCopyHashMultiplier)), scratch, entry);
    jit.urshift32(TrustedImm32(Instance::spreadCopyHashShift), entry);
    static_assert(sizeof(Copy) == 32);
    jit.lshift32(TrustedImm32(6), entry);
    jit.addPtr(Address(instanceGPR, Instance::offsetOfSpreadCopyCache()), entry);
    CCallHelpers::JumpList notFirstOfPair;
    notFirstOfPair.append(jit.branch32(CCallHelpers::NotEqual, result, inEntry(OBJECT_OFFSETOF(Copy, structureID))));
    notFirstOfPair.append(jit.branch64(CCallHelpers::NotEqual, more, inEntry(OBJECT_OFFSETOF(Copy, more))));
    CCallHelpers::Label isFound = jit.label();
    jit.loadPtr(inEntry(OBJECT_OFFSETOF(Copy, allocator)), scratch);
    jit.emitAllocateWithNonNullAllocator(result, JITAllocator::variable(), scratch, counter, cannotAllocate, CCallHelpers::SlowAllocationResult::UndefinedBehavior);
    jit.load64(inEntry(OBJECT_OFFSETOF(Copy, header)), scratch);
    jit.store64(scratch, Address(result));
    jit.store64(TrustedImm32(0), Address(result, JSObject::butterflyOffset()));
    jit.load8(inEntry(OBJECT_OFFSETOF(Copy, copiedWordCount)), counter);
    Jump copiesNothing = jit.branchTest32(CCallHelpers::Zero, counter);
    CCallHelpers::Label copies = jit.label();
    jit.load64(CCallHelpers::BaseIndex(source, counter, CCallHelpers::TimesEight, storageLessOneWord), scratch);
    jit.store64(scratch, CCallHelpers::BaseIndex(result, counter, CCallHelpers::TimesEight, storageLessOneWord));
    jit.branchSub32(CCallHelpers::NonZero, TrustedImm32(1), counter).linkTo(copies, &jit);
    copiesNothing.link(&jit);
    jit.load8(inEntry(OBJECT_OFFSETOF(Copy, clearedWordCount)), counter);
    Jump clearsNothing = jit.branchTest32(CCallHelpers::Zero, counter);
    jit.load8(inEntry(OBJECT_OFFSETOF(Copy, copiedWordCount)), scratch);
    jit.getEffectiveAddress(CCallHelpers::BaseIndex(result, scratch, CCallHelpers::TimesEight, storageLessOneWord), scratch);
    CCallHelpers::Label clears = jit.label();
    jit.store64(TrustedImm32(0), CCallHelpers::BaseIndex(scratch, counter, CCallHelpers::TimesEight));
    jit.branchSub32(CCallHelpers::NonZero, TrustedImm32(1), counter).linkTo(clears, &jit);
    clearsNothing.link(&jit);
    if (extendsClone) {
        jit.load8(inEntry(OBJECT_OFFSETOF(Copy, places)), counter);
        Jump hasNoFirst = jit.branchTest32(CCallHelpers::Zero, counter);
        jit.store64(first, CCallHelpers::BaseIndex(result, counter, CCallHelpers::TimesEight));
        hasNoFirst.link(&jit);
        jit.load8(inEntry(OBJECT_OFFSETOF(Copy, places) + 1), counter);
        Jump hasNoSecond = jit.branchTest32(CCallHelpers::Zero, counter);
        jit.store64(second, CCallHelpers::BaseIndex(result, counter, CCallHelpers::TimesEight));
        hasNoSecond.link(&jit);
    }
    fenceAfterAllocation(jit, scratch);
    jit.move(result, GPRInfo::returnValueGPR);
    jit.move(TrustedImm32(0), GPRInfo::returnValueGPR2);
    jit.ret();

    notFirstOfPair.link(&jit);
    jit.addPtr(TrustedImm32(sizeof(Copy)), entry);
    genericPath.append(jit.branch32(CCallHelpers::NotEqual, result, inEntry(OBJECT_OFFSETOF(Copy, structureID))));
    genericPath.append(jit.branch64(CCallHelpers::NotEqual, more, inEntry(OBJECT_OFFSETOF(Copy, more))));
    jit.jump().linkTo(isFound, &jit);

    if (!extendsClone) {
        constexpr GPRReg keepsLayout = A2;
        constexpr GPRReg extraProperties = A2;
        constexpr GPRReg described = A4;
#if CPU(ARM64)
        constexpr GPRReg copiedExtraProperties = T10;
#else
        constexpr GPRReg copiedExtraProperties = GPRInfo::returnValueGPR;
#endif
        static_assert(noOverlap(source, extraProperties, described, copiedExtraProperties, entry, result, scratch, A3, instanceGPR));
        CCallHelpers::JumpList cannotCopyRecord;
        isNotPlainObject.link(&jit);
        genericPath.append(jit.branchTest32(CCallHelpers::Zero, keepsLayout));
        jit.load32(Address(source, JSCell::structureIDOffset()), result);
        jit.mul32(TrustedImm32(static_cast<int32_t>(Instance::spreadCopyHashMultiplier)), result, entry);
        jit.urshift32(TrustedImm32(Instance::spreadCopyHashShift), entry);
        jit.lshift32(TrustedImm32(6), entry);
        jit.addPtr(Address(instanceGPR, Instance::offsetOfSpreadCopyCache()), entry);
        Jump isFirstOfPair = jit.branch32(CCallHelpers::Equal, result, inEntry(OBJECT_OFFSETOF(Copy, structureID)));
        jit.addPtr(TrustedImm32(sizeof(Copy)), entry);
        genericPath.append(jit.branch32(CCallHelpers::NotEqual, result, inEntry(OBJECT_OFFSETOF(Copy, structureID))));
        isFirstOfPair.link(&jit);
        jit.load32(Address(source, Typed::offsetOfOrderWord), scratch);
        jit.and32(TrustedImm32(static_cast<int32_t>(~Typed::orderAndCountMask)), scratch);
        genericPath.append(jit.branch32(CCallHelpers::NotEqual, scratch, TrustedImm32(static_cast<int32_t>(Typed::orderWordHasExtraProperties))));
        jit.load64(inEntry(OBJECT_OFFSETOF(Copy, more)), counter);
        Jump hasNoNarrowNumbers = jit.branchTest64(CCallHelpers::Zero, counter);
        CCallHelpers::Label testsNarrowNumber = jit.label();
        jit.countTrailingZeros64WithoutNullCheck(counter, scratch);
        jit.load32(CCallHelpers::BaseIndex(source, scratch, CCallHelpers::TimesFour, Typed::offsetOfFirstField), scratch);
        jit.sub32(TrustedImm32(Typed::nullInt32 + 1), scratch);
        genericPath.append(jit.branch32(CCallHelpers::Below, scratch, TrustedImm32(Typed::minInlineInt32 - (Typed::nullInt32 + 1))));
        jit.add64(TrustedImm32(-1), counter, scratch);
        jit.and64(scratch, counter);
        jit.branchTest64(CCallHelpers::NonZero, counter).linkTo(testsNarrowNumber, &jit);
        hasNoNarrowNumbers.link(&jit);
        structureWithID(jit, result);
        jit.load64(Address(result, Structure::offsetOfExtraPropertiesStructureID()), described);
        jit.urshift64(described, TrustedImm32(Structure::extraPropertiesOffsetShift), counter);
        jit.and32(TrustedImm32(UINT16_MAX), counter);
        jit.load32(CCallHelpers::BaseIndex(source, counter, CCallHelpers::TimesOne), extraProperties);
        decodeCell32(jit, extraProperties, extraProperties);
        cannotCopyRecord.append(jit.branch32(CCallHelpers::NotEqual, described, Address(extraProperties, JSCell::structureIDOffset())));
        cannotCopyRecord.append(jit.branchTestPtr(CCallHelpers::NonZero, Address(extraProperties, JSObject::butterflyOffset())));
        static_assert(MarkedSpace::sizeStep == 2 * sizeof(Allocator));
        jit.urshift64(described, TrustedImm32(Structure::extraPropertiesSizeShift + 1), scratch);
        jit.loadPtr(Address(instanceGPR, Instance::offsetOfCellSpace()), result);
        jit.loadPtr(CCallHelpers::BaseIndex(result, scratch, CCallHelpers::TimesOne, CompleteSubspace::offsetOfAllocatorForSizeStep()), result);
        cannotCopyRecord.append(jit.branchTestPtr(CCallHelpers::Zero, result));
        jit.emitAllocateWithNonNullAllocator(copiedExtraProperties, JITAllocator::variable(), result, scratch, cannotCopyRecord, CCallHelpers::SlowAllocationResult::UndefinedBehavior);
        jit.store32(described, Address(copiedExtraProperties, JSCell::structureIDOffset()));
        jit.store32(TrustedImm32(JSFinalObject::defaultTypeInfoBlob()), Address(copiedExtraProperties, JSCell::indexingTypeAndMiscOffset()));
        jit.urshift64(described, TrustedImm32(Structure::extraPropertiesSizeShift), counter);
        CCallHelpers::Label copiesProperty = jit.label();
        jit.sub32(TrustedImm32(sizeof(EncodedJSValue)), counter);
        jit.load64(CCallHelpers::BaseIndex(extraProperties, counter, CCallHelpers::TimesOne), scratch);
        jit.store64(scratch, CCallHelpers::BaseIndex(copiedExtraProperties, counter, CCallHelpers::TimesOne));
        jit.branch32(CCallHelpers::Above, counter, TrustedImm32(JSObject::butterflyOffset())).linkTo(copiesProperty, &jit);
        jit.loadPtr(inEntry(OBJECT_OFFSETOF(Copy, allocator)), scratch);
        jit.emitAllocateWithNonNullAllocator(result, JITAllocator::variable(), scratch, counter, cannotCopyRecord, CCallHelpers::SlowAllocationResult::UndefinedBehavior);
        jit.load64(inEntry(OBJECT_OFFSETOF(Copy, header)), scratch);
        jit.store64(scratch, Address(result));
        jit.load8(inEntry(OBJECT_OFFSETOF(Copy, copiedWordCount)), counter);
        CCallHelpers::Label copiesWord = jit.label();
        jit.load64(CCallHelpers::BaseIndex(source, counter, CCallHelpers::TimesEight), scratch);
        jit.store64(scratch, CCallHelpers::BaseIndex(result, counter, CCallHelpers::TimesEight));
        jit.branchSub32(CCallHelpers::NonZero, TrustedImm32(1), counter).linkTo(copiesWord, &jit);
        jit.load8(inEntry(OBJECT_OFFSETOF(Copy, clearedWordCount)), counter);
        Jump hasNoRoomBehind = jit.branchTest32(CCallHelpers::Zero, counter);
        jit.load8(inEntry(OBJECT_OFFSETOF(Copy, copiedWordCount)), scratch);
        jit.getEffectiveAddress(CCallHelpers::BaseIndex(result, scratch, CCallHelpers::TimesEight), scratch);
        CCallHelpers::Label clearsWord = jit.label();
        jit.store64(TrustedImm32(0), CCallHelpers::BaseIndex(scratch, counter, CCallHelpers::TimesEight));
        jit.branchSub32(CCallHelpers::NonZero, TrustedImm32(1), counter).linkTo(clearsWord, &jit);
        hasNoRoomBehind.link(&jit);
        jit.urshift64(described, TrustedImm32(Structure::extraPropertiesOffsetShift), counter);
        jit.and32(TrustedImm32(UINT16_MAX), counter);
        encodeCell32(jit, copiedExtraProperties, scratch);
        jit.store32(scratch, CCallHelpers::BaseIndex(result, counter, CCallHelpers::TimesOne));
        fenceAfterAllocation(jit, scratch);
        jit.move(result, GPRInfo::returnValueGPR);
        jit.move(TrustedImm32(0), GPRInfo::returnValueGPR2);
        jit.ret();

        cannotCopyRecord.link(&jit);
        jit.move(TrustedImm32(1), keepsLayout);
        genericPath.append(jit.jump());
    }

    cannotAllocate.link(&jit);
    if (extendsClone)
        jit.load64(inEntry(OBJECT_OFFSETOF(Copy, more)), more);
    genericPath.link(&jit);
    jit.move(instanceGPR, A0);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfRuntimeTable()), T9);
    jit.loadPtr(Address(T9, offsetInTable(extendsClone ? Entry::RawTypedCloneObjectAndExtend : Entry::RawTypedCloneObject)), T9);
    jit.farJump(T9, OperationPtrTag);
}
static void generateFrontEndTypedCloneObject(CCallHelpers& jit) { generateFrontEndTypedCloneObjectImpl(jit, false); }
static void generateFrontEndTypedCloneObjectAndExtend(CCallHelpers& jit) { generateFrontEndTypedCloneObjectImpl(jit, true); }
static void generateFrontEndTypedCloneObjectAndExtendWithNumber(CCallHelpers& jit)
{
    constexpr FPRReg value = FPRInfo::argumentFPR0;
    constexpr GPRReg first = A3;
    constexpr GPRReg second = A4;
    constexpr GPRReg boxedDouble = T11;
    static_assert(noOverlap(A0, A1, A2, first, second, boxedDouble, instanceGPR));
    jit.moveDoubleTo64(value, boxedDouble);
#if CPU(ARM64)
    jit.sub64(GPRInfo::numberTagRegister, boxedDouble);
    jit.move(CCallHelpers::TrustedImm64(JSValue::encode(jsNaN())), first);
    jit.compareOnFlagsDouble(value, value);
    jit.m_assembler.csel<64>(boxedDouble, boxedDouble, first, ARM64Assembler::ConditionEQ);
    setEqualIfExactInt32(jit, value, first, boxedDouble, second, FPRInfo::fpRegT1);
    jit.addZeroExtend64(GPRInfo::numberTagRegister, first, first);
    jit.m_assembler.csel<64>(first, first, boxedDouble, ARM64Assembler::ConditionEQ);
#else
    constexpr GPRReg difference = A0;
    constexpr FPRReg converted = FPRInfo::fpRegT1;
    jit.truncateDoubleToInt32(value, first);
    jit.convertInt32ToDouble(first, converted);
    jit.moveDoubleTo64(converted, difference);
    jit.add64(numberTag, first);
    jit.xor64(boxedDouble, difference);
    jit.sub64(numberTag, boxedDouble);
    if (CCallHelpers::supportsAVX())
        jit.m_assembler.vucomisd_rr(value, value);
    else
        jit.m_assembler.ucomisd_rr(value, value);
    jit.m_assembler.cmovq_mr(X86Assembler::ConditionP, static_cast<int>(Instance::offsetOfBoxedNaN()), instanceGPR, boxedDouble);
    jit.m_assembler.testq_rr(difference, difference);
    jit.m_assembler.cmovq_rr(X86Assembler::ConditionNE, boxedDouble, first);
#endif
    jit.move(TrustedImm32(0), second);
    s_callsBetweenStubs->append({ jit.nearTailCall(), Stub::FrontEndTypedCloneObjectAndExtend });
}
static void generateFrontEndTypedCloneObjectWithSubtypeCheck(CCallHelpers& jit)
{
    constexpr GPRReg source = A1;
    constexpr GPRReg keepsLayout = A2;
    constexpr GPRReg lastSubtypeShape = A3;
    constexpr GPRReg subtypeShapeCount = A4;
    constexpr GPRReg distanceFromLastShape = T9;
    static_assert(noOverlap(A0, source, keepsLayout, lastSubtypeShape, subtypeShapeCount, distanceFromLastShape));
    CCallHelpers::JumpList isNotRecord;
    isNotRecord.append(jit.branchIfNotCell(source));
    isNotRecord.append(jit.branchIfType(source, FinalObjectType));
    static_assert(Typed::shapeWordOf(1) == 0u - 1);
    jit.load32(Address(source, Typed::offsetOfShapeWord), distanceFromLastShape);
    jit.add32(lastSubtypeShape, distanceFromLastShape);
    Jump isSubtype = jit.branch32(CCallHelpers::Below, distanceFromLastShape, subtypeShapeCount);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfRuntimeTable()), T9);
    jit.loadPtr(Address(T9, offsetInTable(Entry::RawTypedCloneObjectWithSubtypeCheck)), T9);
    jit.farJump(T9, OperationPtrTag);
    isSubtype.link(&jit);
    jit.move(TrustedImm32(1), keepsLayout);
    s_callsBetweenStubs->append({ jit.nearTailCall(), Stub::FrontEndTypedCloneObject });
    isNotRecord.link(&jit);
    jit.move(TrustedImm32(0), keepsLayout);
    s_callsBetweenStubs->append({ jit.nearTailCall(), Stub::FrontEndTypedCloneObject });
}

static void generateFrontEndTypedCloneObjectAs(CCallHelpers& jit)
{
    using CacheEntry = Typed::TypedCloneCacheEntry;
    using Plan = Typed::TypedClonePlan;
    using Move = Typed::TypedCloneMove;
    constexpr GPRReg source = A1;
    constexpr GPRReg target = A2;
    constexpr GPRReg counter = A3;
    constexpr GPRReg value = A4;
    constexpr GPRReg plan = T11;
    constexpr GPRReg cursor = plan;
    constexpr GPRReg result = T9;
    constexpr GPRReg scratch = A0;
#if CPU(ARM64)
    constexpr GPRReg kind = T10;
#else
    constexpr GPRReg kind = GPRInfo::returnValueGPR;
#endif
    constexpr FPRReg number = FPRInfo::fpRegT0;
    static_assert(noOverlap(source, target, counter, value, plan, result, scratch, kind, instanceGPR));
    static_assert(sizeof(CacheEntry) == 32 && sizeof(JSCell) == sizeof(uint64_t));
    CCallHelpers::JumpList clonesAsPlainObject;
    CCallHelpers::JumpList asksRuntime;
    clonesAsPlainObject.append(jit.branchIfNotCell(source));
    clonesAsPlainObject.append(jit.branchIfNotType(source, FinalObjectType));
    clonesAsPlainObject.append(jit.branchTestPtr(CCallHelpers::NonZero, Address(source, JSObject::butterflyOffset())));
    jit.load32(Address(source, JSCell::structureIDOffset()), result);
    jit.move(target, scratch);
    jit.urshift64(TrustedImm32(32), scratch);
    jit.xor32(target, scratch);
    jit.xor32(result, scratch);
    jit.mul32(TrustedImm32(static_cast<int32_t>(CacheEntry::multiplier)), scratch, plan);
    jit.urshift32(TrustedImm32(32 - CacheEntry::indexBits), plan);
    jit.lshift32(TrustedImm32(5), plan);
    jit.addPtr(Address(instanceGPR, Instance::offsetOfTypedCloneCache()), plan);
    asksRuntime.append(jit.branch32(CCallHelpers::NotEqual, result, Address(plan, OBJECT_OFFSETOF(CacheEntry, structureID))));
    asksRuntime.append(jit.branch64(CCallHelpers::NotEqual, target, Address(plan, OBJECT_OFFSETOF(CacheEntry, target))));
    jit.loadPtr(Address(plan, OBJECT_OFFSETOF(CacheEntry, plan)), plan);
    jit.load32(Address(plan, OBJECT_OFFSETOF(Plan, path)), scratch);
    clonesAsPlainObject.append(jit.branch32(CCallHelpers::Equal, scratch, TrustedImm32(static_cast<int32_t>(Plan::Path::PlainClone))));
    asksRuntime.append(jit.branch32(CCallHelpers::NotEqual, scratch, TrustedImm32(static_cast<int32_t>(Plan::Path::Stub))));
    jit.loadPtr(Address(plan, OBJECT_OFFSETOF(Plan, allocator)), scratch);
    jit.emitAllocateWithNonNullAllocator(result, JITAllocator::variable(), scratch, counter, asksRuntime, CCallHelpers::SlowAllocationResult::UndefinedBehavior);
    jit.load64(Address(plan, OBJECT_OFFSETOF(Plan, header)), scratch);
    jit.store64(scratch, Address(result));
    jit.load32(Address(plan, OBJECT_OFFSETOF(Plan, bodyWordCount)), counter);
    jit.loadPtr(Address(plan, OBJECT_OFFSETOF(Plan, bodyWords)), scratch);
    CCallHelpers::Label copiesWord = jit.label();
    jit.load64(CCallHelpers::BaseIndex(scratch, counter, CCallHelpers::TimesEight, -static_cast<int32_t>(sizeof(uint64_t))), value);
    jit.store64(value, CCallHelpers::BaseIndex(result, counter, CCallHelpers::TimesEight));
    jit.branchSub32(CCallHelpers::NonZero, TrustedImm32(1), counter).linkTo(copiesWord, &jit);
    jit.load32(Address(plan, OBJECT_OFFSETOF(Plan, moveCount)), counter);
    Jump hasNoMoves = jit.branchTest32(CCallHelpers::Zero, counter);
    jit.loadPtr(Address(plan, OBJECT_OFFSETOF(Plan, firstMove)), cursor);
    CCallHelpers::BaseIndex slot(result, scratch, CCallHelpers::TimesOne);
    CCallHelpers::Label moves = jit.label();
    jit.load16(Address(cursor, OBJECT_OFFSETOF(Move, from)), scratch);
    jit.load64(CCallHelpers::BaseIndex(source, scratch, CCallHelpers::TimesOne), value);
    jit.load8(Address(cursor, OBJECT_OFFSETOF(Move, kind)), kind);
    jit.load16(Address(cursor, OBJECT_OFFSETOF(Move, to)), scratch);
    Jump isNumber = jit.branch32(CCallHelpers::Equal, kind, TrustedImm32(static_cast<int32_t>(Move::Kind::NumberAsDouble)));
    Jump isInlineInt32 = jit.branch32(CCallHelpers::Equal, kind, TrustedImm32(static_cast<int32_t>(Move::Kind::NumberAsInlineInt32)));
    Jump isBoolean = jit.branch32(CCallHelpers::Equal, kind, TrustedImm32(static_cast<int32_t>(Move::Kind::BooleanAsByte)));
    Jump isString = jit.branch32(CCallHelpers::NotEqual, kind, TrustedImm32(static_cast<int32_t>(Move::Kind::Value)));
    jit.store64(value, slot);
    CCallHelpers::Label advances = jit.label();
    jit.addPtr(TrustedImm32(sizeof(Move)), cursor);
    jit.branchSub32(CCallHelpers::NonZero, TrustedImm32(1), counter).linkTo(moves, &jit);
    hasNoMoves.link(&jit);
    fenceAfterAllocation(jit, scratch);
    jit.move(result, GPRInfo::returnValueGPR);
    jit.move(TrustedImm32(0), GPRInfo::returnValueGPR2);
    jit.ret();

    isNumber.link(&jit);
    Jump isNotInt32 = jit.branch64(CCallHelpers::Below, value, numberTag);
    jit.convertInt32ToDouble(value, number);
    jit.storeDouble(number, slot);
    jit.jump().linkTo(advances, &jit);
    isNotInt32.link(&jit);
    clonesAsPlainObject.append(jit.branchTest64(CCallHelpers::Zero, value, numberTag));
    jit.add64(numberTag, value);
    jit.store64(value, slot);
    jit.jump().linkTo(advances, &jit);

    isInlineInt32.link(&jit);
    clonesAsPlainObject.append(jit.branch64(CCallHelpers::Below, value, numberTag));
    clonesAsPlainObject.append(jit.branch32(CCallHelpers::LessThan, value, TrustedImm32(Typed::minInlineInt32)));
    jit.store32(value, slot);
    jit.jump().linkTo(advances, &jit);

    isString.link(&jit);
    Jump isNotCell = jit.branchIfNotCell(value);
    clonesAsPlainObject.append(jit.branchIfNotString(value));
    encodeCell32(jit, value, value);
    jit.store32(value, slot);
    jit.jump().linkTo(advances, &jit);
    isNotCell.link(&jit);
    clonesAsPlainObject.append(jit.branch32(CCallHelpers::NotEqual, kind, TrustedImm32(static_cast<int32_t>(Move::Kind::NullableStringAsCell32))));
    jit.store32(value, slot);
    jit.and64(TrustedImm32(~JSValue::UndefinedTag), value);
    clonesAsPlainObject.append(jit.branch64(CCallHelpers::NotEqual, value, TrustedImm32(JSValue::ValueNull)));
    jit.jump().linkTo(advances, &jit);

    isBoolean.link(&jit);
    jit.xor64(TrustedImm32(JSValue::ValueFalse), value);
    clonesAsPlainObject.append(jit.branchTest64(CCallHelpers::NonZero, value, TrustedImm32(~1)));
    jit.store8(value, slot);
    jit.jump().linkTo(advances, &jit);

    clonesAsPlainObject.link(&jit);
    jit.move(TrustedImm32(0), A2);
    s_callsBetweenStubs->append({ jit.nearTailCall(), Stub::FrontEndTypedCloneObject });

    asksRuntime.link(&jit);
    jit.move(instanceGPR, A0);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfRuntimeTable()), T9);
    jit.loadPtr(Address(T9, offsetInTable(Entry::RawTypedCloneObjectAs)), T9);
    jit.farJump(T9, OperationPtrTag);
}

static void generateConvertByPlan(CCallHelpers& jit)
{
    using CacheEntry = Typed::ConversionCacheEntry;
    using Plan = Typed::ConversionPlan;
    using Move = Typed::ConversionMove;
    constexpr GPRReg sp = CCallHelpers::stackPointerRegister;
    constexpr GPRReg object = A1;
    constexpr GPRReg typeAndReason = A2;
    constexpr GPRReg destination = A2;
    constexpr GPRReg counter = A3;
    constexpr GPRReg value = A4;
    constexpr GPRReg plan = T9;
    constexpr GPRReg cursor = T11;
    constexpr GPRReg scratch = A0;
#if CPU(ARM64)
    constexpr GPRReg kind = T10;
#else
    constexpr GPRReg kind = GPRInfo::returnValueGPR;
#endif
    constexpr FPRReg number = FPRInfo::fpRegT0;
    constexpr int32_t offsetOfTypeAndReason = Plan::maxCellSize;
    constexpr int32_t offsetOfObject = Plan::maxCellSize + sizeof(uint64_t);
    constexpr int32_t offsetOfNumber = Plan::maxCellSize + 2 * sizeof(uint64_t);
    constexpr int32_t offsetOfCounter = Plan::maxCellSize + 3 * sizeof(uint64_t);
    constexpr int32_t offsetOfPlan = Plan::maxCellSize + 4 * sizeof(uint64_t);
    constexpr int32_t offsetOfCursor = Plan::maxCellSize + 5 * sizeof(uint64_t);
    constexpr int32_t offsetOfDestination = Plan::maxCellSize + 6 * sizeof(uint64_t);
    constexpr int32_t offsetOfSource = Plan::maxCellSize + 7 * sizeof(uint64_t);
#if CPU(ARM64)
    constexpr int32_t offsetOfReturnAddress = Plan::maxCellSize + 8 * sizeof(uint64_t);
#endif
    constexpr int32_t frameSize = Plan::maxCellSize + 10 * sizeof(uint64_t);
    static_assert(offsetOfObject == offsetOfTypeAndReason + static_cast<int32_t>(sizeof(uint64_t)));
    using Text = Typed::ConversionText;
    static_assert(sizeof(Text) == 16);
    auto loadTextWord = [&](GPRReg string, GPRReg characters, GPRReg index, GPRReg character, GPRReg length, CCallHelpers::JumpList& notShortString) {
        notShortString.append(jit.branchIfNotString(string));
        jit.loadPtr(Address(string, JSString::offsetOfValue()), characters);
        notShortString.append(jit.branchIfRopeStringImpl(characters));
        notShortString.append(jit.branchTest32(CCallHelpers::Zero, Address(characters, StringImpl::flagsOffset()), TrustedImm32(StringImpl::flagIs8Bit())));
        jit.load32(Address(characters, StringImpl::lengthMemoryOffset()), length);
        notShortString.append(jit.branch32(CCallHelpers::Above, length, TrustedImm32(7)));
        jit.loadPtr(Address(characters, StringImpl::dataOffset()), characters);
        jit.move(length, index);
        jit.move(TrustedImm32(0), string);
        Jump isEmpty = jit.branchTest32(CCallHelpers::Zero, index);
        CCallHelpers::Label next = jit.label();
        jit.lshift64(TrustedImm32(8), string);
        jit.load8(CCallHelpers::BaseIndex(characters, index, CCallHelpers::TimesOne, -1), character);
        jit.or64(character, string);
        jit.branchSub32(CCallHelpers::NonZero, TrustedImm32(1), index).linkTo(next, &jit);
        isEmpty.link(&jit);
        jit.lshift64(TrustedImm32(8), string);
        jit.add32(TrustedImm32(1), length);
        jit.or64(length, string);
    };
    auto findText = [&](GPRReg word, GPRReg text, GPRReg remaining, CCallHelpers::JumpList& isNotFound) {
        CCallHelpers::Label next = jit.label();
        Jump isFound = jit.branch64(CCallHelpers::Equal, word, Address(text, OBJECT_OFFSETOF(Text, text)));
        jit.addPtr(TrustedImm32(sizeof(Text)), text);
        jit.branchSub32(CCallHelpers::NonZero, TrustedImm32(1), remaining).linkTo(next, &jit);
        isNotFound.append(jit.jump());
        isFound.link(&jit);
        jit.load64(Address(text, OBJECT_OFFSETOF(Text, meaning)), word);
    };
    static_assert(noOverlap(object, typeAndReason, counter, value, plan, cursor, scratch, kind, instanceGPR));
    static_assert(sizeof(CacheEntry) == 16 && MarkedBlock::atomSize == 2 * sizeof(uint64_t));
    static_assert(!JSCell::structureIDOffset() && JSCell::indexingTypeAndMiscOffset() == 4 && JSCell::typeInfoFlagsOffset() == 6 && JSCell::cellStateOffset() == 7);
    constexpr uint64_t preservedHeaderBits = 0xffull << 56 | static_cast<uint64_t>(TypeInfoPerCellBit) << 48 | static_cast<uint64_t>(static_cast<uint8_t>(~AllArrayTypesAndHistory)) << 32;
    CCallHelpers::JumpList misses;
    CCallHelpers::JumpList hasNoConversionPlan;
    CCallHelpers::JumpList fails;
    auto copyWords = [&](GPRReg from, GPRReg to) {
        jit.load32(Address(plan, OBJECT_OFFSETOF(Plan, wordCount)), counter);
#if CPU(ARM64)
        static_assert(noOverlap(T12, T13, object, typeAndReason, counter, value, plan, cursor, scratch, kind, instanceGPR));
        jit.move(from, T12);
        jit.move(to, T13);
        CCallHelpers::Label copiesPair = jit.label();
        jit.loadPair64(CCallHelpers::PostIndexAddress(T12, 2 * sizeof(uint64_t)), value, kind);
        jit.storePair64(value, kind, CCallHelpers::PostIndexAddress(T13, 2 * sizeof(uint64_t)));
#else
        CCallHelpers::Label copiesPair = jit.label();
        jit.load64(CCallHelpers::BaseIndex(from, counter, CCallHelpers::TimesEight, -2 * static_cast<int32_t>(sizeof(uint64_t))), value);
        jit.load64(CCallHelpers::BaseIndex(from, counter, CCallHelpers::TimesEight, -static_cast<int32_t>(sizeof(uint64_t))), kind);
        jit.store64(value, CCallHelpers::BaseIndex(to, counter, CCallHelpers::TimesEight, -2 * static_cast<int32_t>(sizeof(uint64_t))));
        jit.store64(kind, CCallHelpers::BaseIndex(to, counter, CCallHelpers::TimesEight, -static_cast<int32_t>(sizeof(uint64_t))));
#endif
        jit.branchSub32(CCallHelpers::NonZero, TrustedImm32(2), counter).linkTo(copiesPair, &jit);
    };

    misses.append(jit.branchIfNotCell(object));
    jit.load32(Address(object, JSCell::structureIDOffset()), scratch);
    jit.xor32(typeAndReason, scratch, plan);
    jit.mul32(TrustedImm32(static_cast<int32_t>(CacheEntry::multiplier)), plan, plan);
    jit.urshift32(TrustedImm32(32 - CacheEntry::indexBits), plan);
    jit.lshift32(TrustedImm32(4), plan);
    jit.addPtr(Address(instanceGPR, Instance::offsetOfTypedConversionCache()), plan);
    hasNoConversionPlan.append(jit.branch32(CCallHelpers::NotEqual, scratch, Address(plan, OBJECT_OFFSETOF(CacheEntry, structureID))));
    hasNoConversionPlan.append(jit.branch32(CCallHelpers::NotEqual, typeAndReason, Address(plan, OBJECT_OFFSETOF(CacheEntry, typeAndReason))));
    jit.loadPtr(Address(plan, OBJECT_OFFSETOF(CacheEntry, plan)), plan);
    jit.load32(Address(plan, OBJECT_OFFSETOF(Plan, discriminantFrom)), scratch);
    Jump hasNoDiscriminant = jit.branchTest32(CCallHelpers::Zero, scratch);
    jit.load64(CCallHelpers::BaseIndex(object, scratch, CCallHelpers::TimesOne), value);
    misses.append(jit.branchIfNotCell(value));
    loadTextWord(value, scratch, counter, kind, cursor, misses);
    jit.loadPtr(Address(plan, OBJECT_OFFSETOF(Plan, firstText)), scratch);
    jit.load32(Address(plan, OBJECT_OFFSETOF(Plan, memberCount)), counter);
    findText(value, scratch, counter, misses);
    jit.move(value, plan);
    hasNoDiscriminant.link(&jit);
    jit.subPtr(TrustedImm32(frameSize), sp);
    jit.storePair64(typeAndReason, object, sp, TrustedImm32(offsetOfTypeAndReason));
    jit.loadPtr(Address(plan, OBJECT_OFFSETOF(Plan, allocator)), scratch);
    Jump convertsInPlace = jit.branchTestPtr(CCallHelpers::Zero, scratch);
    jit.emitAllocateWithNonNullAllocator(destination, JITAllocator::variable(), scratch, counter, fails, CCallHelpers::SlowAllocationResult::UndefinedBehavior);
    Jump hasDestination = jit.jump();
    convertsInPlace.link(&jit);
    fails.append(jit.branchTest8(CCallHelpers::NonZero, Address(instanceGPR, Instance::offsetOfMutatorShouldBeFenced())));
    fails.append(jit.branchTestPtr(CCallHelpers::NonZero, object, TrustedImm32(PreciseAllocation::halfAlignment)));
    jit.move(object, scratch);
    jit.andPtr(CCallHelpers::TrustedImmPtr(MarkedBlock::blockMask), scratch);
    jit.loadPtr(Address(scratch, MarkedBlock::offsetOfHeader + MarkedBlock::Header::offsetOfHandle()), scratch);
    jit.load32(Address(scratch, MarkedBlock::Handle::offsetOfAtomsPerCell()), scratch);
    jit.lshift32(TrustedImm32(1), scratch);
    fails.append(jit.branch32(CCallHelpers::NotEqual, scratch, Address(plan, OBJECT_OFFSETOF(Plan, wordCount))));
    jit.move(sp, destination);
    hasDestination.link(&jit);
    jit.loadPtr(Address(plan, OBJECT_OFFSETOF(Plan, words)), scratch);
    copyWords(scratch, destination);

    jit.load32(Address(plan, OBJECT_OFFSETOF(Plan, moveCount)), counter);
    Jump hasNoMoves = jit.branchTest32(CCallHelpers::Zero, counter);
    jit.loadPtr(Address(plan, OBJECT_OFFSETOF(Plan, firstMove)), cursor);
    CCallHelpers::BaseIndex slot(destination, scratch, CCallHelpers::TimesOne);
    auto loadSlotOffset = [&] {
        jit.load16(Address(cursor, OBJECT_OFFSETOF(Move, to)), scratch);
    };
    auto isKind = [&](Move::Kind expected) {
        return jit.branch32(CCallHelpers::Equal, kind, TrustedImm32(static_cast<int32_t>(expected)));
    };
    CCallHelpers::JumpList mayBeUndefinedOrNull;
    CCallHelpers::JumpList storesCell;
    CCallHelpers::Label moves = jit.label();
    jit.load16(Address(cursor, OBJECT_OFFSETOF(Move, from)), scratch);
    jit.load8(Address(cursor, OBJECT_OFFSETOF(Move, kind)), kind);
    jit.load64(CCallHelpers::BaseIndex(object, scratch, CCallHelpers::TimesOne), value);
    Jump isCellOfShape = isKind(Move::Kind::CellOfShape);
    Jump isCellOfType = isKind(Move::Kind::CellOfType);
    Jump isInlineInt32 = isKind(Move::Kind::NumberAsInlineInt32);
    Jump isNumber = isKind(Move::Kind::NumberAsDouble);
    Jump isFunction = isKind(Move::Kind::Function);
    Jump isObject = isKind(Move::Kind::Object);
    Jump isBoolean = isKind(Move::Kind::BooleanAsByte);
    Jump isBooleanAsValueByte = isKind(Move::Kind::BooleanAsValueByte);
    Jump isLiteralString = isKind(Move::Kind::LiteralString);
    Jump isSwitchOfSource = isKind(Move::Kind::SwitchSource);
    Jump valueIsNotCell = jit.branchIfNotCell(value);
    Jump valueIsNoPlainObjectType = jit.branch8(CCallHelpers::NotEqual, Address(value, JSCell::typeInfoTypeOffset()), TrustedImm32(ObjectType));
    fails.append(jit.branch32(CCallHelpers::GreaterThanOrEqual, Address(value, Typed::offsetOfShapeWord), TrustedImm32(0)));
    valueIsNotCell.link(&jit);
    valueIsNoPlainObjectType.link(&jit);
    loadSlotOffset();
    CCallHelpers::Label storesValue = jit.label();
    jit.store64(value, slot);
    CCallHelpers::Label advances = jit.label();
    jit.addPtr(TrustedImm32(sizeof(Move)), cursor);
    jit.branchSub32(CCallHelpers::NonZero, TrustedImm32(1), counter).linkTo(moves, &jit);
    hasNoMoves.link(&jit);

    Jump allocates = jit.branchTest32(CCallHelpers::NonZero, Address(plan, OBJECT_OFFSETOF(Plan, allocates)));
    CCallHelpers::Label laysCellOverObject = jit.label();
    jit.load64(Address(object), value);
    jit.and64(CCallHelpers::TrustedImm64(preservedHeaderBits), value);
    jit.load64(Address(sp), scratch);
    jit.or64(scratch, value);
    jit.store64(value, Address(sp));
    copyWords(sp, object);
    jit.addPtr(TrustedImm32(frameSize), sp);
    jit.move(object, GPRInfo::returnValueGPR);
    jit.ret();

    allocates.link(&jit);
    jit.loadPtr(Address(plan, OBJECT_OFFSETOF(Plan, allocatorOfExtraProperties)), scratch);
    Jump isCopy = jit.branchTestPtr(CCallHelpers::Zero, scratch);
    fails.append(jit.branch8(CCallHelpers::BelowOrEqual, Address(object, JSCell::cellStateOffset()), TrustedImm32(blackThreshold)));
    jit.emitAllocateWithNonNullAllocator(value, JITAllocator::variable(), scratch, counter, fails, CCallHelpers::SlowAllocationResult::UndefinedBehavior);
    jit.loadPtr(Address(plan, OBJECT_OFFSETOF(Plan, wordsOfExtraProperties)), scratch);
    jit.load32(Address(plan, OBJECT_OFFSETOF(Plan, wordCountOfExtraProperties)), counter);
    CCallHelpers::Label copiesWordOfExtraProperties = jit.label();
    jit.load64(CCallHelpers::BaseIndex(scratch, counter, CCallHelpers::TimesEight, -static_cast<int32_t>(sizeof(uint64_t))), kind);
    jit.store64(kind, CCallHelpers::BaseIndex(value, counter, CCallHelpers::TimesEight, -static_cast<int32_t>(sizeof(uint64_t))));
    jit.branchSub32(CCallHelpers::NonZero, TrustedImm32(1), counter).linkTo(copiesWordOfExtraProperties, &jit);
    jit.load32(Address(plan, OBJECT_OFFSETOF(Plan, moveCountOfExtraProperties)), counter);
    jit.loadPtr(Address(plan, OBJECT_OFFSETOF(Plan, firstMoveOfExtraProperties)), cursor);
    CCallHelpers::Label movesExtraProperty = jit.label();
    jit.load16(Address(cursor, OBJECT_OFFSETOF(Move, from)), scratch);
    jit.load64(CCallHelpers::BaseIndex(object, scratch, CCallHelpers::TimesOne), kind);
    jit.load16(Address(cursor, OBJECT_OFFSETOF(Move, to)), scratch);
    jit.store64(kind, CCallHelpers::BaseIndex(value, scratch, CCallHelpers::TimesOne));
    jit.addPtr(TrustedImm32(sizeof(Move)), cursor);
    jit.branchSub32(CCallHelpers::NonZero, TrustedImm32(1), counter).linkTo(movesExtraProperty, &jit);
    encodeCell32(jit, value, value);
    jit.load32(Address(plan, OBJECT_OFFSETOF(Plan, offsetOfExtraProperties)), scratch);
    jit.store32(value, CCallHelpers::BaseIndex(destination, scratch, CCallHelpers::TimesOne));
    jit.jump().linkTo(laysCellOverObject, &jit);

    isCopy.link(&jit);
    fenceAfterAllocation(jit, scratch);
    jit.addPtr(TrustedImm32(frameSize), sp);
    jit.move(destination, GPRInfo::returnValueGPR);
    jit.ret();

    isCellOfShape.link(&jit);
    mayBeUndefinedOrNull.append(jit.branchIfNotCell(value));
    jit.load32(Address(value, Typed::offsetOfShapeWord), kind);
    jit.add32(Address(cursor, OBJECT_OFFSETOF(Move, lastShape)), kind);
    storesCell.append(jit.branch32(CCallHelpers::Below, kind, Address(cursor, OBJECT_OFFSETOF(Move, shapeCount))));
    fails.append(jit.branch8(CCallHelpers::NotEqual, Address(value, JSCell::typeInfoTypeOffset()), TrustedImm32(FinalObjectType)));
    jit.load64(Address(sp, offsetOfTypeAndReason), kind);
    jit.and32(TrustedImm32(15), kind, scratch);
    Jump isOutermost = jit.branch32(CCallHelpers::NotEqual, scratch, TrustedImm32(Move::reasonOfChild));
    jit.urshift64(TrustedImm32(32), kind);
    fails.append(jit.branch32(CCallHelpers::AboveOrEqual, kind, TrustedImm32(Move::maxDepthOfChildren)));
    Jump hasDepth = jit.jump();
    isOutermost.link(&jit);
    jit.move(TrustedImm32(0), kind);
    hasDepth.link(&jit);
    jit.add32(TrustedImm32(1), kind);
    jit.lshift64(TrustedImm32(32), kind);
    jit.load32(Address(cursor, OBJECT_OFFSETOF(Move, keyOfChild)), scratch);
    fails.append(jit.branchTest32(CCallHelpers::Zero, scratch));
    jit.or64(kind, scratch);
    jit.store64(counter, Address(sp, offsetOfCounter));
    jit.store64(plan, Address(sp, offsetOfPlan));
    jit.store64(cursor, Address(sp, offsetOfCursor));
    jit.store64(destination, Address(sp, offsetOfDestination));
    jit.store64(object, Address(sp, offsetOfSource));
#if CPU(ARM64)
    jit.store64(CCallHelpers::linkRegister, Address(sp, offsetOfReturnAddress));
#endif
    jit.move(value, object);
    jit.move(scratch, typeAndReason);
    s_callsBetweenStubs->append({ jit.nearCall(), Stub::ConvertByPlan });
#if CPU(ARM64)
    jit.load64(Address(sp, offsetOfReturnAddress), CCallHelpers::linkRegister);
#endif
    jit.move(GPRInfo::returnValueGPR, kind);
    jit.load64(Address(sp, offsetOfCounter), counter);
    jit.load64(Address(sp, offsetOfPlan), plan);
    jit.load64(Address(sp, offsetOfCursor), cursor);
    jit.load64(Address(sp, offsetOfDestination), destination);
    jit.load64(Address(sp, offsetOfSource), object);
    jit.load16(Address(cursor, OBJECT_OFFSETOF(Move, from)), scratch);
    jit.load64(CCallHelpers::BaseIndex(object, scratch, CCallHelpers::TimesOne), value);
    fails.append(jit.branchPtr(CCallHelpers::NotEqual, value, kind));
    jit.load32(Address(value, Typed::offsetOfShapeWord), kind);
    jit.add32(Address(cursor, OBJECT_OFFSETOF(Move, lastShape)), kind);
    fails.append(jit.branch32(CCallHelpers::AboveOrEqual, kind, Address(cursor, OBJECT_OFFSETOF(Move, shapeCount))));
    storesCell.append(jit.jump());

    isCellOfType.link(&jit);
    mayBeUndefinedOrNull.append(jit.branchIfNotCell(value));
    jit.load8(Address(value, JSCell::typeInfoTypeOffset()), kind);
    jit.load8(Address(cursor, OBJECT_OFFSETOF(Move, cellType)), scratch);
    fails.append(jit.branch32(CCallHelpers::NotEqual, kind, scratch));
    storesCell.append(jit.jump());

    isFunction.link(&jit);
    mayBeUndefinedOrNull.append(jit.branchIfNotCell(value));
    jit.load8(Address(value, JSCell::typeInfoTypeOffset()), kind);
    storesCell.append(jit.branch32(CCallHelpers::Equal, kind, TrustedImm32(JSFunctionType)));
    jit.sub32(TrustedImm32(SlimClosureType), kind);
    static_assert(SlimClosureWithPropertiesType == SlimClosureType + 1);
    fails.append(jit.branch32(CCallHelpers::Above, kind, TrustedImm32(1)));
    storesCell.append(jit.jump());

    isObject.link(&jit);
    mayBeUndefinedOrNull.append(jit.branchIfNotCell(value));
    jit.load8(Address(value, JSCell::typeInfoTypeOffset()), kind);
    fails.append(jit.branch32(CCallHelpers::Below, kind, TrustedImm32(ObjectType)));
    storesCell.append(jit.branch32(CCallHelpers::NotEqual, kind, TrustedImm32(ObjectType)));
    fails.append(jit.branch32(CCallHelpers::GreaterThanOrEqual, Address(value, Typed::offsetOfShapeWord), TrustedImm32(0)));

    storesCell.link(&jit);
    CCallHelpers::Label storesAnyCell = jit.label();
    loadSlotOffset();
    jit.branchTest8(CCallHelpers::NonZero, Address(cursor, OBJECT_OFFSETOF(Move, flags)), TrustedImm32(Move::isWide)).linkTo(storesValue, &jit);
    encodeCell32(jit, value, value);
    CCallHelpers::Label storesWord = jit.label();
    jit.store32(value, slot);
    jit.jump().linkTo(advances, &jit);

    isInlineInt32.link(&jit);
    mayBeUndefinedOrNull.append(jit.branch64(CCallHelpers::Below, value, numberTag));
    fails.append(jit.branch32(CCallHelpers::LessThan, value, TrustedImm32(Typed::minInlineInt32)));
    loadSlotOffset();
    jit.jump().linkTo(storesWord, &jit);

    isNumber.link(&jit);
    loadSlotOffset();
    Jump isNotInt32 = jit.branch64(CCallHelpers::Below, value, numberTag);
    jit.storeDouble(number, Address(sp, offsetOfNumber));
    jit.convertInt32ToDouble(value, number);
    jit.storeDouble(number, slot);
    jit.loadDouble(Address(sp, offsetOfNumber), number);
    jit.jump().linkTo(advances, &jit);
    isNotInt32.link(&jit);
    mayBeUndefinedOrNull.append(jit.branchTest64(CCallHelpers::Zero, value, numberTag));
    jit.add64(numberTag, value);
    jit.store64(value, slot);
    jit.jump().linkTo(advances, &jit);

    isBoolean.link(&jit);
    jit.xor64(TrustedImm32(JSValue::ValueFalse), value);
    fails.append(jit.branchTest64(CCallHelpers::NonZero, value, TrustedImm32(~1)));
    CCallHelpers::Label storesByte = jit.label();
    loadSlotOffset();
    jit.store8(value, slot);
    jit.jump().linkTo(advances, &jit);

    isBooleanAsValueByte.link(&jit);
    jit.move(value, kind);
    jit.xor64(TrustedImm32(JSValue::ValueFalse), kind);
    mayBeUndefinedOrNull.append(jit.branchTest64(CCallHelpers::NonZero, kind, TrustedImm32(~1)));
    jit.jump().linkTo(storesByte, &jit);

    isLiteralString.link(&jit);
    mayBeUndefinedOrNull.append(jit.branchIfNotCell(value));
    jit.store64(counter, Address(sp, offsetOfCounter));
    jit.store64(plan, Address(sp, offsetOfPlan));
    loadTextWord(value, scratch, counter, kind, plan, fails);
    jit.load64(Address(sp, offsetOfPlan), plan);
    jit.loadPtr(Address(plan, OBJECT_OFFSETOF(Plan, firstText)), scratch);
    jit.load32(Address(cursor, OBJECT_OFFSETOF(Move, lastShape)), counter);
    jit.lshift32(TrustedImm32(4), counter);
    jit.addPtr(counter, scratch);
    jit.load32(Address(cursor, OBJECT_OFFSETOF(Move, shapeCount)), counter);
    findText(value, scratch, counter, fails);
    jit.load64(Address(sp, offsetOfCounter), counter);
    Jump holdsTheStringItself = jit.branchTest64(CCallHelpers::Zero, value);
    loadSlotOffset();
    jit.branchTest8(CCallHelpers::NonZero, Address(cursor, OBJECT_OFFSETOF(Move, flags)), TrustedImm32(Move::isWide)).linkTo(storesValue, &jit);
    jit.jump().linkTo(storesWord, &jit);
    holdsTheStringItself.link(&jit);
    jit.load16(Address(cursor, OBJECT_OFFSETOF(Move, from)), scratch);
    jit.load64(CCallHelpers::BaseIndex(object, scratch, CCallHelpers::TimesOne), value);
    jit.jump().linkTo(storesAnyCell, &jit);

    isSwitchOfSource.link(&jit);
    jit.load64(Address(sp, offsetOfObject), scratch);
    Jump readsOutOfLine = jit.branchPtr(CCallHelpers::NotEqual, object, scratch);
    jit.loadPtr(Address(object, JSObject::butterflyOffset()), object);
    jit.subPtr(TrustedImm32(Move::outOfLineBias), object);
    jit.jump().linkTo(advances, &jit);
    readsOutOfLine.link(&jit);
    jit.move(scratch, object);
    jit.jump().linkTo(advances, &jit);

    mayBeUndefinedOrNull.link(&jit);
    jit.load8(Address(cursor, OBJECT_OFFSETOF(Move, flags)), scratch);
    jit.load8(Address(cursor, OBJECT_OFFSETOF(Move, kind)), kind);
    Jump isUndefined = jit.branch64(CCallHelpers::Equal, value, TrustedImm32(JSValue::ValueUndefined));
    fails.append(jit.branch64(CCallHelpers::NotEqual, value, TrustedImm32(JSValue::ValueNull)));
    fails.append(jit.branchTest32(CCallHelpers::Zero, scratch, TrustedImm32(Move::acceptsNull)));
    Jump nullIsInt32 = isKind(Move::Kind::NumberAsInlineInt32);
    Jump nullIsDouble = isKind(Move::Kind::NumberAsDouble);
    CCallHelpers::Label storesUndefinedOrNull = jit.label();
    isKind(Move::Kind::BooleanAsValueByte).linkTo(storesByte, &jit);
    Jump isNarrow = jit.branchTest32(CCallHelpers::Zero, scratch, TrustedImm32(Move::isWide));
    loadSlotOffset();
    jit.jump().linkTo(storesValue, &jit);
    isNarrow.link(&jit);
    loadSlotOffset();
    jit.jump().linkTo(storesWord, &jit);
    isUndefined.link(&jit);
    fails.append(jit.branchTest32(CCallHelpers::Zero, scratch, TrustedImm32(Move::acceptsUndefined)));
    Jump undefinedIsInt32 = isKind(Move::Kind::NumberAsInlineInt32);
    Jump undefinedIsDouble = isKind(Move::Kind::NumberAsDouble);
    jit.jump().linkTo(storesUndefinedOrNull, &jit);
    nullIsInt32.link(&jit);
    jit.move(TrustedImm32(Typed::nullInt32), value);
    loadSlotOffset();
    jit.jump().linkTo(storesWord, &jit);
    undefinedIsInt32.link(&jit);
    jit.move(TrustedImm32(Typed::undefinedInt32), value);
    loadSlotOffset();
    jit.jump().linkTo(storesWord, &jit);
    nullIsDouble.link(&jit);
    jit.move(CCallHelpers::TrustedImm64(Typed::nullDouble), value);
    loadSlotOffset();
    jit.jump().linkTo(storesValue, &jit);
    undefinedIsDouble.link(&jit);
    jit.move(CCallHelpers::TrustedImm64(Typed::undefinedDouble), value);
    loadSlotOffset();
    jit.jump().linkTo(storesValue, &jit);

    {
        using CastEntry = Typed::UnconvertedCastEntry;
        using Check = Typed::UnconvertedCastCheck;
        using Kinds = Typed::State::CoercionPlan;
        CCallHelpers::JumpList passes;
        constexpr ptrdiff_t behind = sizeof(CacheEntry) << CacheEntry::indexBits;
        hasNoConversionPlan.link(&jit);
        misses.append(jit.branch32(CCallHelpers::NotEqual, scratch, Address(plan, behind + OBJECT_OFFSETOF(CastEntry, structureID))));
        misses.append(jit.branch32(CCallHelpers::NotEqual, typeAndReason, Address(plan, behind + OBJECT_OFFSETOF(CastEntry, typeAndReason))));
        jit.loadPtr(Address(plan, behind + OBJECT_OFFSETOF(CastEntry, checks)), cursor);
        CCallHelpers::Label checks = jit.label();
        jit.load32(Address(cursor, OBJECT_OFFSETOF(Check, kinds)), kind);
        Jump isDone = jit.branchTest32(CCallHelpers::NonZero, kind, TrustedImm32(Check::isEnd));
        jit.loadPtr(Address(cursor, OBJECT_OFFSETOF(Check, holder)), scratch);
        jit.load32(Address(cursor, OBJECT_OFFSETOF(Check, offset)), counter);
        Jump hasHolder = jit.branchTestPtr(CCallHelpers::NonZero, scratch);
        jit.move(object, scratch);
        hasHolder.link(&jit);
        Jump isValue = jit.branchTest32(CCallHelpers::Zero, kind, TrustedImm32(Check::comparesStructureID));
        jit.load32(CCallHelpers::BaseIndex(scratch, counter, CCallHelpers::TimesOne), value);
        misses.append(jit.branch64(CCallHelpers::NotEqual, value, Address(cursor, OBJECT_OFFSETOF(Check, expected))));
        passes.append(jit.jump());
        isValue.link(&jit);
        jit.load64(CCallHelpers::BaseIndex(scratch, counter, CCallHelpers::TimesOne), value);
        passes.append(jit.branch64(CCallHelpers::Equal, value, Address(cursor, OBJECT_OFFSETOF(Check, expected))));
        auto passesIfTaken = [&](uint8_t taken) {
            misses.append(jit.branchTest32(CCallHelpers::Zero, kind, TrustedImm32(taken)));
            passes.append(jit.jump());
        };
        Jump isNotCell = jit.branchIfNotCell(value);
        misses.append(jit.branchTestPtr(CCallHelpers::Zero, value));
        jit.load8(Address(value, JSCell::typeInfoTypeOffset()), counter);
        passes.append(jit.branch32(CCallHelpers::AboveOrEqual, counter, TrustedImm32(ObjectType)));
        misses.append(jit.branch32(CCallHelpers::NotEqual, counter, TrustedImm32(StringType)));
        passesIfTaken(Kinds::acceptsString);
        isNotCell.link(&jit);
        Jump isNotInt32 = jit.branchIfNotInt32(value);
        passesIfTaken(Kinds::acceptsInt32);
        isNotInt32.link(&jit);
        Jump isNotNumber = jit.branchIfNotNumber(value);
        passesIfTaken(Kinds::acceptsDouble);
        isNotNumber.link(&jit);
        for (auto [bits, taken] : { std::pair { JSValue::ValueTrue, Kinds::acceptsTrue }, std::pair { JSValue::ValueFalse, Kinds::acceptsFalse }, std::pair { JSValue::ValueUndefined, Kinds::acceptsUndefined }, std::pair { JSValue::ValueNull, Kinds::acceptsNull } }) {
            Jump isOther = jit.branch64(CCallHelpers::NotEqual, value, TrustedImm32(bits));
            passesIfTaken(taken);
            isOther.link(&jit);
        }
        misses.append(jit.jump());
        passes.link(&jit);
        jit.addPtr(TrustedImm32(sizeof(Check)), cursor);
        jit.jump().linkTo(checks, &jit);
        isDone.link(&jit);
        jit.move(object, GPRInfo::returnValueGPR);
        jit.ret();
    }

    fails.link(&jit);
    jit.loadPair64(sp, TrustedImm32(offsetOfTypeAndReason), typeAndReason, object);
    jit.addPtr(TrustedImm32(frameSize), sp);
    misses.link(&jit);
    jit.move(TrustedImm32(0), GPRInfo::returnValueGPR);
    jit.ret();
}

static void generateFrontEndTypedCoerce(CCallHelpers& jit)
{
#if CPU(ARM64)
    jit.emitFunctionPrologue();
#endif
    s_callsBetweenStubs->append({ jit.nearCall(), Stub::ConvertByPlan });
#if CPU(ARM64)
    jit.emitFunctionEpilogue();
#endif
    Jump isNotConverted = jit.branchTestPtr(CCallHelpers::Zero, GPRInfo::returnValueGPR);
    jit.move(TrustedImm32(0), GPRInfo::returnValueGPR2);
    jit.ret();
    isNotConverted.link(&jit);
    jit.move(instanceGPR, A0);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfRuntimeTable()), T9);
    jit.loadPtr(Address(T9, offsetInTable(Entry::RawTypedCoerce)), T9);
    jit.farJump(T9, OperationPtrTag);
}

static bool returnFromCastIfConversionIsPlanned(CCallHelpers& jit, Stub stub, bool isGivenTypeAlone = false)
{
    auto addReason = [&] {
        if (!isGivenTypeAlone)
            return;
        jit.lshift32(TrustedImm32(4), A2);
        jit.or32(TrustedImm32(static_cast<int32_t>(Typed::Format::CastReason::Claim)), A2);
    };
    bool isLeaf = stub == Stub::LeafColdOperationValue || stub == Stub::LeafColdOperationValueWithoutFPRs;
    if ((!isLeaf && stub != Stub::ColdOperationValue && stub != Stub::ColdOperationValueWithoutFPRs) || (isLeaf && !isARM64()))
        return false;
    static_assert(operationArgumentGPR(1) == A1 && operationArgumentGPR(2) == A2);
    CCallHelpers::JumpList isNotAsked;
    if (isGivenTypeAlone)
        isNotAsked.append(jit.branchTest64(CCallHelpers::Zero, A1));
#if CPU(ARM64)
    jit.pushPair(GPRInfo::callFrameRegister, CCallHelpers::linkRegister);
    jit.pushPair(A2, A3);
    jit.pushPair(A4, T9);
    jit.pushPair(T10, T11);
    jit.pushPair(T12, T13);
    addReason();
    s_callsBetweenStubs->append({ jit.nearCall(), Stub::ConvertByPlan });
    jit.popPair(T12, T13);
    jit.popPair(T10, T11);
    jit.popPair(A4, T9);
    jit.popPair(A2, A3);
    jit.popPair(GPRInfo::callFrameRegister, CCallHelpers::linkRegister);
#else
    constexpr GPRReg saved[] = { A0, A2, A3, A4, T9, T11 };
    for (GPRReg reg : saved)
        jit.push(reg);
    addReason();
    s_callsBetweenStubs->append({ jit.nearCall(), Stub::ConvertByPlan });
    for (unsigned i = std::size(saved); i--;)
        jit.pop(saved[i]);
#endif
    Jump isNotConverted = jit.branchTestPtr(CCallHelpers::Zero, GPRInfo::returnValueGPR);
    returnToTypedCaller(jit, isLeaf);
    isNotConverted.link(&jit);
    isNotAsked.link(&jit);
    return true;
}

static void generateFrontEndTypedGetExtra(CCallHelpers& jit)
{
    using Place = Typed::ExtraPropertyLocation;
    constexpr GPRReg cell = A1;
    constexpr GPRReg name = A2;
    constexpr GPRReg shapeWord = A3;
    constexpr GPRReg entry = T9;
    constexpr GPRReg extraProperties = T10;
    constexpr GPRReg scratch = T11;
    static_assert(noOverlap(cell, name, shapeWord, entry, extraProperties, scratch, instanceGPR));
    static_assert(sizeof(Place) == 16);
    auto returnValue = [&] {
        jit.move(TrustedImm32(0), GPRInfo::returnValueGPR2);
        jit.ret();
    };
    CCallHelpers::JumpList isNotKnown;
    loadExtraPropertiesOf(jit, cell, extraProperties, scratch, isNotKnown);
    jit.load32(Address(extraProperties, JSCell::structureIDOffset()), scratch);
    jit.load32(Address(cell, Typed::offsetOfShapeWord), shapeWord);
    jit.xor32(name, scratch, entry);
    jit.xor32(shapeWord, entry);
    jit.mul32(TrustedImm32(static_cast<int32_t>(Place::multiplier)), entry, entry);
    jit.urshift32(TrustedImm32(32 - Place::indexBits), entry);
    jit.lshift32(TrustedImm32(4), entry);
    jit.addPtr(Address(instanceGPR, Instance::offsetOfTypedExtraPropertyLocations()), entry);
    isNotKnown.append(jit.branch32(CCallHelpers::NotEqual, scratch, Address(entry, OBJECT_OFFSETOF(Place, structureID))));
    isNotKnown.append(jit.branch32(CCallHelpers::NotEqual, name, Address(entry, OBJECT_OFFSETOF(Place, name))));
    isNotKnown.append(jit.branch32(CCallHelpers::NotEqual, shapeWord, Address(entry, OBJECT_OFFSETOF(Place, shapeWord))));
    jit.load32(Address(entry, OBJECT_OFFSETOF(Place, displacement)), scratch);
    jit.signExtend32ToPtr(scratch, scratch);
    Jump isAbsent = jit.branchTest32(CCallHelpers::Zero, scratch);
    Jump isOutOfLine = jit.branch32(CCallHelpers::LessThan, scratch, TrustedImm32(0));
    jit.load64(CCallHelpers::BaseIndex(extraProperties, scratch, CCallHelpers::TimesOne), GPRInfo::returnValueGPR);
    returnValue();

    isOutOfLine.link(&jit);
    jit.loadPtr(Address(extraProperties, JSObject::butterflyOffset()), extraProperties);
    jit.load64(CCallHelpers::BaseIndex(extraProperties, scratch, CCallHelpers::TimesOne), GPRInfo::returnValueGPR);
    returnValue();

    isAbsent.link(&jit);
    jit.move(CCallHelpers::TrustedImm64(JSValue::ValueUndefined), GPRInfo::returnValueGPR);
    returnValue();

    isNotKnown.link(&jit);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfRuntimeTable()), T9);
    jit.loadPtr(Address(T9, offsetInTable(Entry::RawTypedGetExtra)), T9);
    jit.farJump(T9, OperationPtrTag);
}

static void generateFrontEndTypedGetByNameChecked(CCallHelpers& jit, Entry raw, bool returnsDouble)
{
    using Answer = Instance::InheritedFieldAnswer;
    using Kinds = Typed::State::CoercionPlan;
    constexpr GPRReg cell = A1;
    constexpr GPRReg name = A2;
    constexpr GPRReg type = A3;
    constexpr GPRReg answer = T9;
    constexpr GPRReg extraProperties = T10;
    constexpr GPRReg scratch = T11;
#if CPU(X86_64)
    constexpr GPRReg value = GPRInfo::returnValueGPR;
#else
    constexpr GPRReg value = T12;
#endif
    static_assert(noOverlap(A0, cell, name, type, answer, extraProperties, scratch, value, instanceGPR));
    auto inAnswer = [&](ptrdiff_t offset) { return Address(answer, Instance::offsetOfInheritedFieldAnswers() + offset); };
    CCallHelpers::JumpList isNotKnown;
    CCallHelpers::JumpList isKnown;
    jit.load32(Address(cell, JSCell::structureIDOffset()), scratch);
    jit.urshift32(scratch, TrustedImm32(4), answer);
    jit.xor32(name, answer);
    jit.xor32(type, answer);
    static_assert(Instance::inheritedFieldAnswerWays * sizeof(Answer) == 64 && Instance::asksForExtraProperty >= Instance::numberOfInheritedFieldAnswers);
    jit.and32(TrustedImm32(Instance::numberOfInheritedFieldAnswers / Instance::inheritedFieldAnswerWays - 1), answer);
    jit.lshift32(TrustedImm32(6), answer);
    jit.addPtr(instanceGPR, answer);
    jit.or32(TrustedImm32(static_cast<int32_t>(Instance::asksForExtraProperty)), type, value);
    for (unsigned way = 0; way < Instance::inheritedFieldAnswerWays; ++way) {
        CCallHelpers::JumpList differs;
        differs.append(jit.branch32(CCallHelpers::NotEqual, inAnswer(OBJECT_OFFSETOF(Answer, structureID)), scratch));
        differs.append(jit.branch32(CCallHelpers::NotEqual, inAnswer(OBJECT_OFFSETOF(Answer, name)), name));
        differs.append(jit.branch32(CCallHelpers::NotEqual, inAnswer(OBJECT_OFFSETOF(Answer, question)), value));
        if (way + 1 == Instance::inheritedFieldAnswerWays) {
            isNotKnown.append(differs);
            break;
        }
        isKnown.append(jit.jump());
        differs.link(&jit);
        jit.addPtr(TrustedImm32(sizeof(Answer)), answer);
    }
    isKnown.link(&jit);
    loadExtraPropertiesOf(jit, cell, extraProperties, scratch, isNotKnown);
    jit.load32(Address(extraProperties, JSCell::structureIDOffset()), scratch);
    isNotKnown.append(jit.branch32(CCallHelpers::NotEqual, inAnswer(OBJECT_OFFSETOF(Answer, holder)), scratch));
    jit.load32SignedExtendTo64(inAnswer(OBJECT_OFFSETOF(Answer, offset)), scratch);
    jit.move(TrustedImm32(JSValue::ValueUndefined), value);
    Jump isAbsent = jit.branchTest64(CCallHelpers::Zero, scratch);
    Jump isInline = jit.branch64(CCallHelpers::GreaterThanOrEqual, scratch, TrustedImm32(0));
    jit.loadPtr(Address(extraProperties, JSObject::butterflyOffset()), extraProperties);
    isInline.link(&jit);
    jit.load64(CCallHelpers::BaseIndex(extraProperties, scratch, CCallHelpers::TimesOne), value);
    isAbsent.link(&jit);
    auto returnValue = [&] {
        jit.move(value, GPRInfo::returnValueGPR);
        jit.move(TrustedImm32(0), GPRInfo::returnValueGPR2);
        jit.ret();
    };
    auto returnBits = [&](uint64_t bits) {
        jit.move(CCallHelpers::TrustedImm64(static_cast<int64_t>(bits)), scratch);
        jit.move64ToDouble(scratch, FPRInfo::returnValueFPR);
        jit.ret();
    };
    auto requireKind = [&](uint8_t kind) {
        isNotKnown.append(jit.branchTest32(CCallHelpers::Zero, inAnswer(OBJECT_OFFSETOF(Answer, onlyValueChecked)), TrustedImm32(kind)));
    };
    Jump isNotCell = jit.branchIfNotCell(value);
    if (returnsDouble)
        isNotKnown.append(jit.jump());
    else {
        jit.load32(Address(value, JSCell::structureIDOffset()), scratch);
        isNotKnown.append(jit.branch32(CCallHelpers::NotEqual, inAnswer(OBJECT_OFFSETOF(Answer, onlyValueChecked) + sizeof(uint32_t)), scratch));
        returnValue();
    }
    isNotCell.link(&jit);
    Jump isNotInt32 = jit.branchIfNotInt32(value);
    requireKind(Kinds::acceptsInt32);
    if (returnsDouble) {
        jit.convertInt32ToDouble(value, FPRInfo::returnValueFPR);
        jit.ret();
    } else
        returnValue();
    isNotInt32.link(&jit);
    Jump isNotNumber = jit.branchIfNotNumber(value);
    requireKind(Kinds::acceptsDouble);
    if (returnsDouble) {
        jit.sub64(GPRInfo::numberTagRegister, value);
        jit.move64ToDouble(value, FPRInfo::returnValueFPR);
        jit.ret();
    } else
        returnValue();
    isNotNumber.link(&jit);
    Jump isNotUndefined = jit.branch64(CCallHelpers::NotEqual, value, TrustedImm32(JSValue::ValueUndefined));
    requireKind(Kinds::acceptsUndefined);
    if (returnsDouble)
        returnBits(Typed::undefinedDouble);
    else
        returnValue();
    isNotUndefined.link(&jit);
    Jump isNotNull = jit.branch64(CCallHelpers::NotEqual, value, TrustedImm32(JSValue::ValueNull));
    requireKind(Kinds::acceptsNull);
    if (returnsDouble)
        returnBits(Typed::nullDouble);
    else
        returnValue();
    isNotNull.link(&jit);
    if (!returnsDouble) {
        Jump isNotTrue = jit.branch64(CCallHelpers::NotEqual, value, TrustedImm32(JSValue::ValueTrue));
        requireKind(Kinds::acceptsTrue);
        returnValue();
        isNotTrue.link(&jit);
        isNotKnown.append(jit.branch64(CCallHelpers::NotEqual, value, TrustedImm32(JSValue::ValueFalse)));
        requireKind(Kinds::acceptsFalse);
        returnValue();
    }

    isNotKnown.link(&jit);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfRuntimeTable()), T9);
    jit.loadPtr(Address(T9, offsetInTable(raw)), T9);
    jit.farJump(T9, OperationPtrTag);
}

static void generateFrontEndTypedGetByNameChecked(CCallHelpers& jit) { generateFrontEndTypedGetByNameChecked(jit, Entry::RawTypedGetByNameChecked, false); }
static void generateFrontEndTypedGetByNameCheckedAsNumber(CCallHelpers& jit) { generateFrontEndTypedGetByNameChecked(jit, Entry::RawTypedGetByNameCheckedAsNumber, true); }

static CCallHelpers::Label storeThroughSlot(CCallHelpers& jit, CCallHelpers::JumpList& miss, CCallHelpers::JumpList& isNotField)
{
    jit.load64(slotWord(A2, 0), T11);
    miss.append(branchIfStructureDiffers(jit, R0, T11));
    jit.load64(slotWord(A2, 1), T13);
    Jump isOutOfLine;
    {
        Jump hasPointerWord = jit.branchTest64(CCallHelpers::NonZero, T13);
        isOutOfLine = jit.branchTest64(CCallHelpers::NonZero, T11, CCallHelpers::TrustedImm64(1ll << (32 + Slot::offsetBits - 1)));
        extractBits(jit, T11, 32, Slot::offsetBits, T12);
        jit.store64(A1, CCallHelpers::BaseIndex(R0, T12, CCallHelpers::TimesEight));
        returnAfterStoring(jit, A1);
        hasPointerWord.link(&jit);
    }
#if CPU(X86_64)
    Jump slotHasFieldType = jit.branchTest32(CCallHelpers::NonZero, slotWord(A2, 1).withOffset(sizeof(uint32_t)));
#else
    jit.urshift64(T13, TrustedImm32(32), T14);
    Jump slotHasFieldType = jit.branchTest32(CCallHelpers::NonZero, T14);
#endif
    locateCachedProperty(jit, R0, T11, T12);
    jit.store64(A1, CCallHelpers::BaseIndex(T12, T11, CCallHelpers::TimesEight));
    jit.store32(T13, Address(R0, JSCell::structureIDOffset()));
    Jump addsProperty = jit.jump();
    isOutOfLine.link(&jit);
    CCallHelpers::Label isHeld = jit.label();
    locateCachedProperty(jit, R0, T11, T12);
    jit.store64(A1, CCallHelpers::BaseIndex(T12, T11, CCallHelpers::TimesEight));
    Jump sameStructure = jit.branchTest32(CCallHelpers::Zero, T13);
    jit.store32(T13, Address(R0, JSCell::structureIDOffset()));
    Jump hasDifferentStructure = jit.jump();
    sameStructure.link(&jit);

    CCallHelpers::Label stored = jit.label();
    CCallHelpers::Label storedWithPossiblyDifferentStructure = returnAfterStoring(jit, A1);
    hasDifferentStructure.linkTo(storedWithPossiblyDifferentStructure, &jit);
    addsProperty.linkTo(storedWithPossiblyDifferentStructure, &jit);

    {
        slotHasFieldType.link(&jit);
#if CPU(X86_64)
        jit.load32(slotWord(A2, 1).withOffset(sizeof(uint32_t)), T14);
#endif
        {
            Jump notCompiledField = branchUnlessSlotHas<Slot::pointerIsNotCell>(jit, T11);
            static_assert(!(Slot::FieldWrite::isFieldWrite & Slot::isStoreTransition >> 32));
            Jump isTransition = jit.branchTest32(CCallHelpers::NonZero, T14, TrustedImm32(static_cast<int32_t>(Slot::isStoreTransition >> 32)));
            CCallHelpers::Label hasFieldWrite = jit.label();
            jit.and32(TrustedImm32(Slot::FieldWrite::isFieldWrite | Slot::FieldWrite::isNotField), T14, T12);
            Jump notLayoutField = jit.branch32(CCallHelpers::Equal, T12, TrustedImm32(Slot::FieldWrite::isFieldWrite | Slot::FieldWrite::isNotField));
            CCallHelpers::Label storesToField = jit.label();
            CCallHelpers::Label hasFieldAddress;
            storeCompiledField(jit, miss, nullptr, &hasFieldAddress);
            isTransition.link(&jit);
            CCallHelpers::JumpList hasOtherKeys;
            storeByTransition(jit, miss, true, &hasOtherKeys, true);
            hasOtherKeys.link(&jit);
            jit.load64(Address(T10, OBJECT_OFFSETOF(Typed::StoreTransition, fieldWrite)), T13);
            jit.load32(Address(T10, OBJECT_OFFSETOF(Typed::StoreTransition, fieldWrite) + sizeof(uint32_t)), T14);
            jit.load32(Address(T10, OBJECT_OFFSETOF(Typed::StoreTransition, structureIDIfFieldIsInline)), T11);
            jit.branch32(CCallHelpers::Equal, T11, Address(R0, JSCell::structureIDOffset())).linkTo(storesToField, &jit);
            jit.load32(Address(T10, OBJECT_OFFSETOF(Typed::StoreTransition, structureID)), T11);
            miss.append(jit.branch32(CCallHelpers::NotEqual, T11, Address(R0, JSCell::structureIDOffset())));
            jit.jump().linkTo(hasFieldWrite, &jit);
            notLayoutField.link(&jit);
            Jump isNotInExtension = jit.branchTest32(CCallHelpers::Zero, T14, TrustedImm32(static_cast<int32_t>(~Slot::FieldWrite::hasNoFieldInfo)));
            jit.load32(Address(R0, Typed::offsetOfOrderWord), T11);
            miss.append(jit.branchTest32(CCallHelpers::NonZero, T11, TrustedImm32(Typed::orderWordIsFrozen)));
            jit.load32(Address(R0, Typed::offsetOfExtension), T12);
            miss.append(jit.branchTest32(CCallHelpers::Zero, T12));
            decodeCell32(jit, T12, T12);
            jit.zeroExtend16To32(T13, T11);
            miss.append(jit.branch32(CCallHelpers::BelowOrEqual, Address(T12, Typed::offsetOfExtensionSize), T11));
            jit.addPtr(T11, T12);
            jit.jump().linkTo(hasFieldAddress, &jit);
            isNotInExtension.link(&jit);
            isNotField.append(jit.branchTest32(CCallHelpers::Zero, T14, TrustedImm32(Slot::FieldWrite::isInGlobalProxyTarget)));
            jit.loadPtr(Address(R0, JSGlobalProxy::targetOffset()), R0);
            locateCachedProperty(jit, R0, T11, T12);
            jit.store64(A1, CCallHelpers::BaseIndex(T12, T11, CCallHelpers::TimesEight));
            jit.jump().linkTo(stored, &jit);
            notCompiledField.link(&jit);
        }
        auto ifAccepts = [&](unsigned kind) {
            miss.append(jit.branchTest32(CCallHelpers::Zero, T14, TrustedImm32(kind)));
            jit.jump().linkTo(isHeld, &jit);
        };
        Jump isCell = jit.branchIfCell(A1);
        Jump isNotNumber = jit.branchIfNotNumber(A1);
        miss.append(jit.branchTest32(CCallHelpers::Zero, T14, TrustedImm32(SoundTypeNumber)));
        jit.branchIfNotInt32(A1).linkTo(isHeld, &jit);
        jit.convertInt32ToDouble(A1, FPRInfo::fpRegT0);
        jit.moveDoubleTo64(FPRInfo::fpRegT0, A1);
        jit.sub64(numberTag, A1);
        jit.jump().linkTo(isHeld, &jit);

        isNotNumber.link(&jit);
        Jump isNotUndefined = jit.branch64(CCallHelpers::NotEqual, A1, CCallHelpers::TrustedImm64(JSValue::ValueUndefined));
        ifAccepts(SoundTypeUndefined);
        isNotUndefined.link(&jit);
        Jump isNotNull = jit.branch64(CCallHelpers::NotEqual, A1, CCallHelpers::TrustedImm64(JSValue::ValueNull));
        ifAccepts(SoundTypeNull);
        isNotNull.link(&jit);
        jit.and64(TrustedImm32(~1), A1, T12);
        miss.append(jit.branch64(CCallHelpers::NotEqual, T12, CCallHelpers::TrustedImm64(JSValue::ValueFalse)));
        ifAccepts(SoundTypeBoolean);

        isCell.link(&jit);
        jit.load8(Address(A1, JSCell::typeInfoTypeOffset()), T12);
        Jump isNotString = jit.branch32(CCallHelpers::NotEqual, T12, TrustedImm32(StringType));
        ifAccepts(SoundTypeString);
        isNotString.link(&jit);
        Jump isNotArray = jit.branch32(CCallHelpers::NotEqual, T12, TrustedImm32(ArrayType));
        ifAccepts(SoundTypeArray);
        isNotArray.link(&jit);
        Jump isNotFunction = jit.branch32(CCallHelpers::NotEqual, T12, TrustedImm32(JSFunctionType));
        ifAccepts(SoundTypeFunction);
        isNotFunction.link(&jit);
        Jump isFinalObject = jit.branch32(CCallHelpers::Equal, T12, TrustedImm32(FinalObjectType));
        miss.append(jit.branch32(CCallHelpers::Below, T12, TrustedImm32(ObjectType)));
        miss.append(jit.branch32(CCallHelpers::Equal, T12, TrustedImm32(InternalFunctionType)));
        miss.append(jit.branch32(CCallHelpers::Equal, T12, TrustedImm32(DerivedArrayType)));
        jit.load8(Address(A1, JSCell::typeInfoFlagsOffset()), T10);
        Jump mayBeSlimClosure = jit.branchTest32(CCallHelpers::NonZero, T10, TrustedImm32(OverridesGetCallData));
        jit.urshift32(T14, TrustedImm32(16), T10);
        Jump dispatchesOnKind = jit.branchTest32(CCallHelpers::Zero, T10);
        miss.append(jit.branchTest32(CCallHelpers::NonZero, T14, TrustedImm32(SoundTypeOtherObject)));
        jit.or32(TrustedImm32(static_cast<int32_t>(0xffff0000)), T10);
        jit.load32(Address(A1, Typed::offsetOfShapeWord), T12);
        jit.branch32(CCallHelpers::Equal, T10, T12).linkTo(isHeld, &jit);
        miss.append(jit.jump());
        dispatchesOnKind.link(&jit);
        ifAccepts(SoundTypeOtherObject);
        mayBeSlimClosure.link(&jit);
        miss.append(jit.branch32(CCallHelpers::Below, T12, TrustedImm32(SlimClosureType)));
        miss.append(jit.branch32(CCallHelpers::Above, T12, TrustedImm32(SlimClosureWithPropertiesType)));
        ifAccepts(SoundTypeFunction);
        isFinalObject.link(&jit);
        miss.append(jit.branchTest32(CCallHelpers::Zero, T14, TrustedImm32(SoundTypeOtherObject)));
        jit.urshift32(T14, TrustedImm32(16), T12);
        jit.branchTest32(CCallHelpers::Zero, T12).linkTo(isHeld, &jit);
        miss.append(jit.jump());
    }
    return storedWithPossiblyDifferentStructure;
}

static void callNativeSetterIfCached(CCallHelpers& jit, GPRReg name)
{
    using Known = Instance::InheritedSetter;
    constexpr GPRReg uid = T10;
    constexpr GPRReg place = T12;
    constexpr GPRReg known = T13;
    static_assert(noOverlap(R0, A1, A2, uid, T11, known) && noOverlap(R0, A1, A2, uid, T11, place) && noOverlap(A0, A1, A2, A3, uid, T11, known) && sizeof(Known) == 32);
    RELEASE_ASSERT(noOverlap(name, R0, A1, uid, T11, place, known));
    auto inRecord = [&](ptrdiff_t offset) { return Address(known, static_cast<int32_t>(offset)); };
    CCallHelpers::JumpList isNotCached;
    isNotCached.append(jit.branchTest32(CCallHelpers::Zero, Address(instanceGPR, Instance::offsetOfHasCachedNativeSetter())));
    isNotCached.append(jit.branchIfNotCell(R0));
    jit.move(name, T11);
    Jump notHotName = jit.branch32(CCallHelpers::AboveOrEqual, T11, TrustedImm32(PropertyLookupTable::numberOfHotNames));
    jit.mul32(TrustedImm32(PropertyLookupTable::hotNameInverseMultiplier), T11, T11);
    jit.and32(TrustedImm32(PropertyLookupTable::numberOfHotNames - 1), T11);
    notHotName.link(&jit);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfProgramIdentifierPositions()), place);
    jit.load16(CCallHelpers::BaseIndex(place, T11, CCallHelpers::TimesTwo), T11);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfProgramIdentifiers()), place);
    jit.loadPtr(CCallHelpers::BaseIndex(place, T11, CCallHelpers::TimesEight), uid);
    isNotCached.append(jit.branchTestPtr(CCallHelpers::Zero, uid));
    jit.load32(Address(R0, JSCell::structureIDOffset()), T11);
    jit.urshift32(T11, TrustedImm32(4), place);
    jit.urshift64(uid, TrustedImm32(4), known);
    jit.xor32(known, place);
    jit.and32(Address(instanceGPR, Instance::offsetOfInheritedSettersMask()), place);
    jit.lshift32(TrustedImm32(5), place);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfInheritedSetters()), known);
    jit.addPtr(place, known);
    Jump structureDiffers = jit.branch32(CCallHelpers::NotEqual, T11, inRecord(OBJECT_OFFSETOF(Known, structureID)));
    Jump matchesFirst = jit.branchPtr(CCallHelpers::Equal, uid, inRecord(OBJECT_OFFSETOF(Known, uid)));
    structureDiffers.link(&jit);
    jit.xor32(TrustedImm32(sizeof(Known)), place);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfInheritedSetters()), known);
    jit.addPtr(place, known);
    isNotCached.append(jit.branch32(CCallHelpers::NotEqual, T11, inRecord(OBJECT_OFFSETOF(Known, structureID))));
    isNotCached.append(jit.branchPtr(CCallHelpers::NotEqual, uid, inRecord(OBJECT_OFFSETOF(Known, uid))));
    matchesFirst.link(&jit);
    jit.load32(Address(instanceGPR, Instance::offsetOfMegamorphicCacheEpoch()), T11);
    jit.load16(inRecord(OBJECT_OFFSETOF(Known, epoch)), place);
    isNotCached.append(jit.branch32(CCallHelpers::NotEqual, T11, place));
    jit.loadPtr(inRecord(OBJECT_OFFSETOF(Known, nativeSetter)), T11);
    isNotCached.append(jit.branchTestPtr(CCallHelpers::Zero, T11));

#if CPU(ARM64)
    jit.pushToSave(CCallHelpers::linkRegister);
#else
    jit.subPtr(TrustedImm32(sizeof(CPURegister)), CCallHelpers::stackPointerRegister);
#endif
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfVM()), place);
    jit.storePtr(GPRInfo::callFrameRegister, Address(place, VM::offsetOfTopCallFrame()));
    jit.move(A1, A2);
    jit.move(R0, A1);
    jit.move(uid, A3);
    jit.loadPtr(inRecord(OBJECT_OFFSETOF(Known, holder)), A0);
    jit.load32(Address(A0, JSCell::structureIDOffset()), A0);
    structureWithID(jit, A0);
    jit.loadPtr(Address(A0, Structure::realmOffset()), A0);
    jit.call(T11, CustomAccessorPtrTag);
#if CPU(ARM64)
    jit.popToRestore(CCallHelpers::linkRegister);
#else
    jit.addPtr(TrustedImm32(sizeof(CPURegister)), CCallHelpers::stackPointerRegister);
#endif
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfVM()), T11);
    Jump exception = jit.branchTestPtr(CCallHelpers::NonZero, Address(T11, VM::exceptionOffset()));
    jit.ret();
    exception.link(&jit);
    jit.emitFunctionEpilogue();
    loadInstance(jit, T9);
    jumpToEntry(jit, T9, Entry::HandleException);
    isNotCached.link(&jit);
}

static void callPutByNameOperation(CCallHelpers& jit, GPRReg name, uint32_t flagBits)
{
    constexpr bool callerIsThunk = true;
    if (!(flagBits & 1))
        callNativeSetterIfCached(jit, name);
    jit.move(name, A3);
    jit.move(A1, A2);
    jit.move(R0, A1);
    jit.move(instanceGPR, A0);
    jit.move(TrustedImm32(flagBits), A4);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfRuntimeTable()), T11);
    jit.loadPtr(Address(T11, offsetInTable(Entry::operationAOTPutByNameAndCache)), T11);
    callAndCheckException(jit, T11, Returns::Void, GPRInfo::returnValueGPR, callerIsThunk);
}

enum class PutsByName : uint8_t { Strictly, Sloppily, ByDefinition };
static constexpr uint32_t flagBitsOf(PutsByName how) { return how == PutsByName::Strictly ? 2 : how == PutsByName::Sloppily ? 0 : 3; }
static constexpr unsigned variantOf(PutsByName how, Preserves preserves) { return static_cast<unsigned>(how) * 2 + static_cast<unsigned>(preserves); }

static void generatePutByNameGeneric(CCallHelpers& jit) { callPutByNameOperation(jit, A2, flagBitsOf(PutsByName::Strictly)); }
static void generatePutByNameSloppyGeneric(CCallHelpers& jit) { callPutByNameOperation(jit, A2, flagBitsOf(PutsByName::Sloppily)); }
static void generateDefineByNameGeneric(CCallHelpers& jit) { callPutByNameOperation(jit, A2, flagBitsOf(PutsByName::ByDefinition)); }

static void generatePutThroughSlotByNameWith(CCallHelpers& jit, PutsByName how)
{
    CCallHelpers::JumpList miss;
    storeThroughSlot(jit, miss, miss);
    miss.link(&jit);
    callPutByNameOperation(jit, T9, flagBitsOf(how));
}
static void generatePutThroughSlotByName(CCallHelpers& jit) { generatePutThroughSlotByNameWith(jit, PutsByName::Strictly); }
static void generatePutThroughSlotByNameSloppy(CCallHelpers& jit) { generatePutThroughSlotByNameWith(jit, PutsByName::Sloppily); }
static void generateDefineThroughSlotByName(CCallHelpers& jit) { generatePutThroughSlotByNameWith(jit, PutsByName::ByDefinition); }

static void generatePutThroughAccessorByNameWith(CCallHelpers& jit, Stub genericPath)
{
    constexpr GPRReg entry = T13;
    static_assert(noOverlap(R0, A1, T11, T12, entry));
    CCallHelpers::JumpList cannot;
    CCallHelpers::JumpList isLoaded;
    jit.load32(Address(entry, PropertyLookupTable::offsetOfPayloads), T12);
    Jump isOwn = jit.branch32(CCallHelpers::Below, T12, TrustedImm32(PropertyLookupTable::minHolderWord));
    jit.load8(Address(entry, PropertyLookupTable::offsetOfCodeInEntry), T11);
    decodeCell32(jit, T12, T12);
    Jump isOutOfLine = jit.branch32(CCallHelpers::AboveOrEqual, T11, TrustedImm32(PropertyLookupTable::firstCodeOutOfLine));
    jit.load64(CCallHelpers::BaseIndex(T12, T11, CCallHelpers::TimesEight), T12);
    isLoaded.append(jit.jump());
    isOutOfLine.link(&jit);
    jit.load64(outOfLineSlot(jit, T12, T11, T12, PropertyLookupTable::firstCodeOutOfLine), T12);
    isLoaded.append(jit.jump());
    isOwn.link(&jit);
    jit.move(T12, T11);
    loadOwnAccessor(jit, R0, T11, T12);
    isLoaded.link(&jit);
    jit.loadPtr(Address(T12, GetterSetter::offsetOfSetter()), T12);
    cannot.append(jit.branchTest8(CCallHelpers::Zero, Address(T12, JSCell::typeInfoFlagsOffset()), TrustedImm32(TypeOfReturnsFunction)));
    cannot.append(jit.branchIfType(T12, NullSetterFunctionType));
    checkStackBeforeCallingAccessor(jit);
    jit.move(T12, calleeGPR);
    jit.move(R0, thisGPR);
    jit.move(A1, argumentGPR(0));
    jit.move(TrustedImm32(1), countGPR);
    jit.jump().linkTo(variadicCallCellLabel(), &jit);

    cannot.link(&jit);
    loadEntryName(jit, entry, A2);
    jit.jump().linkTo(stubLabels()[static_cast<unsigned>(genericPath)], &jit);
}
static void generatePutThroughAccessorByName(CCallHelpers& jit) { generatePutThroughAccessorByNameWith(jit, Stub::PutByNameGeneric); }
static void generatePutThroughAccessorByNameSloppy(CCallHelpers& jit) { generatePutThroughAccessorByNameWith(jit, Stub::PutByNameSloppyGeneric); }

static void generatePutByNameWithNewStorage(CCallHelpers& jit, Stub fallbackStub)
{
    constexpr size_t sizeOfFirstStorage = initialOutOfLineCapacity * sizeof(EncodedJSValue);
    constexpr GPRReg structureIDAfter = T10;
    constexpr GPRReg code = T11;
    constexpr GPRReg count = T12;
    constexpr GPRReg oldStorage = T13;
    constexpr GPRReg allocator = A3;
    constexpr GPRReg storage = T9;
    static_assert(noOverlap(R0, A1, A2, A3, T9, T10, T11, T12, T13));
    CCallHelpers::JumpList cannot;
    auto setStorageAndStructure = [&](GPRReg butterfly) {
        jit.and32(TrustedImm32(~PropertyLookupTable::newStructureFlags), structureIDAfter);
        jit.or32(TrustedImm32(StructureID::nukedStructureIDBit), Address(R0, JSCell::structureIDOffset()));
        jit.storeFence();
        jit.storePtr(butterfly, Address(R0, JSObject::butterflyOffset()));
        jit.storeFence();
        jit.store32(structureIDAfter, Address(R0, JSCell::structureIDOffset()));
        jit.jump().linkTo(stubLabels()[static_cast<unsigned>(Stub::WriteBarrier)], &jit);
    };
    jit.loadPtr(Address(R0, JSObject::butterflyOffset()), oldStorage);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfAuxiliarySpace()), allocator);
    Jump grows = jit.branchTest32(CCallHelpers::NonZero, structureIDAfter, TrustedImm32(PropertyLookupTable::growsStorage));

    cannot.append(jit.branchTestPtr(CCallHelpers::NonZero, oldStorage));
    Jump notFunction = jit.branch8(CCallHelpers::NotEqual, Address(R0, JSCell::typeInfoTypeOffset()), TrustedImm32(JSFunctionType));
    constexpr unsigned plainFunctionExecutable = Typed::FunctionTables::executableKind(static_cast<uint8_t>(Typed::Format::FunctionKind::Plain), false);
    constexpr unsigned arrowFunctionExecutable = Typed::FunctionTables::executableKind(static_cast<uint8_t>(Typed::Format::FunctionKind::Arrow), false);
    jit.loadPtr(Address(R0, JSFunction::offsetOfExecutableOrRareData()), count);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfTypedExecutable(plainFunctionExecutable)), storage);
    Jump isPlainFunction = jit.branchPtr(CCallHelpers::Equal, count, storage);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfTypedExecutable(arrowFunctionExecutable)), storage);
    Jump isArrowFunction = jit.branchPtr(CCallHelpers::Equal, count, storage);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfBoundFunctionExecutable()), storage);
    cannot.append(jit.branchPtr(CCallHelpers::NotEqual, count, storage));
    isArrowFunction.link(&jit);
    isPlainFunction.link(&jit);
    notFunction.link(&jit);
    jit.loadPtr(Address(allocator, CompleteSubspace::offsetOfAllocatorForSizeStep() + MarkedSpace::sizeClassToIndex(sizeOfFirstStorage) * sizeof(Allocator)), allocator);
    cannot.append(jit.branchTestPtr(CCallHelpers::Zero, allocator));
    jit.emitAllocateWithNonNullAllocator(storage, JITAllocator::variable(), allocator, count, cannot, CCallHelpers::SlowAllocationResult::UndefinedBehavior);
    for (unsigned i = 0; i + 1 < initialOutOfLineCapacity; ++i)
        jit.store64(TrustedImm32(0), Address(storage, i * sizeof(EncodedJSValue)));
    jit.store64(A1, Address(storage, sizeOfFirstStorage - sizeof(EncodedJSValue)));
    jit.addPtr(TrustedImm32(sizeOfFirstStorage + sizeof(IndexingHeader)), storage);
    setStorageAndStructure(storage);

    grows.link(&jit);
    static_assert(MarkedSpace::sizeStep == 2 * sizeof(EncodedJSValue));
    cannot.append(jit.branchTestPtr(CCallHelpers::Zero, oldStorage));
    jit.loadPtr(CCallHelpers::BaseIndex(allocator, code, CCallHelpers::TimesEight, CompleteSubspace::offsetOfAllocatorForSizeStep()), allocator);
    cannot.append(jit.branchTestPtr(CCallHelpers::Zero, allocator));
    jit.emitAllocateWithNonNullAllocator(storage, JITAllocator::variable(), allocator, count, cannot, CCallHelpers::SlowAllocationResult::UndefinedBehavior);
    static_assert(!(initialOutOfLineCapacity % 2));
    constexpr GPRReg upperHalf = allocator;
    constexpr GPRReg first = code;
    constexpr GPRReg second = A2;
    jit.lshiftPtr(code, TrustedImm32(3), count);
#if CPU(ARM64)
    jit.subPtr(count, oldStorage);
    jit.subPtr(TrustedImm32(sizeof(IndexingHeader)), oldStorage);
    jit.add64(storage, count, upperHalf);
    jit.move(code, count);
    CCallHelpers::Label clearsAndCopies = jit.label();
    jit.m_assembler.ldp<64>(first, second, oldStorage, PairPostIndex(2 * sizeof(EncodedJSValue)));
    jit.m_assembler.stp<64>(first, second, upperHalf, PairPostIndex(2 * sizeof(EncodedJSValue)));
    jit.m_assembler.stp<64>(ARM64Registers::zr, ARM64Registers::zr, storage, PairPostIndex(2 * sizeof(EncodedJSValue)));
    jit.branchSub32(CCallHelpers::NonZero, TrustedImm32(2), count).linkTo(clearsAndCopies, &jit);
#else
    jit.subPtr(TrustedImm32(sizeof(IndexingHeader)), oldStorage);
    jit.addPtr(count, storage);
    jit.getEffectiveAddress(CCallHelpers::BaseIndex(storage, count, CCallHelpers::TimesOne), upperHalf);
    jit.neg64(count);
    CCallHelpers::Label clearsAndCopies = jit.label();
    jit.load64(CCallHelpers::BaseIndex(oldStorage, count, CCallHelpers::TimesOne), first);
    jit.load64(CCallHelpers::BaseIndex(oldStorage, count, CCallHelpers::TimesOne, sizeof(EncodedJSValue)), second);
    jit.store64(first, CCallHelpers::BaseIndex(upperHalf, count, CCallHelpers::TimesOne));
    jit.store64(second, CCallHelpers::BaseIndex(upperHalf, count, CCallHelpers::TimesOne, sizeof(EncodedJSValue)));
    jit.store64(TrustedImm32(0), CCallHelpers::BaseIndex(storage, count, CCallHelpers::TimesOne));
    jit.store64(TrustedImm32(0), CCallHelpers::BaseIndex(storage, count, CCallHelpers::TimesOne, sizeof(EncodedJSValue)));
    jit.branchAdd64(CCallHelpers::NonZero, TrustedImm32(2 * sizeof(EncodedJSValue)), count).linkTo(clearsAndCopies, &jit);
#endif
    jit.store64(A1, Address(storage, -static_cast<int32_t>(sizeof(EncodedJSValue))));
    jit.addPtr(TrustedImm32(sizeof(IndexingHeader)), upperHalf);
    setStorageAndStructure(upperHalf);

    cannot.linkTo(stubLabels()[static_cast<unsigned>(fallbackStub)], &jit);
}
static void generatePutByNameWithNewStorage(CCallHelpers& jit) { generatePutByNameWithNewStorage(jit, Stub::PutByNameGeneric); }
static void generatePutByNameSloppyWithNewStorage(CCallHelpers& jit) { generatePutByNameWithNewStorage(jit, Stub::PutByNameSloppyGeneric); }
static void generateDefineByNameWithNewStorage(CCallHelpers& jit) { generatePutByNameWithNewStorage(jit, Stub::DefineByNameGeneric); }

constexpr GPRReg storeEntryGPR = T13;

static void generateAddInlineByName(CCallHelpers& jit)
{
    jit.load32(Address(storeEntryGPR, PropertyLookupTable::offsetOfPayloads), T10);
    jit.load8(Address(storeEntryGPR, PropertyLookupTable::offsetOfCodeInEntry), T11);
    jit.store64(A1, CCallHelpers::BaseIndex(R0, T11, CCallHelpers::TimesEight));
    jit.store32(T10, Address(R0, JSCell::structureIDOffset()));
    jit.jump().linkTo(stubLabels()[static_cast<unsigned>(Stub::WriteBarrier)], &jit);
}

static void generateAddOutOfLineByName(CCallHelpers& jit)
{
    jit.load32(Address(storeEntryGPR, PropertyLookupTable::offsetOfPayloads), T10);
    jit.load8(Address(storeEntryGPR, PropertyLookupTable::offsetOfCodeInEntry), T11);
    jit.store64(A1, outOfLineSlot(jit, R0, T11, T13, 0));
    jit.store32(T10, Address(R0, JSCell::structureIDOffset()));
    jit.jump().linkTo(stubLabels()[static_cast<unsigned>(Stub::WriteBarrier)], &jit);
}

static void generateReplaceOutOfLineByName(CCallHelpers& jit)
{
    jit.store64(A1, ownStorageSlot(jit, R0, Address(storeEntryGPR, PropertyLookupTable::offsetOfPayloads), T11, T13));
    jit.branchIfCell(A1).linkTo(stubLabels()[static_cast<unsigned>(Stub::WriteBarrier)], &jit);
    jit.ret();
}

struct PutByNameContinuations {
    CCallHelpers::Label notInlineEntry;
    CCallHelpers::Label hasKindAndCode;
    CCallHelpers::Label hasNoEntry;
    CCallHelpers::Label throughSlots;
    CCallHelpers::Label genericPath;
};
static PutByNameContinuations& putByNameContinuations(PutsByName how, Preserves preserves)
{
    static NeverDestroyed<std::array<PutByNameContinuations, 6>> continuations;
    return continuations.get()[variantOf(how, preserves)];
}

struct PutByNameStubs {
    Stub genericPath;
    Stub throughSlot;
    Stub withNewStorage;
    Stub newStorageLabel[2];
    Stub slotsLabel[2];
    Stub throughAccessor;
    Stub accessorLabel[2];
    Stub arrayLengthLabel[2];
    Stub extraPropertyLabel[2];
    Stub fieldLabel[5][2];
};
constexpr PropertyLookupTable::Kind putByNameFieldKinds[] = { PropertyLookupTable::Kind::FieldCell32, PropertyLookupTable::Kind::FieldInt32, PropertyLookupTable::Kind::FieldBoxed, PropertyLookupTable::Kind::FieldDouble, PropertyLookupTable::Kind::FieldBoolean };
static PutByNameStubs putByNameStubs(PutsByName how)
{
    switch (how) {
    case PutsByName::Strictly:
        return { Stub::PutByNameGeneric, Stub::PutThroughSlotByName, Stub::PutByNameWithNewStorage, { Stub::PutByNameAddsStorage, Stub::PutByNameAddsStoragePreservingTwo }, { Stub::PutByNameThroughSlots, Stub::PutByNameThroughSlotsPreservingTwo }, Stub::PutThroughAccessorByName, { Stub::PutByNameThroughAccessor, Stub::PutByNameThroughAccessorPreservingTwo }, { Stub::PutByNameSetsArrayLength, Stub::PutByNameSetsArrayLengthPreservingTwo }, { Stub::PutByNameStoresExtraProperty, Stub::PutByNameStoresExtraPropertyPreservingTwo }, { { Stub::PutByNameStoresFieldCell32, Stub::PutByNameStoresFieldCell32PreservingTwo }, { Stub::PutByNameStoresFieldInt32, Stub::PutByNameStoresFieldInt32PreservingTwo }, { Stub::PutByNameStoresFieldBoxed, Stub::PutByNameStoresFieldBoxedPreservingTwo }, { Stub::PutByNameStoresFieldDouble, Stub::PutByNameStoresFieldDoublePreservingTwo }, { Stub::PutByNameStoresFieldBoolean, Stub::PutByNameStoresFieldBooleanPreservingTwo } } };
    case PutsByName::Sloppily:
        return { Stub::PutByNameSloppyGeneric, Stub::PutThroughSlotByNameSloppy, Stub::PutByNameSloppyWithNewStorage, { Stub::PutByNameSloppyAddsStorage, Stub::PutByNameSloppyAddsStoragePreservingTwo }, { Stub::PutByNameSloppyThroughSlots, Stub::PutByNameSloppyThroughSlotsPreservingTwo }, Stub::PutThroughAccessorByNameSloppy, { Stub::PutByNameSloppyThroughAccessor, Stub::PutByNameSloppyThroughAccessorPreservingTwo }, { Stub::PutByNameSloppySetsArrayLength, Stub::PutByNameSloppySetsArrayLengthPreservingTwo }, { Stub::PutByNameSloppyStoresExtraProperty, Stub::PutByNameSloppyStoresExtraPropertyPreservingTwo }, { { Stub::PutByNameSloppyStoresFieldCell32, Stub::PutByNameSloppyStoresFieldCell32PreservingTwo }, { Stub::PutByNameSloppyStoresFieldInt32, Stub::PutByNameSloppyStoresFieldInt32PreservingTwo }, { Stub::PutByNameSloppyStoresFieldBoxed, Stub::PutByNameSloppyStoresFieldBoxedPreservingTwo }, { Stub::PutByNameSloppyStoresFieldDouble, Stub::PutByNameSloppyStoresFieldDoublePreservingTwo }, { Stub::PutByNameSloppyStoresFieldBoolean, Stub::PutByNameSloppyStoresFieldBooleanPreservingTwo } } };
    case PutsByName::ByDefinition:
        break;
    }
    return { Stub::DefineByNameGeneric, Stub::DefineThroughSlotByName, Stub::DefineByNameWithNewStorage, { Stub::DefineByNameAddsStorage, Stub::DefineByNameAddsStoragePreservingTwo }, { Stub::DefineByNameThroughSlots, Stub::DefineByNameThroughSlotsPreservingTwo }, Stub::DefineThroughSlotByName, { Stub::DefineByNameThroughSlots, Stub::DefineByNameThroughSlotsPreservingTwo }, { Stub::DefineByNameThroughSlots, Stub::DefineByNameThroughSlotsPreservingTwo }, { Stub::DefineByNameStoresExtraProperty, Stub::DefineByNameStoresExtraPropertyPreservingTwo }, { { Stub::DefineByNameThroughSlots, Stub::DefineByNameThroughSlotsPreservingTwo }, { Stub::DefineByNameThroughSlots, Stub::DefineByNameThroughSlotsPreservingTwo }, { Stub::DefineByNameThroughSlots, Stub::DefineByNameThroughSlotsPreservingTwo }, { Stub::DefineByNameThroughSlots, Stub::DefineByNameThroughSlotsPreservingTwo }, { Stub::DefineByNameThroughSlots, Stub::DefineByNameThroughSlotsPreservingTwo } } };
}

static void storeExtraProperty(CCallHelpers& jit, GPRReg entry, CCallHelpers::JumpList& cannot, bool isDefinition)
{
    constexpr GPRReg extraProperties = T9;
    constexpr GPRReg payload = T10;
    constexpr GPRReg code = T11;
    constexpr GPRReg known = T12;
    RELEASE_ASSERT(noOverlap(R0, A1, entry, extraProperties, payload, code, known));
    auto branchIfBarrierIsNeeded = [&](GPRReg cell, GPRReg scratch) {
        jit.load8(Address(cell, JSCell::cellStateOffset()), scratch);
        return jit.branch32(CCallHelpers::BelowOrEqual, scratch, Address(instanceGPR, Instance::offsetOfBarrierThreshold()));
    };
    auto loadNewStructureFlags = [&] {
        jit.and32(TrustedImm32(~(PropertyLookupTable::newStructureFlags | PropertyLookupTable::payloadIsSlots)), payload, known);
        structureWithID(jit, known);
        jit.load64(Address(known, Structure::offsetOfExtraPropertiesStructureID()), known);
    };
    auto loadExtraPropertiesOffset = [&](GPRReg result) {
        jit.urshift64(known, TrustedImm32(Structure::extraPropertiesOffsetShift), result);
        jit.and32(TrustedImm32(UINT16_MAX), result);
    };
    jit.load8(Address(entry, PropertyLookupTable::offsetOfCodeInEntry), code);
    jit.load32(Address(entry, PropertyLookupTable::offsetOfPayloads), payload);
    uint32_t mayBeReplaced = isDefinition ? PropertyLookupTable::extraPropertyHasDefaultAttributes : PropertyLookupTable::extraPropertyIsWritten;
    Jump notInlineAfterReference = jit.branch32(CCallHelpers::AboveOrEqual, code, TrustedImm32(PropertyLookupTable::firstOutOfLineExtraPropertyCode));
    cannot.append(jit.branchTest32(CCallHelpers::Zero, payload, TrustedImm32(mayBeReplaced)));
    jit.urshift32(TrustedImm32(PropertyLookupTable::extraPropertiesOffsetShift), payload);
    jit.load32(CCallHelpers::BaseIndex(R0, payload, CCallHelpers::TimesOne), payload);
    decodeCell32(jit, payload, payload);
    jit.store64(A1, CCallHelpers::BaseIndex(payload, code, CCallHelpers::TimesEight));
    CCallHelpers::Label isStored = jit.label();
    Jump notCell = jit.branchIfNotCell(A1);
    jit.move(payload, R0);
    jit.jump().linkTo(stubLabels()[static_cast<unsigned>(Stub::WriteBarrier)], &jit);
    notCell.link(&jit);
    jit.ret();

    notInlineAfterReference.link(&jit);
    Jump adds = jit.branchTest32(CCallHelpers::NonZero, code, TrustedImm32(PropertyLookupTable::storeAddsExtraProperty));
    cannot.append(jit.branchTest32(CCallHelpers::Zero, payload, TrustedImm32(mayBeReplaced)));
    loadExtraProperties(jit, R0, payload, known, cannot);
    jit.and32(TrustedImm32(PropertyLookupTable::extraPropertyUsesHandle - 1), code);
    Jump isOutOfLine = jit.branch32(CCallHelpers::AboveOrEqual, code, TrustedImm32(PropertyLookupTable::firstOutOfLineExtraPropertyCode));
    jit.store64(A1, CCallHelpers::BaseIndex(payload, code, CCallHelpers::TimesEight));
    jit.jump().linkTo(isStored, &jit);
    isOutOfLine.link(&jit);
    jit.store64(A1, outOfLineSlot(jit, payload, code, known, PropertyLookupTable::firstOutOfLineExtraPropertyCode));
    jit.jump().linkTo(isStored, &jit);

    adds.link(&jit);
    if (!isDefinition)
        cannot.append(jit.branchTest32(CCallHelpers::NonZero, code, TrustedImm32(PropertyLookupTable::onlyDefinitionAddsExtraProperty)));
    cannot.append(branchIfBarrierIsNeeded(R0, extraProperties));
    loadNewStructureFlags();
    Jump makes = jit.branchTest32(CCallHelpers::NonZero, payload, TrustedImm32(PropertyLookupTable::storeCreatesExtraProperties));
    loadExtraPropertiesOffset(extraProperties);
    Jump extraPropertiesViaHandle = jit.branchTest32(CCallHelpers::Zero, extraProperties);
    jit.load32(CCallHelpers::BaseIndex(R0, extraProperties, CCallHelpers::TimesOne), extraProperties);
    decodeCell32(jit, extraProperties, extraProperties);
    CCallHelpers::Label areLoaded = jit.label();
    cannot.append(branchIfBarrierIsNeeded(extraProperties, code));
    jit.load8(Address(entry, PropertyLookupTable::offsetOfCodeInEntry), code);
    jit.and32(TrustedImm32(PropertyLookupTable::onlyDefinitionAddsExtraProperty - 1), code);
    jit.and32(TrustedImm32(~(PropertyLookupTable::newStructureFlags | PropertyLookupTable::payloadIsSlots)), payload);
    Jump isAddedOutOfLine = jit.branch32(CCallHelpers::AboveOrEqual, code, TrustedImm32(PropertyLookupTable::firstOutOfLineExtraPropertyCode));
    jit.store32(known, Address(extraProperties, JSCell::structureIDOffset()));
    jit.store32(payload, Address(R0, JSCell::structureIDOffset()));
    jit.store64(A1, CCallHelpers::BaseIndex(extraProperties, code, CCallHelpers::TimesEight));
    jit.ret();

    isAddedOutOfLine.link(&jit);
    constexpr size_t sizeOfFirstStorage = initialOutOfLineCapacity * sizeof(EncodedJSValue);
    Jump hasStorage = jit.branchTestPtr(CCallHelpers::NonZero, Address(extraProperties, JSObject::butterflyOffset()));
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfAuxiliarySpace()), code);
    jit.loadPtr(Address(code, CompleteSubspace::offsetOfAllocatorForSizeStep() + MarkedSpace::sizeClassToIndex(sizeOfFirstStorage) * sizeof(Allocator)), code);
    cannot.append(jit.branchTestPtr(CCallHelpers::Zero, code));
    jit.emitAllocateWithNonNullAllocator(payload, JITAllocator::variable(), code, known, cannot, CCallHelpers::SlowAllocationResult::UndefinedBehavior);
    for (unsigned i = 0; i < initialOutOfLineCapacity; ++i)
        jit.store64(TrustedImm32(0), Address(payload, i * sizeof(EncodedJSValue)));
    jit.addPtr(TrustedImm32(sizeOfFirstStorage + sizeof(IndexingHeader)), payload);
    jit.storePtr(payload, Address(extraProperties, JSObject::butterflyOffset()));
    jit.load32(Address(entry, PropertyLookupTable::offsetOfPayloads), payload);
    loadNewStructureFlags();
    jit.and32(TrustedImm32(~(PropertyLookupTable::newStructureFlags | PropertyLookupTable::payloadIsSlots)), payload);
    jit.load8(Address(entry, PropertyLookupTable::offsetOfCodeInEntry), code);
    jit.and32(TrustedImm32(PropertyLookupTable::onlyDefinitionAddsExtraProperty - 1), code);
    hasStorage.link(&jit);
    jit.store32(known, Address(extraProperties, JSCell::structureIDOffset()));
    jit.store32(payload, Address(R0, JSCell::structureIDOffset()));
    jit.store64(A1, outOfLineSlot(jit, extraProperties, code, known, PropertyLookupTable::firstOutOfLineExtraPropertyCode));
    jit.ret();

    extraPropertiesViaHandle.link(&jit);
    loadExtraPropertiesViaHandle(jit, R0, extraProperties, code, cannot);
    jit.jump().linkTo(areLoaded, &jit);

    makes.link(&jit);
    constexpr GPRReg allocator = code;
    constexpr GPRReg scratch = payload;
    static_assert(MarkedSpace::sizeStep == 2 * sizeof(Allocator));
    cannot.append(jit.branchTest32(CCallHelpers::NonZero, Address(R0, Typed::offsetOfOrderWord), TrustedImm32(Typed::orderWordIsNotExtensible)));
    jit.urshift64(known, TrustedImm32(Structure::extraPropertiesSizeShift + 1), scratch);
    jit.loadPtr(Address(instanceGPR, Instance::offsetOfCellSpace()), allocator);
    jit.loadPtr(CCallHelpers::BaseIndex(allocator, scratch, CCallHelpers::TimesOne, CompleteSubspace::offsetOfAllocatorForSizeStep()), allocator);
    cannot.append(jit.branchTestPtr(CCallHelpers::Zero, allocator));
    jit.emitAllocateWithNonNullAllocator(extraProperties, JITAllocator::variable(), allocator, scratch, cannot, CCallHelpers::SlowAllocationResult::UndefinedBehavior);
    jit.store32(known, Address(extraProperties, JSCell::structureIDOffset()));
    jit.store32(TrustedImm32(JSFinalObject::defaultTypeInfoBlob()), Address(extraProperties, JSCell::indexingTypeAndMiscOffset()));
    jit.storePtr(CCallHelpers::TrustedImmPtr(nullptr), Address(extraProperties, JSObject::butterflyOffset()));
    jit.store64(A1, Address(extraProperties, JSObject::offsetOfInlineStorage()));
    constexpr GPRReg end = code;
    jit.urshift64(known, TrustedImm32(Structure::extraPropertiesSizeShift), end);
    CCallHelpers::Label clears = jit.label();
    jit.sub32(TrustedImm32(sizeof(EncodedJSValue)), end);
    jit.store64(TrustedImm32(0), CCallHelpers::BaseIndex(extraProperties, end, CCallHelpers::TimesOne));
    jit.branch32(CCallHelpers::Above, end, TrustedImm32(JSObject::offsetOfInlineStorage() + sizeof(EncodedJSValue))).linkTo(clears, &jit);
    fenceAfterAllocation(jit, scratch);
    loadExtraPropertiesOffset(code);
    Jump needsHandle = jit.branchTest32(CCallHelpers::Zero, code);
    encodeCell32(jit, extraProperties, scratch);
    jit.store32(scratch, CCallHelpers::BaseIndex(R0, code, CCallHelpers::TimesOne));
    jit.or32(TrustedImm32(Typed::orderWordHasExtraProperties), Address(R0, Typed::offsetOfOrderWord));
    CCallHelpers::Label hasReference = jit.label();
    jit.load32(Address(entry, PropertyLookupTable::offsetOfPayloads), payload);
    jit.and32(TrustedImm32(~(PropertyLookupTable::newStructureFlags | PropertyLookupTable::payloadIsSlots)), payload);
    jit.store32(payload, Address(R0, JSCell::structureIDOffset()));
    jit.ret();

    needsHandle.link(&jit);
    auto loadEmptyHandle = [&](GPRReg result) {
        jit.loadPtr(Address(instanceGPR, Instance::offsetOfTypedExtraPropertiesHandleSegments()), result);
        jit.loadPtr(Address(result), result);
    };
    loadEmptyHandle(scratch);
    jit.load32(Address(scratch, OBJECT_OFFSETOF(Typed::ExtraPropertiesHandle, nextFree)), code);
    cannot.append(jit.branchTest32(CCallHelpers::Zero, code));
    jit.move(code, known);
    loadExtraPropertiesHandleAt(jit, known, scratch);
    jit.load32(Address(scratch, OBJECT_OFFSETOF(Typed::ExtraPropertiesHandle, nextFree)), known);
    jit.storePtr(R0, Address(scratch, OBJECT_OFFSETOF(Typed::ExtraPropertiesHandle, object)));
    jit.storePtr(extraProperties, Address(scratch, OBJECT_OFFSETOF(Typed::ExtraPropertiesHandle, extraProperties)));
    loadEmptyHandle(extraProperties);
    jit.store32(known, Address(extraProperties, OBJECT_OFFSETOF(Typed::ExtraPropertiesHandle, nextFree)));
    jit.load32(Address(R0, Typed::offsetOfOrderWord), known);
    jit.and32(TrustedImm32(Typed::orderAndCountMask), known, extraProperties);
    jit.store32(extraProperties, Address(scratch, OBJECT_OFFSETOF(Typed::ExtraPropertiesHandle, orderAndCount)));
    jit.and32(TrustedImm32(static_cast<int32_t>(~Typed::orderAndCountMask)), known);
    jit.or32(code, known);
    jit.or32(TrustedImm32(Typed::orderWordHasExtraProperties), known);
    jit.store32(known, Address(R0, Typed::offsetOfOrderWord));
    jit.jump().linkTo(hasReference, &jit);
}

static void setArrayLength(CCallHelpers& jit, GPRReg entry, CCallHelpers::JumpList& cannot)
{
    constexpr GPRReg hole = T9;
    constexpr GPRReg newLength = T10;
    constexpr GPRReg butterfly = T11;
    constexpr GPRReg length = T12;
    constexpr unsigned maxUnrolledClearLength = 64;
    RELEASE_ASSERT(noOverlap(R0, A1, entry, hole, newLength, butterfly, length));
    cannot.append(jit.branchIfNotInt32(A1));
    jit.zeroExtend32ToWord(A1, newLength);
    cannot.append(jit.branch32(CCallHelpers::LessThan, newLength, TrustedImm32(0)));
    jit.loadPtr(Address(R0, JSObject::butterflyOffset()), butterfly);
    jit.load32(Address(butterfly, Butterfly::offsetOfPublicLength()), length);
    Jump isShorter = jit.branch32(CCallHelpers::Below, newLength, length);
    cannot.append(jit.branch32(CCallHelpers::Above, newLength, Address(butterfly, Butterfly::offsetOfVectorLength())));
    jit.store32(newLength, Address(butterfly, Butterfly::offsetOfPublicLength()));
    jit.ret();

    isShorter.link(&jit);
    jit.sub32(length, newLength, hole);
    cannot.append(jit.branch32(CCallHelpers::Above, hole, TrustedImm32(maxUnrolledClearLength)));
    jit.load8(Address(entry, PropertyLookupTable::offsetOfCodeInEntry), hole);
    Jump hasNoDoubles = jit.branchTest32(CCallHelpers::Zero, hole);
    jit.move(CCallHelpers::TrustedImm64(std::bit_cast<int64_t>(PNaN)), hole);
    hasNoDoubles.link(&jit);
    CCallHelpers::Label clears = jit.label();
    jit.sub32(TrustedImm32(1), length);
    jit.store64(hole, CCallHelpers::BaseIndex(butterfly, length, CCallHelpers::TimesEight));
    jit.branch32(CCallHelpers::Above, length, newLength).linkTo(clears, &jit);
    jit.store32(newLength, Address(butterfly, Butterfly::offsetOfPublicLength()));
    jit.ret();
}

#if CPU(X86_64)
static void replaceInline(CCallHelpers& jit, Address destination, CCallHelpers::JumpList& isNotWritable)
{
    jit.load8(destination, T11);
    isNotWritable.append(jit.branchTest32(CCallHelpers::Zero, T11));
    jit.store64(A1, CCallHelpers::BaseIndex(R0, T11, CCallHelpers::TimesEight));
    jit.branchIfCell(A1).linkTo(stubLabels()[static_cast<unsigned>(Stub::WriteBarrier)], &jit);
    jit.ret();
}
#else
static Jump storeInlineByCell(CCallHelpers& jit)
{
    extractBits(jit, nameCellGPR, kindInCellShift, 8, T11);
    Jump isReadOnly = jit.branchTest32(CCallHelpers::Zero, T11);
    jit.store64(A1, CCallHelpers::BaseIndex(R0, T11, CCallHelpers::TimesEight));
    jit.branchIfCell(A1).linkTo(stubLabels()[static_cast<unsigned>(Stub::WriteBarrier)], &jit);
    jit.ret();
    return isReadOnly;
}
#endif

static void emitTypedFieldStoreFromEntry(CCallHelpers& jit, GPRReg entry, PropertyLookupTable::Kind kind, CCallHelpers::JumpList& cannot)
{
    using FieldWrite = Slot::FieldWrite;
    constexpr GPRReg pointer = T9;
    constexpr GPRReg description = T10;
    constexpr GPRReg scratch = T11;
    RELEASE_ASSERT(noOverlap(R0, A1, entry, pointer, description, scratch, T12));
    jit.load32(Address(entry, PropertyLookupTable::offsetOfPayloads), description);
    cannot.append(jit.branchTest32(CCallHelpers::Zero, description, TrustedImm32(PropertyLookupTable::payloadIsSlots)));
    loadSlotFromPayload(jit, description, PropertyLookupTable::Access::Store, pointer, scratch);
    jit.load64(slotWord(pointer, 0), scratch);
    cannot.append(branchIfStructureDiffers(jit, R0, scratch));
    cannot.append(branchUnlessSlotHas<Slot::pointerIsNotCell>(jit, scratch));
    jit.load64(slotWord(pointer, 1), pointer);
    jit.urshift64(pointer, TrustedImm32(32), description);
    uint32_t kept = 0;
    uint32_t significantRepresentationBits = FieldWrite::representationMask;
    switch (kind) {
    case PropertyLookupTable::Kind::FieldCell32:
        kept = FieldWrite::Cell32;
        break;
    case PropertyLookupTable::Kind::FieldInt32:
        static_assert((FieldWrite::Int32OrNumberBox & FieldWrite::Int32) == FieldWrite::Int32OrNumberBox && (FieldWrite::Int32OrNumberBox | 4) == FieldWrite::Int32);
        kept = FieldWrite::Int32OrNumberBox;
        significantRepresentationBits = FieldWrite::representationMask & ~4u;
        break;
    case PropertyLookupTable::Kind::FieldBoxed:
        kept = FieldWrite::Boxed;
        break;
    case PropertyLookupTable::Kind::FieldDouble:
        kept = FieldWrite::Double;
        break;
    case PropertyLookupTable::Kind::FieldBoolean:
        kept = FieldWrite::Boolean;
        break;
    default:
        RELEASE_ASSERT_NOT_REACHED();
    }
    constexpr uint32_t otherStoreFlags = FieldWrite::isNotField | FieldWrite::isInGlobalProxyTarget | static_cast<uint32_t>(Slot::isStoreTransition >> 32);
    jit.and32(TrustedImm32(static_cast<int32_t>(FieldWrite::isFieldWrite | otherStoreFlags | significantRepresentationBits)), description, scratch);
    cannot.append(jit.branch32(CCallHelpers::NotEqual, scratch, TrustedImm32(static_cast<int32_t>(FieldWrite::isFieldWrite | kept))));
    storeCompiledField(jit, cannot, nullptr, nullptr, kind);
}

static void generatePutByNameWith(CCallHelpers& jit, PutsByName how, Preserves preserves)
{
    constexpr GPRReg name = T9;
    constexpr GPRReg entry = storeEntryGPR;
    constexpr GPRReg slot = T13;
    PropertyLookupTable::Access access = how == PutsByName::ByDefinition ? PropertyLookupTable::Access::Define : PropertyLookupTable::Access::Store;
    PutByNameStubs stubs = putByNameStubs(how);
    PutByNameContinuations& continuations = putByNameContinuations(how, preserves);
    ptrdiff_t handlers = Instance::offsetOfPutByNameHandlers(variantOf(how, preserves));
    CCallHelpers::Label writeBarrier = stubLabels()[static_cast<unsigned>(Stub::WriteBarrier)];
    CCallHelpers::JumpList genericPath;
    CCallHelpers::JumpList throughSlots;
    genericPath.append(jit.branchIfNotCell(R0));
    loadRowByName(jit, R0, T13, T11);
    jit.and32(TrustedImm32(PropertyLookupTable::numberOfColumns - 1), name, T11);
    CCallHelpers::JumpList hasNoEntry;
#if CPU(X86_64)
    jit.m_assembler.cmpw_rm(name, PropertyLookupTable::offsetOfFirstColumn + PropertyLookupTable::offsetOfNameInEntry, T13, T11, CCallHelpers::TimesEight);
    Jump notInlineEntry = Jump(jit.m_assembler.jCC(X86Assembler::ConditionNE));
    jit.load8(CCallHelpers::BaseIndex(T13, T11, CCallHelpers::TimesEight, PropertyLookupTable::offsetOfFirstColumn + PropertyLookupTable::offsetOfStoreOffsetInEntry), T10);
    hasNoEntry.append(jit.branchTest32(CCallHelpers::Zero, T10));
    jit.store64(A1, CCallHelpers::BaseIndex(R0, T10, CCallHelpers::TimesEight));
    jit.branchIfCell(A1).linkTo(writeBarrier, &jit);
    jit.ret();
    notInlineEntry.link(&jit);
    jit.getEffectiveAddress(CCallHelpers::BaseIndex(T13, T11, CCallHelpers::TimesEight, PropertyLookupTable::offsetOfFirstColumn), entry);
    jit.load16(Address(entry, PropertyLookupTable::offsetOfNameInEntry), T11);
    jit.xor32(name, T11);
    hasNoEntry.append(jit.branch32(CCallHelpers::NotEqual, T11, TrustedImm32(PropertyLookupTable::hasKindAndCode)));
    jumpToEntryHandler(jit, entry, T11, handlers);
#else
    auto hasFlag = [&](unsigned shift, uint8_t flag) { return CCallHelpers::TrustedImm64(static_cast<int64_t>(flag) << shift); };
    jit.load64(CCallHelpers::BaseIndex(T13, T11, CCallHelpers::TimesEight, PropertyLookupTable::offsetOfFirstColumn), nameCellGPR);
    Jump notInlineEntry = branchIfCellNameDiffers(jit, name);
    hasNoEntry.append(storeInlineByCell(jit));

    notInlineEntry.link(&jit);
    continuations.notInlineEntry = jit.label();
    hasNoEntry.append(branchIfCellHasNoEntry(jit));
    continuations.hasKindAndCode = jit.label();
    Jump needsNoHandler = jit.branchTest64(CCallHelpers::NonZero, nameCellGPR, hasFlag(kindInCellShift, PropertyLookupTable::storeNeedsNoHandler));
    CCallHelpers::Label needsHandler = jit.label();
    extractBits(jit, nameCellGPR, nameInCellShift, WTF::fastLog2(PropertyLookupTable::numberOfColumns), T11);
    jit.getEffectiveAddress(CCallHelpers::BaseIndex(T13, T11, CCallHelpers::TimesEight, PropertyLookupTable::offsetOfFirstColumn), entry);
    extractBits(jit, nameCellGPR, kindInCellShift, PropertyLookupTable::bitsOfKind, T11);
    jit.farJump(CCallHelpers::BaseIndex(instanceGPR, T11, CCallHelpers::TimesEight, static_cast<int32_t>(handlers)), JITThunkPtrTag);

    needsNoHandler.link(&jit);
    Jump isReplacedInStorage = jit.branchTest64(CCallHelpers::NonZero, nameCellGPR, hasFlag(kindInCellShift, PropertyLookupTable::valueIsInStorage));
    if (how != PutsByName::ByDefinition)
        jit.branchTest64(CCallHelpers::Zero, nameCellGPR, hasFlag(codeInCellShift, PropertyLookupTable::storesAlsoAdd)).linkTo(needsHandler, &jit);
    extractBits(jit, nameCellGPR, codeInCellShift, 7, T11);
    jit.store64(A1, CCallHelpers::BaseIndex(R0, T11, CCallHelpers::TimesEight));
    jit.store32(nameCellGPR, Address(R0, JSCell::structureIDOffset()));
    jit.jump().linkTo(writeBarrier, &jit);

    isReplacedInStorage.link(&jit);
    jit.loadPtr(Address(R0, JSObject::butterflyOffset()), T13);
    jit.m_assembler.str<64>(A1, T13, nameCellGPR, ARM64Assembler::SXTW, 0);
    jit.branchIfCell(A1).linkTo(writeBarrier, &jit);
    jit.ret();

#endif

    setLabelOf(jit, stubs.newStorageLabel[static_cast<unsigned>(preserves)]);
    loadEntryName(jit, entry, name);
    jit.load32(Address(entry, PropertyLookupTable::offsetOfPayloads), T10);
    jit.load8(Address(entry, PropertyLookupTable::offsetOfCodeInEntry), T11);
    callStubPreservingRegisters(jit, stubs.withNewStorage, preserves, [&] {
        jit.move(name, A2);
    });

    if (how != PutsByName::ByDefinition) {
        setLabelOf(jit, stubs.accessorLabel[static_cast<unsigned>(preserves)]);
        callStubPreservingRegisters(jit, stubs.throughAccessor, preserves, [] { });

        setLabelOf(jit, stubs.arrayLengthLabel[static_cast<unsigned>(preserves)]);
        setArrayLength(jit, entry, throughSlots);

    }
    setLabelOf(jit, stubs.extraPropertyLabel[static_cast<unsigned>(preserves)]);
    storeExtraProperty(jit, entry, throughSlots, how == PutsByName::ByDefinition);

    if (how != PutsByName::ByDefinition) {
        for (unsigned i = 0; i < std::size(putByNameFieldKinds); ++i) {
            setLabelOf(jit, stubs.fieldLabel[i][static_cast<unsigned>(preserves)]);
            emitTypedFieldStoreFromEntry(jit, entry, putByNameFieldKinds[i], throughSlots);
        }
    }

    continuations.hasNoEntry = jit.label();
    genericPath.append(jit.branchIfNotCell(R0));
    hasNoEntry.link(&jit);
    CCallHelpers::Label searchOverflow = jit.label();
    loadRowByName(jit, R0, T13, T11);
    findEntryInOverflow(jit, name, T13, T11, genericPath);

    throughSlots.link(&jit);
    continuations.throughSlots = jit.label();
    setLabelOf(jit, stubs.slotsLabel[static_cast<unsigned>(preserves)]);
    loadEntryName(jit, entry, name);
    jit.load32(Address(entry, PropertyLookupTable::offsetOfPayloads), T10);
    Jump hasNoSlots = jit.branchTest32(CCallHelpers::Zero, T10, TrustedImm32(PropertyLookupTable::payloadIsSlots));
    loadSlotFromPayload(jit, T10, access, slot, T11);
    jit.load64(slotWord(slot, 0), T11);
    genericPath.append(branchIfStructureDiffers(jit, R0, T11));
    Jump needsMore = jit.branchTest32(CCallHelpers::NonZero, slotWord(slot, 1).withOffset(sizeof(uint32_t)), TrustedImm32(-1));
    jit.load32(slotWord(slot, 1), T10);
    Jump structureIsUnchanged = jit.branchTest32(CCallHelpers::Zero, T10);
    locateCachedProperty(jit, R0, T11, T13);
    jit.store64(A1, CCallHelpers::BaseIndex(T13, T11, CCallHelpers::TimesEight));
    jit.store32(T10, Address(R0, JSCell::structureIDOffset()));
    jit.jump().linkTo(writeBarrier, &jit);

    structureIsUnchanged.link(&jit);
    locateCachedProperty(jit, R0, T11, T13);
    jit.store64(A1, CCallHelpers::BaseIndex(T13, T11, CCallHelpers::TimesEight));
    jit.branchIfCell(A1).linkTo(writeBarrier, &jit);
    jit.ret();

    needsMore.link(&jit);
    callStubPreservingRegisters(jit, stubs.throughSlot, preserves, [&] {
        jit.move(slot, A2);
    });

    hasNoSlots.link(&jit);
    jit.branch8(CCallHelpers::Equal, Address(entry, PropertyLookupTable::offsetOfKindInEntry), TrustedImm32(static_cast<uint8_t>(PropertyLookupTable::Kind::OutOfLine) | PropertyLookupTable::flagsForKind(PropertyLookupTable::Kind::OutOfLine))).linkTo(searchOverflow, &jit);
    genericPath.link(&jit);
    continuations.genericPath = jit.label();
    callStubPreservingRegisters(jit, stubs.genericPath, preserves, [&] {
        jit.move(name, A2);
    });
}
static void generatePutByName(CCallHelpers& jit) { generatePutByNameWith(jit, PutsByName::Strictly, Preserves::Nothing); }
