    isHole.link(&jit);
    jit.move64ToDouble(savedNumber, number);
    jit.move64ToDouble(savedScratch, scratch);
    absent.link(&jit);
    genericPath.append(jit.branch8(CCallHelpers::NotEqual, Address(A1, JSCell::typeInfoTypeOffset()), TrustedImm32(ArrayType)));
