static void generateGetByNameAs(CCallHelpers& jit, bool keepsTwoIntegers, ReadAs kind, bool acceptsUndefined = false, bool acceptsNull = false)
{
    constexpr GPRReg name = T9;
    CCallHelpers::JumpList typeMismatch;
    auto callWithinFrame = [&](std::optional<Stub> stubOrEntryHandler) {
        jit.emitFunctionPrologue();
        if (keepsTwoIntegers) {
#if CPU(X86_64)
            jit.push(preservedIntegerGPRs[0]);
            jit.push(preservedIntegerGPRs[1]);
#else
            jit.pushPair(preservedIntegerGPRs[0], preservedIntegerGPRs[1]);
#endif
        }
        if (stubOrEntryHandler)
            callStubFromStub(jit, *stubOrEntryHandler);
        else {
            jit.move(T13, readEntryGPR);
            jit.loadPtr(CCallHelpers::BaseIndex(instanceGPR, T11, CCallHelpers::TimesEight, static_cast<int32_t>(Instance::offsetOfGetByNameHandlers(static_cast<unsigned>(Preserves::NothingWithinFrame)))), T11);
            jit.call(T11, JITThunkPtrTag);
        }
        if (keepsTwoIntegers) {
#if CPU(X86_64)
            jit.pop(preservedIntegerGPRs[1]);
            jit.pop(preservedIntegerGPRs[0]);
#else
            jit.popPair(preservedIntegerGPRs[0], preservedIntegerGPRs[1]);
#endif
        }
        jit.emitFunctionEpilogueWithEmptyFrame();
    };
    Jump notCell = jit.branchIfNotCell(R0);
    loadRowByName(jit, R0, T13, T11);
    jit.and32(TrustedImm32(PropertyLookupTable::numberOfColumns - 1), name, T11);
#if CPU(X86_64)
    jit.m_assembler.cmpw_rm(name, PropertyLookupTable::offsetOfFirstColumn + PropertyLookupTable::offsetOfNameInEntry, T13, T11, CCallHelpers::TimesEight);
    Jump notInlineEntry = Jump(jit.m_assembler.jCC(X86Assembler::ConditionNE));
    jit.load32(CCallHelpers::BaseIndex(T13, T11, CCallHelpers::TimesEight, PropertyLookupTable::offsetOfFirstColumn + PropertyLookupTable::offsetOfReadOffsetInEntry), T11);
    jit.load64(CCallHelpers::BaseIndex(R0, T11, CCallHelpers::TimesEight), R0);
    endReadAs(jit, kind, acceptsUndefined, acceptsNull, typeMismatch);

    notInlineEntry.link(&jit);
    jit.getEffectiveAddress(CCallHelpers::BaseIndex(T13, T11, CCallHelpers::TimesEight, PropertyLookupTable::offsetOfFirstColumn), T13);
    jit.load16(Address(T13, PropertyLookupTable::offsetOfNameInEntry), T11);
    jit.xor32(name, T11);
    Jump hasNoEntry = jit.branch32(CCallHelpers::NotEqual, T11, TrustedImm32(PropertyLookupTable::hasKindAndCode));
    jit.load8(Address(T13, PropertyLookupTable::offsetOfKindInEntry), T11);
#else
    jit.load64(CCallHelpers::BaseIndex(T13, T11, CCallHelpers::TimesEight, PropertyLookupTable::offsetOfFirstColumn), nameCellGPR);
    Jump notInlineEntry = branchIfCellNameDiffers(jit, name);
    jit.m_assembler.ldr<64>(R0, R0, nameCellGPR, ARM64Assembler::UXTW, 3);
    endReadAs(jit, kind, acceptsUndefined, acceptsNull, typeMismatch);

    notInlineEntry.link(&jit);
    Jump hasNoEntry = branchIfCellHasNoEntry(jit);
    jit.getEffectiveAddress(CCallHelpers::BaseIndex(T13, T11, CCallHelpers::TimesEight, PropertyLookupTable::offsetOfFirstColumn), T13);
    extractBits(jit, nameCellGPR, kindInCellShift, PropertyLookupTable::bitsOfKind, T11);
#endif
    using Kind = PropertyLookupTable::Kind;
    CCallHelpers::JumpList isRead;
    static_assert(!static_cast<unsigned>(Kind::Absent) && PropertyLookupTable::impliesAbsent(Kind::AbsentAndStoreAddsInNewStorage) && !PropertyLookupTable::impliesAbsent(static_cast<Kind>(static_cast<unsigned>(Kind::AbsentAndStoreAddsInNewStorage) + 1)));
    Jump isAbsent = jit.branch32(CCallHelpers::BelowOrEqual, T11, TrustedImm32(static_cast<unsigned>(Kind::AbsentAndStoreAddsInNewStorage)));
    callWithinFrame(std::nullopt);
    endReadAs(jit, kind, acceptsUndefined, acceptsNull, typeMismatch);

    isAbsent.link(&jit);
    jit.move(CCallHelpers::TrustedImm64(JSValue::ValueUndefined), R0);
    if (!acceptsUndefined)
        typeMismatch.append(jit.jump());
    else {
        if (kind == ReadAs::Double) {
            jit.move(CCallHelpers::TrustedImm64(Typed::undefinedDouble), R0);
            jit.move64ToDouble(R0, FPRInfo::fpRegT0);
        }
        jit.ret();
    }

    hasNoEntry.link(&jit);
    callWithinFrame(Stub::GetByNameWithinFrameAfterFirstProbe);
    isRead.append(jit.jump());

    notCell.link(&jit);
    callWithinFrame(Stub::GetByNameWithinFrame);
    isRead.link(&jit);
    endReadAs(jit, kind, acceptsUndefined, acceptsNull, typeMismatch);

    typeMismatch.link(&jit);
    s_callsBetweenStubs->append({ jit.nearTailCall(), Stub::ThrowAtSite });
}
